    fn srpt_hiku2_ocs_queue_route(self, queue_density: f32) -> Option<&'static str> {
        self.srpt_hiku2_ocs_queue_density_threshold()
            .map(|threshold| {
                if queue_density < threshold {
                    "srpt_ready_hiku2_ocs_borda"
                } else {
                    "srpt_ready_ocs_current_demand"
                }
            })
    }

