struct FaasrankOperationalComponents {
    cpu_headroom: f32,
    memory_headroom: f32,
    locality: f32,
    warm_affinity: f32,
    load_balance: f32,
    diversity: f32,
}

impl FaasrankOperationalComponents {
    fn weighted_score(self) -> f32 {
        0.25 * self.cpu_headroom
            + 0.20 * self.memory_headroom
            + 0.15 * self.locality
            + 0.25 * self.warm_affinity
            + 0.15 * self.load_balance
            - 0.05 * self.diversity
    }
}

