    fn capture_v137_native_shadow(
        &mut self,
        env: &SimEnvObserve,
        mech: &MechanismImpl,
    ) -> Option<NativeShadowCapture> {
        let kind = self
            .settings
            .operational_expert_proxy
            .native_shadow_anchor_kind()?;
        assert!(
            self.settings.operational_direct_initialization,
            "V137 native shadow profiles require NASH_OPERATIONAL_DIRECT_INITIALIZATION=true"
        );
        Some(self.capture_native_shadow_kind(kind, env, mech))
    }

    fn capture_native_shadow_kind(
        &mut self,
        kind: NativeShadowAnchorKind,
        env: &SimEnvObserve,
        mech: &MechanismImpl,
    ) -> NativeShadowCapture {
        let (sender, receiver) = mpsc::channel();
        let v144 = self
            .settings
            .operational_expert_proxy
            .uses_causal_burst_morphology_router();
        let v145 = self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_router();
        let v149 = self
            .settings
            .operational_expert_proxy
            .uses_causal_steady_load_closure();
        match kind {
            NativeShadowAnchorKind::Hash => {
                if v144 {
                    self.v144_hash_shadow_invocations =
                        self.v144_hash_shadow_invocations.saturating_add(1);
                }
                self.v144_hash_shadow.schedule_some(env, mech, &sender)
            }
            NativeShadowAnchorKind::Random => {
                let algorithm_seed = env.help().config().algorithm_seed();
                if self.v141_random_shadow_seed.as_deref() != Some(algorithm_seed) {
                    self.v141_random_shadow =
                        Some(RandomScheduler::from_algorithm_seed(algorithm_seed));
                    self.v141_random_shadow_seed = Some(algorithm_seed.to_string());
                    self.v141_random_shadow_initializations =
                        self.v141_random_shadow_initializations.saturating_add(1);
                }
                self.v141_random_shadow_invocations =
                    self.v141_random_shadow_invocations.saturating_add(1);
                self.v141_random_shadow
                    .as_mut()
                    .expect("V141 Random shadow must be initialized")
                    .schedule_some(env, mech, &sender);
            }
            NativeShadowAnchorKind::Faasrank => {
                if self.v143_faasrank_shadow.is_none() {
                    self.v143_faasrank_shadow = Some(FaaSRankScheduler::new(
                        &env.help().config().experiment.faasrank_model,
                    ));
                    self.v143_faasrank_shadow_initializations =
                        self.v143_faasrank_shadow_initializations.saturating_add(1);
                }
                if v144 {
                    self.v144_faasrank_shadow_invocations =
                        self.v144_faasrank_shadow_invocations.saturating_add(1);
                }
                if v145 {
                    self.v145_faasrank_shadow_invocations =
                        self.v145_faasrank_shadow_invocations.saturating_add(1);
                }
                if v149 {
                    self.v149_faasrank_selected_invocations =
                        self.v149_faasrank_selected_invocations.saturating_add(1);
                }
                self.v143_faasrank_shadow
                    .as_mut()
                    .expect("V143 FaaSRank shadow must be initialized")
                    .schedule_some(env, mech, &sender);
            }
            NativeShadowAnchorKind::Greedy => {
                if v144 {
                    self.v144_greedy_shadow_invocations =
                        self.v144_greedy_shadow_invocations.saturating_add(1);
                }
                if v145 {
                    self.v145_greedy_shadow_invocations =
                        self.v145_greedy_shadow_invocations.saturating_add(1);
                }
                self.v137_greedy_shadow.schedule_some(env, mech, &sender)
            }
            NativeShadowAnchorKind::Hiku => self.v137_hiku_shadow.schedule_some(env, mech, &sender),
            NativeShadowAnchorKind::Jiagu => {
                if v149 {
                    self.v149_jiagu_selected_invocations =
                        self.v149_jiagu_selected_invocations.saturating_add(1);
                }
                self.v138_jiagu_shadow.schedule_some(env, mech, &sender)
            }
            NativeShadowAnchorKind::Orion => {
                if v149 {
                    self.v149_orion_advisory_invocations =
                        self.v149_orion_advisory_invocations.saturating_add(1);
                }
                self.v138_orion_shadow.schedule_some(env, mech, &sender)
            }
            NativeShadowAnchorKind::LoadLeast => {
                if v144 {
                    self.v144_load_least_shadow_invocations =
                        self.v144_load_least_shadow_invocations.saturating_add(1);
                }
                if v145 {
                    self.v145_load_least_shadow_invocations =
                        self.v145_load_least_shadow_invocations.saturating_add(1);
                }
                self.v138_load_least_shadow
                    .schedule_some(env, mech, &sender)
            }
            NativeShadowAnchorKind::Ocs => {
                if v149 {
                    self.v149_ocs_selected_invocations =
                        self.v149_ocs_selected_invocations.saturating_add(1);
                }
                self.v137_ocs_shadow.schedule_some(env, mech, &sender)
            }
        }
        drop(sender);

        let mut capture = NativeShadowCapture::new(kind);
        for message in receiver.try_iter() {
            capture.record_message(message);
        }
        capture
    }

    fn capture_v149_causal_steady_load_portfolio(
        &mut self,
        env: &SimEnvObserve,
        mech: &MechanismImpl,
    ) -> Vec<NativeShadowCapture> {
        match self
            .v149_selected_kind
            .expect("V149 causal route must be frozen before native capture")
        {
            NativeShadowAnchorKind::Ocs => {
                let ocs = self.capture_native_shadow_kind(NativeShadowAnchorKind::Ocs, env, mech);
                // Orion is advisory on the realized OCS cohort.  Recreate it
                // every window so an undispatched All-frontier command can
                // never mutate counterfactual persistent state.
                self.v138_orion_shadow = OrionScheduler::new();
                let orion =
                    self.capture_native_shadow_kind(NativeShadowAnchorKind::Orion, env, mech);
                vec![ocs, orion]
            }
            NativeShadowAnchorKind::Faasrank => {
                vec![self.capture_native_shadow_kind(NativeShadowAnchorKind::Faasrank, env, mech)]
            }
            NativeShadowAnchorKind::Jiagu => {
                vec![self.capture_native_shadow_kind(NativeShadowAnchorKind::Jiagu, env, mech)]
            }
            unexpected => panic!(
                "V149 causal route selected unsupported native expert {}",
                unexpected.as_str()
            ),
        }
    }

    fn capture_v138_native_portfolio(
        &mut self,
        env: &SimEnvObserve,
        mech: &MechanismImpl,
    ) -> Vec<NativeShadowCapture> {
        if self
            .settings
            .operational_expert_proxy
            .native_portfolio_rule()
            .is_none()
        {
            return Vec::new();
        }
        assert!(
            self.settings.operational_direct_initialization,
            "V138 native portfolio profiles require NASH_OPERATIONAL_DIRECT_INITIALIZATION=true"
        );
        if self
            .settings
            .operational_expert_proxy
            .uses_causal_steady_load_closure()
        {
            return self.capture_v149_causal_steady_load_portfolio(env, mech);
        }
        let kinds = Self::native_portfolio_expert_kinds(
            self.settings
                .operational_expert_proxy
                .native_portfolio_rule()
                .expect("V141 portfolio rule disappeared"),
        );
        kinds
            .into_iter()
            .map(|kind| self.capture_native_shadow_kind(kind, env, mech))
            .collect()
    }

    fn native_portfolio_expert_kinds(rule: NativePortfolioRule) -> Vec<NativeShadowAnchorKind> {
        match rule {
            NativePortfolioRule::CausalBurstMorphology => vec![
                NativeShadowAnchorKind::Hash,
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::LoadLeast,
            ],
            NativePortfolioRule::CausalRawPersistence
            | NativePortfolioRule::CausalRawPersistenceFullFrontier
            | NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier => vec![
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::LoadLeast,
            ],
            NativePortfolioRule::CausalSteadyLoadClosure => vec![
                NativeShadowAnchorKind::Ocs,
                NativeShadowAnchorKind::Orion,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::Jiagu,
            ],
            NativePortfolioRule::RandomDefaultServicePareto
            | NativePortfolioRule::RandomDefaultWelfarePareto => vec![
                NativeShadowAnchorKind::Random,
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Hiku,
                NativeShadowAnchorKind::Jiagu,
                NativeShadowAnchorKind::Orion,
                NativeShadowAnchorKind::LoadLeast,
            ],
            NativePortfolioRule::FaasrankDefaultServicePareto => vec![
                NativeShadowAnchorKind::Random,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Hiku,
                NativeShadowAnchorKind::Jiagu,
                NativeShadowAnchorKind::Orion,
                NativeShadowAnchorKind::LoadLeast,
                NativeShadowAnchorKind::Ocs,
            ],
            NativePortfolioRule::MinimaxService
            | NativePortfolioRule::MinsumService
            | NativePortfolioRule::ServiceWelfareBorda => vec![
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Hiku,
                NativeShadowAnchorKind::Jiagu,
                NativeShadowAnchorKind::Orion,
                NativeShadowAnchorKind::LoadLeast,
            ],
        }
    }

    fn align_v137_native_shadow_players(
        &mut self,
        feasible_players: Vec<PlayerId>,
    ) -> Vec<PlayerId> {
        let Some(capture) = self.v137_native_shadow_capture.as_mut() else {
            return feasible_players;
        };
        Self::align_native_shadow_capture(capture, &feasible_players, &self.feasible_nodes);
        capture.ordered_players.clone()
    }

    fn align_native_shadow_capture(
        capture: &mut NativeShadowCapture,
        feasible_players: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) {
        let expected = feasible_players.iter().copied().collect::<HashSet<_>>();
        let captured = capture.assignments.keys().copied().collect::<HashSet<_>>();
        capture.missing_players = expected.difference(&captured).count();
        capture.extra_players = captured.difference(&expected).count();
        capture.infeasible_commands = capture
            .assignments
            .iter()
            .filter(|(player, node_id)| {
                !feasible_nodes
                    .get(player)
                    .is_some_and(|nodes| nodes.contains(node_id))
            })
            .count();
        capture.valid = capture.duplicate_commands == 0
            && capture.unexpected_messages == 0
            && capture.missing_players == 0
            && capture.extra_players == 0
            && capture.infeasible_commands == 0
            && capture.command_count == feasible_players.len();
        if !capture.valid {
            panic!(
                "V137 {} native shadow mismatch: commands={} duplicates={} unexpected={} missing={} extra={} infeasible={}",
                capture.kind.as_str(),
                capture.command_count,
                capture.duplicate_commands,
                capture.unexpected_messages,
                capture.missing_players,
                capture.extra_players,
                capture.infeasible_commands,
            );
        }
    }

    fn align_v142_random_prefix_capture(
        capture: &mut NativeShadowCapture,
        feasible_players: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) -> Vec<PlayerId> {
        assert_eq!(
            capture.kind,
            NativeShadowAnchorKind::Random,
            "V142 prefix source must be Random"
        );
        let expected = feasible_players.iter().copied().collect::<HashSet<_>>();
        let captured = capture.assignments.keys().copied().collect::<HashSet<_>>();
        capture.missing_players = expected.difference(&captured).count();
        capture.extra_players = captured.difference(&expected).count();
        capture.infeasible_commands = capture
            .assignments
            .iter()
            .filter(|(player, node_id)| {
                !feasible_nodes
                    .get(player)
                    .is_some_and(|nodes| nodes.contains(node_id))
            })
            .count();
        capture.valid = capture.duplicate_commands == 0
            && capture.unexpected_messages == 0
            && capture.extra_players == 0
            && capture.infeasible_commands == 0
            && capture.command_count == capture.ordered_players.len()
            && capture.assignments.len() == capture.ordered_players.len();
        if !capture.valid {
            panic!(
                "V142 Random prefix mismatch: commands={} duplicates={} unexpected={} missing={} extra={} infeasible={}",
                capture.command_count,
                capture.duplicate_commands,
                capture.unexpected_messages,
                capture.missing_players,
                capture.extra_players,
                capture.infeasible_commands,
            );
        }
        capture.ordered_players.clone()
    }

    fn project_native_capture_to_v142_random_prefix(
        source: &NativeShadowCapture,
        random_prefix: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) -> NativeShadowCapture {
        let mut projected = NativeShadowCapture::new(source.kind);
        for &player in random_prefix {
            let &node_id = source.assignments.get(&player).unwrap_or_else(|| {
                panic!(
                    "V142 {} native assignment is missing a Random-prefix player",
                    source.kind.as_str()
                )
            });
            projected.command_count = projected.command_count.saturating_add(1);
            projected.ordered_players.push(player);
            projected.assignments.insert(player, node_id);
        }
        Self::align_native_shadow_capture(&mut projected, random_prefix, feasible_nodes);
        projected
    }

    fn v143_player_order_fingerprint(players: &[PlayerId]) -> u64 {
        let mut hash = 14_695_981_039_346_656_037u64;
        for player in players {
            for value in [player.req_id as u64, player.fn_id as u64] {
                hash ^= value;
                hash = hash.wrapping_mul(1_099_511_628_211);
            }
        }
        hash
    }

    fn v143_capture_subset_fingerprint(capture: &NativeShadowCapture, players: &[PlayerId]) -> u64 {
        let mut hash = 14_695_981_039_346_656_037u64;
        for player in players {
            for value in [
                player.req_id as u64,
                player.fn_id as u64,
                capture
                    .assignments
                    .get(player)
                    .copied()
                    .unwrap_or(usize::MAX) as u64,
            ] {
                hash ^= value;
                hash = hash.wrapping_mul(1_099_511_628_211);
            }
        }
        hash
    }

    fn v143_ready_feasible_players(
        &self,
        env: &SimEnvObserve,
        feasible_players: &[PlayerId],
    ) -> Vec<PlayerId> {
        let mut ready = HashSet::new();
        for request in env.core().requests().values() {
            for fn_id in schedule_helper::collect_task_to_sche(
                request,
                env,
                schedule_helper::CollectTaskConfig::PreAllDone,
            ) {
                ready.insert(PlayerId {
                    req_id: request.req_id,
                    fn_id,
                });
            }
        }
        feasible_players
            .iter()
            .copied()
            .filter(|player| ready.contains(player))
            .collect()
    }

    fn v149_ocs_feasible_players(
        &self,
        env: &SimEnvObserve,
        feasible_players: &[PlayerId],
    ) -> Vec<PlayerId> {
        let mut parents_scheduled = HashSet::new();
        for request in env.core().requests().values() {
            for fn_id in schedule_helper::collect_task_to_sche(
                request,
                env,
                schedule_helper::CollectTaskConfig::PreAllSched,
            ) {
                parents_scheduled.insert(PlayerId {
                    req_id: request.req_id,
                    fn_id,
                });
            }
        }
        feasible_players
            .iter()
            .copied()
            .filter(|player| parents_scheduled.contains(player))
            .collect()
    }

    fn build_v143_random_prefix_ready_tail_cohort(
        &mut self,
        random_prefix: &[PlayerId],
        ready_feasible_players: &[PlayerId],
    ) -> Vec<PlayerId> {
        let prefix = random_prefix.iter().copied().collect::<HashSet<_>>();
        let ready = ready_feasible_players
            .iter()
            .copied()
            .collect::<HashSet<_>>();
        assert_eq!(
            prefix.len(),
            random_prefix.len(),
            "V143 Random prefix contains duplicate players"
        );
        assert_eq!(
            ready.len(),
            ready_feasible_players.len(),
            "V143 ready-feasible frontier contains duplicate players"
        );
        let mut cohort = random_prefix.to_vec();
        cohort.extend(
            ready_feasible_players
                .iter()
                .copied()
                .filter(|player| !prefix.contains(player)),
        );
        self.v143_ready_feasible_player_count = ready_feasible_players.len();
        self.v143_prefix_ready_overlap_count = prefix.intersection(&ready).count();
        self.v143_ready_tail_player_count = cohort.len().saturating_sub(random_prefix.len());
        self.v143_combined_cohort_player_count = cohort.len();
        self.v143_combined_cohort_ordered_hash = Some(Self::v143_player_order_fingerprint(&cohort));
        cohort
    }

    fn project_native_capture_to_v143_hybrid(
        source: &NativeShadowCapture,
        random: &NativeShadowCapture,
        random_prefix: &[PlayerId],
        cohort: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) -> NativeShadowCapture {
        assert_ne!(
            source.kind,
            NativeShadowAnchorKind::Random,
            "V143 hybrid tail source cannot be Random"
        );
        assert_eq!(
            source.duplicate_commands,
            0,
            "V143 {} native source emitted duplicate commands",
            source.kind.as_str()
        );
        assert_eq!(
            source.unexpected_messages,
            0,
            "V143 {} native source emitted unexpected messages",
            source.kind.as_str()
        );
        let prefix = random_prefix.iter().copied().collect::<HashSet<_>>();
        let mut projected = NativeShadowCapture::new(source.kind);
        for &player in cohort {
            let node_id = if prefix.contains(&player) {
                *random
                    .assignments
                    .get(&player)
                    .unwrap_or_else(|| panic!("V143 Random assignment is missing a prefix player"))
            } else {
                *source.assignments.get(&player).unwrap_or_else(|| {
                    panic!(
                        "V143 {} native assignment is missing a ready-tail player",
                        source.kind.as_str()
                    )
                })
            };
            projected.command_count = projected.command_count.saturating_add(1);
            projected.ordered_players.push(player);
            projected.assignments.insert(player, node_id);
        }
        Self::align_native_shadow_capture(&mut projected, cohort, feasible_nodes);
        projected
    }

    /// V144/V145/V146/V147 observe each unchanged native scheduler on its own
    /// command stream. V144/V145 project to a parent-complete cohort; V146
    /// deliberately expands that cohort to all currently unscheduled common
    /// placement-feasible players; V147 invokes this independently for each
    /// expert's preregistered native frontier. Drop commands outside the active
    /// frontier while preserving native relative order and exact selected node.
    /// Every requested frontier player must still be present and feasible;
    /// otherwise the contract fails closed.
    fn project_native_capture_to_causal_ready_feasible(
        source: &NativeShadowCapture,
        ready_feasible_players: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) -> NativeShadowCapture {
        assert_eq!(
            source.duplicate_commands,
            0,
            "causal native router {} source emitted duplicate commands",
            source.kind.as_str()
        );
        assert_eq!(
            source.unexpected_messages,
            0,
            "causal native router {} source emitted unexpected messages",
            source.kind.as_str()
        );
        let expected = ready_feasible_players
            .iter()
            .copied()
            .collect::<HashSet<_>>();
        assert_eq!(
            expected.len(),
            ready_feasible_players.len(),
            "causal native router ready-feasible cohort contains duplicate players"
        );
        for &player in ready_feasible_players {
            let node_id = source.assignments.get(&player).unwrap_or_else(|| {
                panic!(
                    "{} native assignment is missing a ready-feasible player",
                    source.kind.as_str()
                )
            });
            assert!(
                feasible_nodes
                    .get(&player)
                    .is_some_and(|nodes| nodes.contains(node_id)),
                "causal native router {} assignment chose an infeasible node for a ready-feasible player",
                source.kind.as_str()
            );
        }
        let mut projected = NativeShadowCapture::new(source.kind);
        for &player in &source.ordered_players {
            if !expected.contains(&player) {
                continue;
            }
            let node_id = source.assignments[&player];
            projected.command_count = projected.command_count.saturating_add(1);
            projected.ordered_players.push(player);
            assert!(
                projected.assignments.insert(player, node_id).is_none(),
                "causal native router projected capture contains duplicate players"
            );
        }
        assert_eq!(
            projected.assignments.len(),
            expected.len(),
            "causal native router projected capture lost a ready-feasible player"
        );
        let projected_order = projected.ordered_players.clone();
        Self::align_native_shadow_capture(&mut projected, &projected_order, feasible_nodes);
        projected
    }

    fn record_v142_random_prefix_evidence(
        &mut self,
        feasible_player_count: usize,
        source: &NativeShadowCapture,
    ) {
        self.v142_random_prefix_feasible_player_count = feasible_player_count;
        self.v142_random_prefix_player_count = source.ordered_players.len();
        self.v142_random_prefix_missing_feasible_player_count = source.missing_players;
        self.v142_random_prefix_early_stop_observed = source.missing_players > 0;
        self.v142_random_prefix_ordered_command_hash = Some(source.command_fingerprint());
    }

    fn select_v142_random_prefix_anchor(
        &mut self,
        feasible_players: Vec<PlayerId>,
    ) -> Vec<PlayerId> {
        let mut source = self
            .v137_native_shadow_capture
            .take()
            .expect("V142 Random prefix capture is missing");
        let random_prefix = Self::align_v142_random_prefix_capture(
            &mut source,
            &feasible_players,
            &self.feasible_nodes,
        );
        self.record_v142_random_prefix_evidence(feasible_players.len(), &source);
        let projected = Self::project_native_capture_to_v142_random_prefix(
            &source,
            &random_prefix,
            &self.feasible_nodes,
        );
        self.v137_native_shadow_capture = Some(projected);
        random_prefix
    }

    fn assignment_from_native_capture(
        &self,
        players: &[PlayerId],
        base_aggregates: &[NodeAggregate],
        capture: &NativeShadowCapture,
    ) -> Option<AssignmentState> {
        if !capture.valid || capture.assignments.len() != players.len() {
            return None;
        }
        let mut state = AssignmentState::new(base_aggregates.to_vec(), players.len());
        for &player in players {
            let &node_id = capture.assignments.get(&player)?;
            if !self
                .feasible_nodes
                .get(&player)
                .is_some_and(|nodes| nodes.contains(&node_id))
            {
                return None;
            }
            state.add(
                player,
                node_id,
                &self.existing_containers,
                &self.function_profiles,
            );
        }
        (state.assignments.len() == players.len()).then_some(state)
    }

    fn v138_all_player_work_service_proxy(
        &self,
        player: PlayerId,
        node_id: NodeId,
        prefix: &AssignmentState,
        complete_assignment: &AssignmentState,
    ) -> Option<f64> {
        let profile = self.function_profiles.get(&player.fn_id)?;
        let node = self.node_snapshots.get(node_id)?;
        let queue_work = self.node_queue_cpu_works.get(node_id)?.as_ref()?;
        if !profile.raw_cpu.is_finite()
            || profile.raw_cpu < 0.0
            || !node.cpu_capacity.is_finite()
            || node.cpu_capacity <= EPSILON
            || queue_work.pending_cpu_values.len() != node.pending_tasks
            || queue_work.resident_remaining_cpu_values.len() != node.resident_tasks
        {
            return None;
        }
        let admitted_work = queue_work.admitted_total();
        if !admitted_work.is_finite() || admitted_work < 0.0 {
            return None;
        }

        let mut parent_transfer = 0.0f64;
        for &parent_fn_id in self
            .function_parents
            .get(&player.fn_id)
            .map(Vec::as_slice)
            .unwrap_or(&[])
        {
            let parent = self.function_profiles.get(&parent_fn_id)?;
            if !parent.output_mb.is_finite() || parent.output_mb < 0.0 {
                return None;
            }
            let parent_player = PlayerId {
                req_id: player.req_id,
                fn_id: parent_fn_id,
            };
            let parent_node = self
                .v138_player_parent_nodes
                .get(&(player, parent_fn_id))
                .copied()
                .or_else(|| complete_assignment.assignments.get(&parent_player).copied())?;
            if parent_node == node_id {
                continue;
            }
            let bandwidth = self
                .node_bandwidths
                .get(parent_node)
                .and_then(|row| row.get(node_id))
                .copied()?;
            if !bandwidth.is_finite() || bandwidth <= EPSILON {
                return None;
            }
            parent_transfer += f64::from(parent.output_mb) / f64::from(bandwidth);
            if !parent_transfer.is_finite() {
                return None;
            }
        }

        let mut projected_players = prefix
            .assignments
            .iter()
            .filter_map(|(&projected_player, &projected_node)| {
                (projected_node == node_id).then_some(projected_player)
            })
            .collect::<Vec<_>>();
        projected_players.sort_unstable();
        let mut projected_work = 0.0f64;
        for projected_player in projected_players {
            let raw_cpu = self.function_profiles.get(&projected_player.fn_id)?.raw_cpu;
            if !raw_cpu.is_finite() || raw_cpu < 0.0 {
                return None;
            }
            projected_work += f64::from(raw_cpu);
        }
        let total_work = admitted_work + projected_work + f64::from(profile.raw_cpu);
        if !total_work.is_finite() || total_work < 0.0 {
            return None;
        }
        let cold_start = if self.warm_containers.contains(&(player.fn_id, node_id)) {
            0.0
        } else {
            profile.cold_start_frames as f64
        };
        let proxy = total_work / f64::from(node.cpu_capacity) + cold_start + parent_transfer;
        proxy
            .is_finite()
            .then_some(proxy)
            .filter(|value| *value >= 0.0)
    }

    fn v138_all_player_service_certificate(
        &self,
        players: &[PlayerId],
        base_aggregates: &[NodeAggregate],
        assignment: &AssignmentState,
    ) -> ReadinessServiceCertificate {
        if players.is_empty() || assignment.assignments.len() != players.len() {
            return ReadinessServiceCertificate::default();
        }
        let mut prefix = AssignmentState::new(base_aggregates.to_vec(), players.len());
        let mut service_sum = 0.0f64;
        let mut service_max = 0.0f64;
        for &player in players {
            let Some(&node_id) = assignment.assignments.get(&player) else {
                return ReadinessServiceCertificate::default();
            };
            let Some(service) =
                self.v138_all_player_work_service_proxy(player, node_id, &prefix, assignment)
            else {
                return ReadinessServiceCertificate::default();
            };
            service_sum += service;
            service_max = service_max.max(service);
            if !service_sum.is_finite() || !service_max.is_finite() {
                return ReadinessServiceCertificate::default();
            }
            prefix.add(
                player,
                node_id,
                &self.existing_containers,
                &self.function_profiles,
            );
        }
        ReadinessServiceCertificate {
            complete: true,
            evaluated_players: players.len(),
            service_sum: Some(service_sum),
            service_max: Some(service_max),
        }
    }

    fn rank_v138_native_portfolio_candidates(
        diagnostics: &mut [NativePortfolioCandidateDiagnostic],
    ) {
        let rank = |indices: &mut Vec<usize>,
                    diagnostics: &mut [NativePortfolioCandidateDiagnostic],
                    field: fn(&NativePortfolioCandidateDiagnostic) -> f64,
                    descending: bool,
                    assign: fn(&mut NativePortfolioCandidateDiagnostic, usize)| {
            indices.sort_by(|left, right| {
                let order = field(&diagnostics[*left]).total_cmp(&field(&diagnostics[*right]));
                (if descending { order.reverse() } else { order }).then_with(|| left.cmp(right))
            });
            for (position, &index) in indices.iter().enumerate() {
                assign(&mut diagnostics[index], position + 1);
            }
        };
        let mut indices = (0..diagnostics.len()).collect::<Vec<_>>();
        rank(
            &mut indices,
            diagnostics,
            |item| item.service_max.unwrap_or(f64::INFINITY),
            false,
            |item, value| item.service_max_rank = Some(value),
        );
        rank(
            &mut indices,
            diagnostics,
            |item| item.service_sum.unwrap_or(f64::INFINITY),
            false,
            |item, value| item.service_sum_rank = Some(value),
        );
        rank(
            &mut indices,
            diagnostics,
            |item| f64::from(item.paper_welfare.unwrap_or(f32::NEG_INFINITY)),
            true,
            |item, value| item.paper_welfare_rank = Some(value),
        );
        for item in diagnostics {
            item.rank_sum = Some(
                item.service_max_rank.unwrap_or(usize::MAX / 4)
                    + item.service_sum_rank.unwrap_or(usize::MAX / 4)
                    + item.paper_welfare_rank.unwrap_or(usize::MAX / 4),
            );
        }
    }

    fn native_portfolio_candidate_observations(
        diagnostics: &[NativePortfolioCandidateDiagnostic],
    ) -> Vec<serde_json::Value> {
        let default = diagnostics.first();
        let random_default = diagnostics
            .first()
            .filter(|candidate| candidate.kind == "random");
        diagnostics
            .iter()
            .map(|candidate| {
                let default_service_max_nonworse = default
                    .and_then(|item| item.service_max.zip(candidate.service_max))
                    .map(|(baseline, value)| value <= baseline + f64::from(EPSILON));
                let default_service_sum_nonworse = default
                    .and_then(|item| item.service_sum.zip(candidate.service_sum))
                    .map(|(baseline, value)| value <= baseline + f64::from(EPSILON));
                let default_service_sum_strictly_lower = default
                    .and_then(|item| item.service_sum.zip(candidate.service_sum))
                    .map(|(baseline, value)| value < baseline - f64::from(EPSILON));
                let default_welfare_nonworse = default
                    .and_then(|item| item.paper_welfare.zip(candidate.paper_welfare))
                    .map(|(baseline, value)| value + EPSILON >= baseline);
                let random_service_max_nonworse = random_default
                    .and_then(|random| random.service_max.zip(candidate.service_max))
                    .map(|(random, value)| value <= random + f64::from(EPSILON));
                let random_service_sum_nonworse = random_default
                    .and_then(|random| random.service_sum.zip(candidate.service_sum))
                    .map(|(random, value)| value <= random + f64::from(EPSILON));
                let random_service_sum_strictly_lower = random_default
                    .and_then(|random| random.service_sum.zip(candidate.service_sum))
                    .map(|(random, value)| value < random - f64::from(EPSILON));
                let random_welfare_nonworse = random_default
                    .and_then(|random| random.paper_welfare.zip(candidate.paper_welfare))
                    .map(|(random, value)| value + EPSILON >= random);
                let random_welfare_strictly_higher = random_default
                    .and_then(|random| random.paper_welfare.zip(candidate.paper_welfare))
                    .map(|(random, value)| value > random + EPSILON);
                serde_json::json!({
                    "kind": candidate.kind,
                    "commands": candidate.command_count,
                    "duplicate_commands": candidate.duplicate_commands,
                    "unexpected_messages": candidate.unexpected_messages,
                    "missing_players": candidate.missing_players,
                    "extra_players": candidate.extra_players,
                    "infeasible_commands": candidate.infeasible_commands,
                    "valid": candidate.valid,
                    "ordered_command_hash": candidate.ordered_command_hash,
                    "assignment_hash": candidate.assignment_hash,
                    "service_complete": candidate.service_complete,
                    "service_players": candidate.service_players,
                    "service_sum": candidate.service_sum,
                    "service_max": candidate.service_max,
                    "paper_welfare": candidate.paper_welfare,
                    "service_max_rank": candidate.service_max_rank,
                    "service_sum_rank": candidate.service_sum_rank,
                    "paper_welfare_rank": candidate.paper_welfare_rank,
                    "rank_sum": candidate.rank_sum,
                    "random_service_max_nonworse": random_service_max_nonworse,
                    "random_service_sum_nonworse": random_service_sum_nonworse,
                    "random_service_sum_strictly_lower": random_service_sum_strictly_lower,
                    "random_welfare_nonworse": random_welfare_nonworse,
                    "random_welfare_strictly_higher": random_welfare_strictly_higher,
                    "default_kind": default.map(|item| item.kind),
                    "default_service_max_nonworse": default_service_max_nonworse,
                    "default_service_sum_nonworse": default_service_sum_nonworse,
                    "default_service_sum_strictly_lower": default_service_sum_strictly_lower,
                    "default_welfare_nonworse": default_welfare_nonworse,
                    "default_service_pareto_admissible": default_service_max_nonworse
                        .zip(default_service_sum_strictly_lower)
                        .zip(default_welfare_nonworse)
                        .map(|((max_nonworse, sum_strict), welfare_nonworse)| max_nonworse && sum_strict && welfare_nonworse),
                    "random_service_pareto_admissible": random_service_max_nonworse
                        .zip(random_service_sum_strictly_lower)
                        .zip(random_welfare_nonworse)
                        .map(|((max_nonworse, sum_strict), welfare_nonworse)| max_nonworse && sum_strict && welfare_nonworse),
                    "random_welfare_pareto_admissible": random_service_max_nonworse
                        .zip(random_service_sum_nonworse)
                        .zip(random_welfare_strictly_higher)
                        .map(|((max_nonworse, sum_nonworse), welfare_strict)| max_nonworse && sum_nonworse && welfare_strict),
                    "selected": candidate.selected,
                })
            })
            .collect()
    }

    fn v144_causal_burst_morphology_observation(&self, stats: &SolveStats) -> serde_json::Value {
        let enabled = self
            .settings
            .operational_expert_proxy
            .uses_causal_burst_morphology_router();
        let invocation_count = |kind| {
            self.v138_native_portfolio_captures
                .iter()
                .filter(|capture| capture.kind == kind)
                .count()
        };
        let all_four_once = self.v138_native_portfolio_captures.len() == 4
            && [
                NativeShadowAnchorKind::Hash,
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::LoadLeast,
            ]
            .iter()
            .all(|kind| invocation_count(*kind) == 1);
        serde_json::json!({
            "enabled": enabled,
            "frame": self.operational_frame,
            "arrival_history_valid": self.v144_arrival_history_valid,
            "frame_reset_this_window": self.v144_frame_reset_this_window,
            "history_discontinuity_this_window": self.v144_history_discontinuity_this_window,
            "shock_active": self.operational_causal_arrival_shock_active(),
            "episode_started_this_window": self.v144_episode_started_this_window,
            "episode_count": self.v144_episode_count,
            "first_episode_start_frame": self.v144_first_episode_start_frame,
            "first_episode_active_age_frames": self.v144_first_episode_age_frames,
            "first_episode_sustained": self.v144_first_episode_sustained,
            "selected_kind": self.v144_selected_kind.map(NativeShadowAnchorKind::as_str),
            "selection_reason": self.v144_selection_reason,
            "selector_inputs": "first_seen_arrival_counts_and_current_frame_only",
            "scenario_seed_future_or_outcome_inputs_used": false,
            "shadow_initializations": {
                "hash": enabled.then_some(1),
                "greedy": enabled.then_some(1),
                "faasrank": enabled.then_some(self.v143_faasrank_shadow_initializations),
                "load_least": enabled.then_some(1),
            },
            "shadow_invocations_total": {
                "hash": self.v144_hash_shadow_invocations,
                "greedy": self.v144_greedy_shadow_invocations,
                "faasrank": self.v144_faasrank_shadow_invocations,
                "load_least": self.v144_load_least_shadow_invocations,
            },
            "shadow_invocations_this_window": {
                "hash": invocation_count(NativeShadowAnchorKind::Hash),
                "greedy": invocation_count(NativeShadowAnchorKind::Greedy),
                "faasrank": invocation_count(NativeShadowAnchorKind::Faasrank),
                "load_least": invocation_count(NativeShadowAnchorKind::LoadLeast),
            },
            "all_four_shadows_advanced_exactly_once_this_window": enabled && all_four_once,
            "selected_native_ordered_command_hash": stats.native_shadow_ordered_command_hash,
            "selected_native_assignment_hash": stats.native_shadow_anchor_assignment_hash,
            "final_assignment_hash": stats.assignment_hash,
            "selected_initializer_dispatched_exactly": !stats.window_guard_accepted
                && stats.native_shadow_anchor_assignment_hash == Some(stats.assignment_hash),
            "accepted_nash_proposal_dispatched_exactly": stats.window_guard_accepted
                && stats.proposal_assignment_hash == Some(stats.assignment_hash),
        })
    }

    fn v145_causal_raw_persistence_observation(&self, stats: &SolveStats) -> serde_json::Value {
        let enabled = self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_router();
        let invocation_count = |kind| {
            self.v138_native_portfolio_captures
                .iter()
                .filter(|capture| capture.kind == kind)
                .count()
        };
        let all_three_once = self.v138_native_portfolio_captures.len() == 3
            && [
                NativeShadowAnchorKind::Greedy,
                NativeShadowAnchorKind::Faasrank,
                NativeShadowAnchorKind::LoadLeast,
            ]
            .iter()
            .all(|kind| invocation_count(*kind) == 1);
        let persistence_comparison = self
            .v145_recent_5_count
            .zip(self.v145_baseline_80_count)
            .and_then(|(recent, baseline)| {
                let recent_scaled = recent
                    .checked_mul(V145_RAW_PERSISTENCE_BASELINE_FRAMES)?
                    .checked_mul(V145_RAW_PERSISTENCE_THRESHOLD_DENOMINATOR)?;
                let baseline_scaled = baseline
                    .checked_mul(V145_RAW_PERSISTENCE_RECENT_FRAMES)?
                    .checked_mul(V145_RAW_PERSISTENCE_THRESHOLD_NUMERATOR)?;
                Some(serde_json::json!({
                    "recent_scaled": recent_scaled,
                    "baseline_scaled": baseline_scaled,
                    "sustained": recent_scaled >= baseline_scaled,
                }))
            });
        serde_json::json!({
            "enabled": enabled,
            "frame": self.operational_frame,
            "arrival_history_valid": self.v145_arrival_history_valid,
            "frame_reset_this_window": self.v145_frame_reset_this_window,
            "history_discontinuity_this_window": self.v145_history_discontinuity_this_window,
            "raw_first_seen_current_frame": self.operational_arrival_shock_first_seen_current_frame,
            "rolling_shock_active": self.operational_causal_arrival_shock_active(),
            "episode_started_this_window": self.v145_episode_started_this_window,
            "episode_count": self.v145_episode_count,
            "first_episode_start_frame": self.v145_first_episode_start_frame,
            "first_episode_age_frames": self.v145_first_episode_age_frames,
            "baseline_frames": V145_RAW_PERSISTENCE_BASELINE_FRAMES,
            "baseline_80_count": self.v145_baseline_80_count,
            "recent_frames": V145_RAW_PERSISTENCE_RECENT_FRAMES,
            "recent_5_count": self.v145_recent_5_count,
            "evaluation_age_frames": V145_RAW_PERSISTENCE_EVALUATION_AGE_FRAMES,
            "threshold_numerator": V145_RAW_PERSISTENCE_THRESHOLD_NUMERATOR,
            "threshold_denominator": V145_RAW_PERSISTENCE_THRESHOLD_DENOMINATOR,
            "persistence_evaluated_once": self.v145_persistence_evaluated,
            "persistence_evaluation_count": self.v145_persistence_evaluation_count,
            "checked_arithmetic_valid": self.v145_checked_arithmetic_valid,
            "persistence_comparison": persistence_comparison,
            "first_episode_sustained": self.v145_first_episode_sustained,
            "selected_kind": self.v145_selected_kind.map(NativeShadowAnchorKind::as_str),
            "selection_reason": self.v145_selection_reason,
            "selector_inputs": "first_seen_arrival_counts_and_current_frame_only",
            "scenario_seed_future_or_outcome_inputs_used": false,
            "shadow_initializations": {
                "greedy": enabled.then_some(1),
                "faasrank": enabled.then_some(self.v143_faasrank_shadow_initializations),
                "load_least": enabled.then_some(1),
            },
            "shadow_invocations_total": {
                "greedy": self.v145_greedy_shadow_invocations,
                "faasrank": self.v145_faasrank_shadow_invocations,
                "load_least": self.v145_load_least_shadow_invocations,
            },
            "shadow_invocations_this_window": {
                "greedy": invocation_count(NativeShadowAnchorKind::Greedy),
                "faasrank": invocation_count(NativeShadowAnchorKind::Faasrank),
                "load_least": invocation_count(NativeShadowAnchorKind::LoadLeast),
            },
            "all_three_shadows_advanced_exactly_once_this_window": enabled && all_three_once,
            "selected_native_ordered_command_hash": stats.native_shadow_ordered_command_hash,
            "selected_native_assignment_hash": stats.native_shadow_anchor_assignment_hash,
            "final_assignment_hash": stats.assignment_hash,
            "selected_initializer_dispatched_exactly": !stats.window_guard_accepted
                && stats.native_shadow_anchor_assignment_hash == Some(stats.assignment_hash),
            "accepted_nash_proposal_dispatched_exactly": stats.window_guard_accepted
                && stats.proposal_assignment_hash == Some(stats.assignment_hash),
        })
    }

    fn v146_native_capture_evidence(
        captures: &[NativeShadowCapture],
    ) -> ([usize; 3], [Option<u64>; 3]) {
        let evidence = |kind| {
            let mut matching = captures.iter().filter(|capture| capture.kind == kind);
            let capture = matching
                .next()
                .unwrap_or_else(|| panic!("V146 {} native capture is missing", kind.as_str()));
            assert!(
                matching.next().is_none(),
                "V146 {} native capture is duplicated",
                kind.as_str()
            );
            (capture.command_count, Some(capture.command_fingerprint()))
        };
        let greedy = evidence(NativeShadowAnchorKind::Greedy);
        let faasrank = evidence(NativeShadowAnchorKind::Faasrank);
        let load_least = evidence(NativeShadowAnchorKind::LoadLeast);
        (
            [greedy.0, faasrank.0, load_least.0],
            [greedy.1, faasrank.1, load_least.1],
        )
    }

    fn v146_causal_raw_persistence_full_frontier_observation(
        &self,
        stats: &SolveStats,
    ) -> serde_json::Value {
        let enabled = self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_full_frontier_router();
        let dropped = [0, 1, 2].map(|index| {
            self.v146_native_source_command_counts[index]
                .checked_sub(self.v146_native_projected_command_counts[index])
        });
        let complete_common_cohort = enabled
            && self
                .v146_native_projected_command_counts
                .iter()
                .all(|count| *count == self.v146_full_frontier_feasible_player_count)
            && dropped.iter().all(Option::is_some);
        serde_json::json!({
            "enabled": enabled,
            "frame": self.operational_frame,
            "player_frontier": self.settings.operational_expert_proxy.player_frontier_name(),
            "collect_task_config": enabled.then_some("all_unscheduled_functions"),
            "common_hpa_candidate_filter_only": enabled,
            "full_frontier_feasible_player_count": self.v146_full_frontier_feasible_player_count,
            "source_native_command_counts": {
                "greedy": self.v146_native_source_command_counts[0],
                "faasrank": self.v146_native_source_command_counts[1],
                "load_least": self.v146_native_source_command_counts[2],
            },
            "source_native_ordered_command_hashes": {
                "greedy": self.v146_native_source_ordered_command_hashes[0],
                "faasrank": self.v146_native_source_ordered_command_hashes[1],
                "load_least": self.v146_native_source_ordered_command_hashes[2],
            },
            "projected_command_counts": {
                "greedy": self.v146_native_projected_command_counts[0],
                "faasrank": self.v146_native_projected_command_counts[1],
                "load_least": self.v146_native_projected_command_counts[2],
            },
            "projected_ordered_command_hashes": {
                "greedy": self.v146_native_projected_ordered_command_hashes[0],
                "faasrank": self.v146_native_projected_ordered_command_hashes[1],
                "load_least": self.v146_native_projected_ordered_command_hashes[2],
            },
            "dropped_noncohort_command_counts": {
                "greedy": dropped[0],
                "faasrank": dropped[1],
                "load_least": dropped[2],
            },
            "all_three_projected_assignments_cover_exact_full_feasible_cohort": complete_common_cohort,
            "selected_kind": self.v145_selected_kind.map(NativeShadowAnchorKind::as_str),
            "selection_reason": self.v145_selection_reason,
            "selected_native_ordered_command_hash": stats.native_shadow_ordered_command_hash,
            "selected_native_assignment_hash": stats.native_shadow_anchor_assignment_hash,
            "final_assignment_hash": stats.assignment_hash,
            "selected_initializer_dispatched_exactly": !stats.window_guard_accepted
                && stats.native_shadow_anchor_assignment_hash == Some(stats.assignment_hash),
            "accepted_nash_proposal_dispatched_exactly": stats.window_guard_accepted
                && stats.proposal_assignment_hash == Some(stats.assignment_hash),
        })
    }

    fn v147_causal_raw_persistence_route_native_frontier_observation(
        &self,
        stats: &SolveStats,
    ) -> serde_json::Value {
        let enabled = self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_route_native_frontier();
        let invocation_count = |kind| {
            self.v138_native_portfolio_captures
                .iter()
                .filter(|capture| capture.kind == kind)
                .count()
        };
        let native_frontiers_complete = enabled
            && self
                .v147_native_command_counts
                .iter()
                .zip(self.v147_native_frontier_player_counts.iter())
                .all(|(commands, players)| commands == players)
            && self
                .v147_native_ordered_command_hashes
                .iter()
                .all(Option::is_some)
            && self.v138_native_portfolio_captures.len() == 3
            && self.v138_native_portfolio_captures.iter().all(|capture| {
                capture.valid
                    && capture.duplicate_commands == 0
                    && capture.unexpected_messages == 0
                    && capture.missing_players == 0
                    && capture.extra_players == 0
                    && capture.infeasible_commands == 0
                    && capture.command_count == capture.ordered_players.len()
            });
        let selected_frontier = match self.v145_selected_kind {
            Some(NativeShadowAnchorKind::Faasrank) => Some("parents_completed"),
            Some(NativeShadowAnchorKind::Greedy | NativeShadowAnchorKind::LoadLeast) => {
                Some("all_unscheduled_functions")
            }
            _ => None,
        };
        let selected_index = self.v145_selected_kind.and_then(|selected| match selected {
            NativeShadowAnchorKind::Greedy => Some(0),
            NativeShadowAnchorKind::Faasrank => Some(1),
            NativeShadowAnchorKind::LoadLeast => Some(2),
            _ => None,
        });
        let selected_capture_complete = enabled
            && selected_index.is_some_and(|index| {
                self.v147_native_command_counts[index]
                    == self.v147_native_frontier_player_counts[index]
                    && self.v147_selected_frontier_player_count
                        == self.v147_native_frontier_player_counts[index]
                    && stats.native_shadow_command_count == self.v147_native_command_counts[index]
                    && stats.native_shadow_ordered_command_hash
                        == self.v147_native_ordered_command_hashes[index]
            });
        serde_json::json!({
            "enabled": enabled,
            "frame": self.operational_frame,
            "router_selected_kind": self.v145_selected_kind.map(NativeShadowAnchorKind::as_str),
            "router_selection_reason": self.v145_selection_reason,
            "native_frontiers": {
                "greedy": "all_unscheduled_functions",
                "faasrank": "parents_completed",
                "load_least": "all_unscheduled_functions",
            },
            "native_frontier_player_counts": {
                "greedy": self.v147_native_frontier_player_counts[0],
                "faasrank": self.v147_native_frontier_player_counts[1],
                "load_least": self.v147_native_frontier_player_counts[2],
            },
            "native_command_counts": {
                "greedy": self.v147_native_command_counts[0],
                "faasrank": self.v147_native_command_counts[1],
                "load_least": self.v147_native_command_counts[2],
            },
            "native_ordered_command_hashes": {
                "greedy": self.v147_native_ordered_command_hashes[0],
                "faasrank": self.v147_native_ordered_command_hashes[1],
                "load_least": self.v147_native_ordered_command_hashes[2],
            },
            "shadow_invocations_this_window": {
                "greedy": invocation_count(NativeShadowAnchorKind::Greedy),
                "faasrank": invocation_count(NativeShadowAnchorKind::Faasrank),
                "load_least": invocation_count(NativeShadowAnchorKind::LoadLeast),
            },
            "all_three_shadows_advanced_exactly_once_this_window": enabled
                && invocation_count(NativeShadowAnchorKind::Greedy) == 1
                && invocation_count(NativeShadowAnchorKind::Faasrank) == 1
                && invocation_count(NativeShadowAnchorKind::LoadLeast) == 1,
            "every_native_capture_complete_on_own_frontier": native_frontiers_complete,
            "selected_frontier": selected_frontier,
            "selected_frontier_player_count": self.v147_selected_frontier_player_count,
            "selected_frontier_player_order_hash": self.v147_selected_frontier_player_order_hash,
            "selected_capture_complete_on_own_frontier": selected_capture_complete,
            "selected_native_ordered_command_hash": stats.native_shadow_ordered_command_hash,
            "selected_native_assignment_hash": stats.native_shadow_anchor_assignment_hash,
            "final_assignment_hash": stats.assignment_hash,
            "no_cross_expert_cohort_tail_fill": enabled,
            "selected_initializer_dispatched_exactly": !stats.window_guard_accepted
                && stats.native_shadow_anchor_assignment_hash == Some(stats.assignment_hash),
            "accepted_nash_proposal_dispatched_exactly": stats.window_guard_accepted
                && stats.proposal_assignment_hash == Some(stats.assignment_hash),
        })
    }

