    fn select_v138_native_portfolio_index(
        rule: NativePortfolioRule,
        diagnostics: &[NativePortfolioCandidateDiagnostic],
    ) -> usize {
        assert_ne!(
            rule,
            NativePortfolioRule::CausalBurstMorphology,
            "V144 morphology selection requires the causal scheduler state"
        );
        assert_ne!(
            rule,
            NativePortfolioRule::CausalRawPersistence,
            "V145 persistence selection requires the causal scheduler state"
        );
        assert_ne!(
            rule,
            NativePortfolioRule::CausalRawPersistenceFullFrontier,
            "V146 full-frontier persistence selection requires the causal scheduler state"
        );
        assert_ne!(
            rule,
            NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier,
            "V147 route-native-frontier persistence selection requires the causal scheduler state"
        );
        assert_ne!(
            rule,
            NativePortfolioRule::CausalSteadyLoadClosure,
            "V149 steady-load selection requires the causal scheduler state"
        );
        if matches!(
            rule,
            NativePortfolioRule::RandomDefaultServicePareto
                | NativePortfolioRule::RandomDefaultWelfarePareto
                | NativePortfolioRule::FaasrankDefaultServicePareto
        ) {
            let default = diagnostics
                .first()
                .expect("native default portfolio cannot be empty");
            let expected_default = match rule {
                NativePortfolioRule::FaasrankDefaultServicePareto => "faasrank",
                _ => "random",
            };
            assert_eq!(
                default.kind, expected_default,
                "native default kind changed"
            );
            let default_max = default
                .service_max
                .expect("native default candidate is missing service max");
            let default_sum = default
                .service_sum
                .expect("native default candidate is missing service sum");
            let default_welfare = default
                .paper_welfare
                .expect("native default candidate is missing paper welfare");
            let epsilon64 = f64::from(EPSILON);
            let mut admissible = (1..diagnostics.len())
                .filter(|&index| {
                    let candidate = &diagnostics[index];
                    let service_max = candidate
                        .service_max
                        .expect("V141 candidate is missing service max");
                    let service_sum = candidate
                        .service_sum
                        .expect("V141 candidate is missing service sum");
                    let welfare = candidate
                        .paper_welfare
                        .expect("V141 candidate is missing paper welfare");
                    match rule {
                        NativePortfolioRule::RandomDefaultServicePareto => {
                            service_max <= default_max + epsilon64
                                && service_sum < default_sum - epsilon64
                                && welfare + EPSILON >= default_welfare
                        }
                        NativePortfolioRule::RandomDefaultWelfarePareto => {
                            service_max <= default_max + epsilon64
                                && service_sum <= default_sum + epsilon64
                                && welfare > default_welfare + EPSILON
                        }
                        NativePortfolioRule::FaasrankDefaultServicePareto => {
                            service_max <= default_max + epsilon64
                                && service_sum < default_sum - epsilon64
                                && welfare + EPSILON >= default_welfare
                        }
                        _ => unreachable!(),
                    }
                })
                .collect::<Vec<_>>();
            if admissible.is_empty() {
                return 0;
            }
            admissible.sort_by(|left, right| {
                let left_item = &diagnostics[*left];
                let right_item = &diagnostics[*right];
                match rule {
                    NativePortfolioRule::RandomDefaultServicePareto => left_item
                        .service_sum
                        .expect("V141 candidate is missing service sum")
                        .total_cmp(
                            &right_item
                                .service_sum
                                .expect("V141 candidate is missing service sum"),
                        )
                        .then_with(|| {
                            right_item
                                .paper_welfare
                                .expect("V141 candidate is missing paper welfare")
                                .total_cmp(
                                    &left_item
                                        .paper_welfare
                                        .expect("V141 candidate is missing paper welfare"),
                                )
                        })
                        .then_with(|| left.cmp(right)),
                    NativePortfolioRule::FaasrankDefaultServicePareto => left_item
                        .service_sum
                        .expect("V143 candidate is missing service sum")
                        .total_cmp(
                            &right_item
                                .service_sum
                                .expect("V143 candidate is missing service sum"),
                        )
                        .then_with(|| {
                            right_item
                                .paper_welfare
                                .expect("V143 candidate is missing paper welfare")
                                .total_cmp(
                                    &left_item
                                        .paper_welfare
                                        .expect("V143 candidate is missing paper welfare"),
                                )
                        })
                        .then_with(|| left.cmp(right)),
                    NativePortfolioRule::RandomDefaultWelfarePareto => right_item
                        .paper_welfare
                        .expect("V141 candidate is missing paper welfare")
                        .total_cmp(
                            &left_item
                                .paper_welfare
                                .expect("V141 candidate is missing paper welfare"),
                        )
                        .then_with(|| {
                            left_item
                                .service_sum
                                .expect("V141 candidate is missing service sum")
                                .total_cmp(
                                    &right_item
                                        .service_sum
                                        .expect("V141 candidate is missing service sum"),
                                )
                        })
                        .then_with(|| left.cmp(right)),
                    _ => unreachable!(),
                }
            });
            return admissible[0];
        }
        (0..diagnostics.len())
            .min_by(|left, right| {
                let left_item = &diagnostics[*left];
                let right_item = &diagnostics[*right];
                match rule {
                    NativePortfolioRule::MinimaxService => left_item
                        .service_max
                        .expect("V138 minimax candidate is missing service max")
                        .total_cmp(
                            &right_item
                                .service_max
                                .expect("V138 minimax candidate is missing service max"),
                        )
                        .then_with(|| {
                            left_item
                                .service_sum
                                .expect("V138 minimax candidate is missing service sum")
                                .total_cmp(
                                    &right_item
                                        .service_sum
                                        .expect("V138 minimax candidate is missing service sum"),
                                )
                        })
                        .then_with(|| {
                            right_item
                                .paper_welfare
                                .expect("V138 minimax candidate is missing paper welfare")
                                .total_cmp(
                                    &left_item
                                        .paper_welfare
                                        .expect("V138 minimax candidate is missing paper welfare"),
                                )
                        })
                        .then_with(|| left.cmp(right)),
                    NativePortfolioRule::MinsumService => left_item
                        .service_sum
                        .expect("V138 minsum candidate is missing service sum")
                        .total_cmp(
                            &right_item
                                .service_sum
                                .expect("V138 minsum candidate is missing service sum"),
                        )
                        .then_with(|| {
                            left_item
                                .service_max
                                .expect("V138 minsum candidate is missing service max")
                                .total_cmp(
                                    &right_item
                                        .service_max
                                        .expect("V138 minsum candidate is missing service max"),
                                )
                        })
                        .then_with(|| {
                            right_item
                                .paper_welfare
                                .expect("V138 minsum candidate is missing paper welfare")
                                .total_cmp(
                                    &left_item
                                        .paper_welfare
                                        .expect("V138 minsum candidate is missing paper welfare"),
                                )
                        })
                        .then_with(|| left.cmp(right)),
                    NativePortfolioRule::ServiceWelfareBorda => left_item
                        .rank_sum
                        .expect("V138 Borda candidate is missing rank sum")
                        .cmp(
                            &right_item
                                .rank_sum
                                .expect("V138 Borda candidate is missing rank sum"),
                        )
                        .then_with(|| left.cmp(right)),
                    NativePortfolioRule::RandomDefaultServicePareto
                    | NativePortfolioRule::RandomDefaultWelfarePareto
                    | NativePortfolioRule::FaasrankDefaultServicePareto
                    | NativePortfolioRule::CausalBurstMorphology
                    | NativePortfolioRule::CausalRawPersistence
                    | NativePortfolioRule::CausalRawPersistenceFullFrontier
                    | NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier
                    | NativePortfolioRule::CausalSteadyLoadClosure => {
                        unreachable!()
                    }
                }
            })
            .expect("V138 native portfolio cannot be empty")
    }

    fn v144_selected_native_portfolio_index(
        selected_kind: NativeShadowAnchorKind,
        diagnostics: &[NativePortfolioCandidateDiagnostic],
    ) -> usize {
        diagnostics
            .iter()
            .position(|candidate| candidate.kind == selected_kind.as_str())
            .expect("V144 selected expert is missing from the native portfolio")
    }

    fn v138_native_portfolio_selection_reason(
        rule: NativePortfolioRule,
        diagnostics: &[NativePortfolioCandidateDiagnostic],
        selected: usize,
    ) -> &'static str {
        let selected_item = &diagnostics[selected];
        let tied_on_f64 = |field: fn(&NativePortfolioCandidateDiagnostic) -> f64,
                           candidates: &[usize]| {
            candidates
                .iter()
                .copied()
                .filter(|&index| {
                    field(&diagnostics[index]).total_cmp(&field(selected_item)) == Ordering::Equal
                })
                .collect::<Vec<_>>()
        };
        let tied_on_f32 = |field: fn(&NativePortfolioCandidateDiagnostic) -> f32,
                           candidates: &[usize]| {
            candidates
                .iter()
                .copied()
                .filter(|&index| {
                    field(&diagnostics[index]).total_cmp(&field(selected_item)) == Ordering::Equal
                })
                .collect::<Vec<_>>()
        };
        let all = (0..diagnostics.len()).collect::<Vec<_>>();
        match rule {
            NativePortfolioRule::CausalBurstMorphology => "causal_burst_morphology_state_machine",
            NativePortfolioRule::CausalRawPersistence => "causal_raw_persistence_state_machine",
            NativePortfolioRule::CausalRawPersistenceFullFrontier => {
                "causal_raw_persistence_full_frontier_state_machine"
            }
            NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier => {
                "causal_raw_persistence_route_native_frontier_state_machine"
            }
            NativePortfolioRule::CausalSteadyLoadClosure => {
                "causal_steady_load_closure_state_machine"
            }
            NativePortfolioRule::MinimaxService => {
                let service_max_ties = tied_on_f64(
                    |item| item.service_max.expect("V138 service max is missing"),
                    &all,
                );
                if service_max_ties.len() == 1 {
                    return "minimum_service_max";
                }
                let service_sum_ties = tied_on_f64(
                    |item| item.service_sum.expect("V138 service sum is missing"),
                    &service_max_ties,
                );
                if service_sum_ties.len() == 1 {
                    return "service_max_tie_minimum_service_sum";
                }
                let welfare_ties = tied_on_f32(
                    |item| item.paper_welfare.expect("V138 paper welfare is missing"),
                    &service_sum_ties,
                );
                if welfare_ties.len() == 1 {
                    "service_and_sum_tie_maximum_paper_welfare"
                } else {
                    "all_metrics_tie_stable_native_kind"
                }
            }
            NativePortfolioRule::MinsumService => {
                let service_sum_ties = tied_on_f64(
                    |item| item.service_sum.expect("V138 service sum is missing"),
                    &all,
                );
                if service_sum_ties.len() == 1 {
                    return "minimum_service_sum";
                }
                let service_max_ties = tied_on_f64(
                    |item| item.service_max.expect("V138 service max is missing"),
                    &service_sum_ties,
                );
                if service_max_ties.len() == 1 {
                    return "service_sum_tie_minimum_service_max";
                }
                let welfare_ties = tied_on_f32(
                    |item| item.paper_welfare.expect("V138 paper welfare is missing"),
                    &service_max_ties,
                );
                if welfare_ties.len() == 1 {
                    "service_sum_and_max_tie_maximum_paper_welfare"
                } else {
                    "all_metrics_tie_stable_native_kind"
                }
            }
            NativePortfolioRule::ServiceWelfareBorda => {
                let selected_rank_sum = selected_item
                    .rank_sum
                    .expect("V138 Borda rank sum is missing");
                let rank_sum_ties = diagnostics
                    .iter()
                    .filter(|item| item.rank_sum == Some(selected_rank_sum))
                    .count();
                if rank_sum_ties > 1 {
                    return "ordinal_rank_sum_tie_stable_native_kind";
                }
                let selected_has_metric_tie =
                    diagnostics.iter().enumerate().any(|(index, item)| {
                        index != selected
                            && (item
                                .service_max
                                .expect("V138 service max is missing")
                                .total_cmp(
                                    &selected_item
                                        .service_max
                                        .expect("V138 service max is missing"),
                                )
                                == Ordering::Equal
                                || item
                                    .service_sum
                                    .expect("V138 service sum is missing")
                                    .total_cmp(
                                        &selected_item
                                            .service_sum
                                            .expect("V138 service sum is missing"),
                                    )
                                    == Ordering::Equal
                                || item
                                    .paper_welfare
                                    .expect("V138 paper welfare is missing")
                                    .total_cmp(
                                        &selected_item
                                            .paper_welfare
                                            .expect("V138 paper welfare is missing"),
                                    )
                                    == Ordering::Equal)
                    });
                if selected_has_metric_tie {
                    "minimum_ordinal_rank_sum_with_stable_metric_tie_ranks"
                } else {
                    "minimum_ordinal_rank_sum"
                }
            }
            NativePortfolioRule::RandomDefaultServicePareto => {
                if selected == 0 {
                    "random_default_no_strict_service_pareto_replacement"
                } else {
                    "strict_service_pareto_replacement_minimum_service_sum"
                }
            }
            NativePortfolioRule::RandomDefaultWelfarePareto => {
                if selected == 0 {
                    "random_default_no_strict_welfare_pareto_replacement"
                } else {
                    "strict_welfare_pareto_replacement_maximum_paper_welfare"
                }
            }
            NativePortfolioRule::FaasrankDefaultServicePareto => {
                if selected == 0 {
                    "faasrank_default_no_strict_service_pareto_replacement"
                } else {
                    "strict_service_pareto_replacement_minimum_service_sum"
                }
            }
        }
    }

    fn native_portfolio_candidate_diagnostic(
        &self,
        capture: &NativeShadowCapture,
        expected_player_count: usize,
        base_aggregates: &[NodeAggregate],
        signal: &PriceSignal,
    ) -> NativePortfolioCandidateDiagnostic {
        // The preregistered service certificate includes work already admitted
        // to runtime nodes. Paper welfare has a different state domain: Eq. (8)
        // contains only the current joint-decision players because existing
        // contention is already represented by Pressure(t) and Eq. (12).
        let paper_aggregates = self.empty_window_aggregates();
        let service_state = self
            .assignment_from_native_capture(&capture.ordered_players, base_aggregates, capture)
            .unwrap_or_else(|| {
                panic!(
                    "V138 {} native portfolio assignment is incomplete",
                    capture.kind.as_str()
                )
            });
        let paper_state = self
            .assignment_from_native_capture(&capture.ordered_players, &paper_aggregates, capture)
            .unwrap_or_else(|| {
                panic!(
                    "V138 {} native portfolio paper-welfare assignment is incomplete",
                    capture.kind.as_str()
                )
            });
        let service_assignment_hash =
            Self::assignment_fingerprint(&capture.ordered_players, &service_state);
        let paper_assignment_hash =
            Self::assignment_fingerprint(&capture.ordered_players, &paper_state);
        assert_eq!(
            service_assignment_hash,
            paper_assignment_hash,
            "V140 {} native portfolio service and paper-welfare assignments diverged",
            capture.kind.as_str()
        );
        let certificate = self.v138_all_player_service_certificate(
            &capture.ordered_players,
            base_aggregates,
            &service_state,
        );
        let welfare = self
            .social_welfare(&capture.ordered_players, &paper_state, signal)
            .total;
        assert!(
            certificate.complete
                && certificate.evaluated_players == expected_player_count
                && certificate.service_sum.is_some_and(f64::is_finite)
                && certificate.service_max.is_some_and(f64::is_finite)
                && welfare.is_finite(),
            "V138 {} native portfolio certificate is unavailable",
            capture.kind.as_str()
        );
        NativePortfolioCandidateDiagnostic {
            kind: capture.kind.as_str(),
            command_count: capture.command_count,
            duplicate_commands: capture.duplicate_commands,
            unexpected_messages: capture.unexpected_messages,
            missing_players: capture.missing_players,
            extra_players: capture.extra_players,
            infeasible_commands: capture.infeasible_commands,
            valid: capture.valid,
            ordered_command_hash: capture.command_fingerprint(),
            assignment_hash: Some(service_assignment_hash),
            service_complete: certificate.complete,
            service_players: certificate.evaluated_players,
            service_sum: certificate.service_sum,
            service_max: certificate.service_max,
            paper_welfare: Some(welfare),
            service_max_rank: None,
            service_sum_rank: None,
            paper_welfare_rank: None,
            rank_sum: None,
            selected: false,
        }
    }

    fn project_native_nodes_to_ordered_cohort(
        source: &NativeShadowCapture,
        ordered_players: &[PlayerId],
        feasible_nodes: &HashMap<PlayerId, Vec<NodeId>>,
    ) -> NativeShadowCapture {
        assert_eq!(
            source.duplicate_commands,
            0,
            "V149 {} advisory source emitted duplicate commands",
            source.kind.as_str()
        );
        assert_eq!(
            source.unexpected_messages,
            0,
            "V149 {} advisory source emitted unexpected messages",
            source.kind.as_str()
        );
        let unique = ordered_players.iter().copied().collect::<HashSet<_>>();
        assert_eq!(
            unique.len(),
            ordered_players.len(),
            "V149 selected native cohort contains duplicate players"
        );
        let mut projected = NativeShadowCapture::new(source.kind);
        for &player in ordered_players {
            let node_id = *source.assignments.get(&player).unwrap_or_else(|| {
                panic!(
                    "V149 {} advisory assignment is missing a selected player",
                    source.kind.as_str()
                )
            });
            assert!(
                feasible_nodes
                    .get(&player)
                    .is_some_and(|nodes| nodes.contains(&node_id)),
                "V149 {} advisory assignment chose an infeasible node",
                source.kind.as_str()
            );
            projected.command_count = projected.command_count.saturating_add(1);
            projected.ordered_players.push(player);
            assert!(projected.assignments.insert(player, node_id).is_none());
        }
        Self::align_native_shadow_capture(&mut projected, ordered_players, feasible_nodes);
        projected
    }

    fn v149_select_ocs_orion_projection(
        diagnostics: &[NativePortfolioCandidateDiagnostic],
    ) -> usize {
        assert_eq!(diagnostics.len(), 2, "V149 low portfolio changed");
        let ocs = &diagnostics[0];
        let orion = &diagnostics[1];
        assert_eq!(ocs.kind, "ocs", "V149 low default changed");
        assert_eq!(orion.kind, "orion", "V149 low advisory changed");
        let epsilon64 = f64::from(EPSILON);
        let admissible = orion.service_complete
            && ocs.service_complete
            && orion
                .service_max
                .zip(ocs.service_max)
                .is_some_and(|(candidate, baseline)| candidate <= baseline + epsilon64)
            && orion
                .service_sum
                .zip(ocs.service_sum)
                .is_some_and(|(candidate, baseline)| candidate < baseline - epsilon64)
            && orion
                .paper_welfare
                .zip(ocs.paper_welfare)
                .is_some_and(|(candidate, baseline)| candidate + EPSILON >= baseline);
        usize::from(admissible)
    }

    fn select_v138_native_portfolio(
        &mut self,
        feasible_players: Vec<PlayerId>,
        ready_feasible_players: &[PlayerId],
        base_aggregates: &[NodeAggregate],
        signal: &PriceSignal,
    ) -> Vec<PlayerId> {
        let Some(rule) = self
            .settings
            .operational_expert_proxy
            .native_portfolio_rule()
        else {
            return feasible_players;
        };
        let mut captures = std::mem::take(&mut self.v138_native_portfolio_captures);
        let expected_capture_count = match rule {
            NativePortfolioRule::CausalBurstMorphology => 4,
            NativePortfolioRule::CausalRawPersistence
            | NativePortfolioRule::CausalRawPersistenceFullFrontier
            | NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier => 3,
            NativePortfolioRule::CausalSteadyLoadClosure => {
                if self.v149_selected_kind == Some(NativeShadowAnchorKind::Ocs) {
                    2
                } else {
                    1
                }
            }
            NativePortfolioRule::RandomDefaultServicePareto
            | NativePortfolioRule::RandomDefaultWelfarePareto => 6,
            NativePortfolioRule::FaasrankDefaultServicePareto => 8,
            NativePortfolioRule::MinimaxService
            | NativePortfolioRule::MinsumService
            | NativePortfolioRule::ServiceWelfareBorda => 5,
        };
        assert_eq!(
            captures.len(),
            expected_capture_count,
            "native portfolio capture count changed"
        );
        if rule == NativePortfolioRule::CausalSteadyLoadClosure {
            let selected_kind = self
                .v149_selected_kind
                .expect("V149 route was not updated before portfolio selection");
            let expected_players = match selected_kind {
                NativeShadowAnchorKind::Ocs => self.v149_ocs_feasible_players.as_slice(),
                NativeShadowAnchorKind::Faasrank => ready_feasible_players,
                NativeShadowAnchorKind::Jiagu => feasible_players.as_slice(),
                unexpected => panic!(
                    "V149 selected unsupported native expert {}",
                    unexpected.as_str()
                ),
            };
            let selected_native = Self::project_native_capture_to_causal_ready_feasible(
                captures
                    .first()
                    .expect("V149 selected native capture is missing"),
                expected_players,
                &self.feasible_nodes,
            );
            let selected_players = selected_native.ordered_players.clone();
            let mut projected = vec![selected_native];
            if selected_kind == NativeShadowAnchorKind::Ocs {
                projected.push(Self::project_native_nodes_to_ordered_cohort(
                    captures
                        .get(1)
                        .expect("V149 Orion advisory capture is missing"),
                    &selected_players,
                    &self.feasible_nodes,
                ));
            }
            if selected_players.is_empty() {
                self.v137_native_shadow_capture = projected.first().cloned();
                self.v138_native_portfolio_captures = projected;
                self.v138_native_portfolio_diagnostics.clear();
                return Vec::new();
            }
            let mut diagnostics = projected
                .iter()
                .map(|capture| {
                    self.native_portfolio_candidate_diagnostic(
                        capture,
                        selected_players.len(),
                        base_aggregates,
                        signal,
                    )
                })
                .collect::<Vec<_>>();
            let selected = if selected_kind == NativeShadowAnchorKind::Ocs {
                Self::v149_select_ocs_orion_projection(&diagnostics)
            } else {
                0
            };
            diagnostics[selected].selected = true;
            self.v149_orion_projection_selected = selected == 1;
            self.v137_native_shadow_capture = Some(projected[selected].clone());
            self.v138_native_portfolio_captures = projected;
            self.v138_native_portfolio_diagnostics = diagnostics;
            return selected_players;
        }
        if rule == NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier {
            self.v147_native_frontier_player_counts = [
                feasible_players.len(),
                ready_feasible_players.len(),
                feasible_players.len(),
            ];
            captures = captures
                .iter()
                .map(|capture| {
                    let native_frontier = match capture.kind {
                        NativeShadowAnchorKind::Greedy | NativeShadowAnchorKind::LoadLeast => {
                            feasible_players.as_slice()
                        }
                        NativeShadowAnchorKind::Faasrank => ready_feasible_players,
                        _ => panic!("V147 unexpected native expert {}", capture.kind.as_str()),
                    };
                    Self::project_native_capture_to_causal_ready_feasible(
                        capture,
                        native_frontier,
                        &self.feasible_nodes,
                    )
                })
                .collect();
            let (counts, hashes) = Self::v146_native_capture_evidence(&captures);
            self.v147_native_command_counts = counts;
            self.v147_native_ordered_command_hashes = hashes;

            let selected_kind = self
                .v145_selected_kind
                .expect("V147 persistence route was not updated before portfolio selection");
            let selected = captures
                .iter()
                .position(|capture| capture.kind == selected_kind)
                .expect("V147 selected expert is missing from the native portfolio");
            let selected_players = captures[selected].ordered_players.clone();
            self.v147_selected_frontier_player_count = selected_players.len();
            self.v147_selected_frontier_player_order_hash =
                Some(Self::v143_player_order_fingerprint(&selected_players));
            self.v137_native_shadow_capture = Some(captures[selected].clone());
            if selected_players.is_empty() {
                self.v138_native_portfolio_captures = captures;
                self.v138_native_portfolio_diagnostics.clear();
                return Vec::new();
            }
            let mut diagnostic = self.native_portfolio_candidate_diagnostic(
                &captures[selected],
                selected_players.len(),
                base_aggregates,
                signal,
            );
            diagnostic.selected = true;
            self.v138_native_portfolio_captures = captures;
            self.v138_native_portfolio_diagnostics = vec![diagnostic];
            return selected_players;
        }
        let v146_full_frontier = self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_full_frontier_router();
        if v146_full_frontier {
            self.v146_full_frontier_feasible_player_count = feasible_players.len();
            let (counts, hashes) = Self::v146_native_capture_evidence(&captures);
            self.v146_native_source_command_counts = counts;
            self.v146_native_source_ordered_command_hashes = hashes;
        }
        let feasible_players = if matches!(
            rule,
            NativePortfolioRule::CausalBurstMorphology
                | NativePortfolioRule::CausalRawPersistence
                | NativePortfolioRule::CausalRawPersistenceFullFrontier
                | NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier
        ) {
            captures = captures
                .iter()
                .map(|capture| {
                    Self::project_native_capture_to_causal_ready_feasible(
                        capture,
                        &feasible_players,
                        &self.feasible_nodes,
                    )
                })
                .collect();
            if v146_full_frontier {
                let (counts, hashes) = Self::v146_native_capture_evidence(&captures);
                self.v146_native_projected_command_counts = counts;
                self.v146_native_projected_ordered_command_hashes = hashes;
            }
            feasible_players
        } else if self
            .settings
            .operational_expert_proxy
            .uses_random_prefix_cohort()
        {
            assert_eq!(
                captures.first().map(|capture| capture.kind),
                Some(NativeShadowAnchorKind::Random),
                "V142 portfolio must put Random first"
            );
            let random_prefix = Self::align_v142_random_prefix_capture(
                captures
                    .first_mut()
                    .expect("V142 Random portfolio capture is missing"),
                &feasible_players,
                &self.feasible_nodes,
            );
            for capture in captures.iter_mut().skip(1) {
                Self::align_native_shadow_capture(capture, &feasible_players, &self.feasible_nodes);
            }
            self.record_v142_random_prefix_evidence(
                feasible_players.len(),
                captures
                    .first()
                    .expect("V142 Random portfolio capture disappeared"),
            );
            captures = captures
                .iter()
                .map(|capture| {
                    Self::project_native_capture_to_v142_random_prefix(
                        capture,
                        &random_prefix,
                        &self.feasible_nodes,
                    )
                })
                .collect();
            random_prefix
        } else if self
            .settings
            .operational_expert_proxy
            .uses_random_prefix_ready_tail_cohort()
        {
            assert_eq!(
                captures.first().map(|capture| capture.kind),
                Some(NativeShadowAnchorKind::Random),
                "V143 portfolio must put Random first"
            );
            assert_eq!(
                captures.get(1).map(|capture| capture.kind),
                Some(NativeShadowAnchorKind::Faasrank),
                "V143 portfolio must put FaaSRank first after the Random prefix source"
            );
            let random_prefix = Self::align_v142_random_prefix_capture(
                captures
                    .first_mut()
                    .expect("V143 Random prefix capture is missing"),
                &feasible_players,
                &self.feasible_nodes,
            );
            self.record_v142_random_prefix_evidence(
                feasible_players.len(),
                captures
                    .first()
                    .expect("V143 Random prefix capture disappeared"),
            );
            let cohort = self
                .build_v143_random_prefix_ready_tail_cohort(&random_prefix, ready_feasible_players);
            let random = captures
                .first()
                .expect("V143 Random prefix capture disappeared")
                .clone();
            captures = captures
                .iter()
                .skip(1)
                .map(|capture| {
                    Self::project_native_capture_to_v143_hybrid(
                        capture,
                        &random,
                        &random_prefix,
                        &cohort,
                        &self.feasible_nodes,
                    )
                })
                .collect();
            let prefix_hash = random.command_fingerprint();
            let ready_tail = &cohort[random_prefix.len()..];
            self.v143_candidate_partition_diagnostics = captures
                .iter()
                .map(|capture| {
                    let projected_prefix_hash =
                        Self::v143_capture_subset_fingerprint(capture, &random_prefix);
                    serde_json::json!({
                        "kind": capture.kind.as_str(),
                        "cohort_player_order_hash": Self::v143_player_order_fingerprint(&cohort),
                        "random_prefix_player_count": random_prefix.len(),
                        "random_prefix_assignment_hash": projected_prefix_hash,
                        "expected_random_prefix_assignment_hash": prefix_hash,
                        "random_prefix_nodes_preserved": projected_prefix_hash == prefix_hash,
                        "ready_tail_player_count": ready_tail.len(),
                        "ready_tail_assignment_hash": Self::v143_capture_subset_fingerprint(capture, ready_tail),
                    })
                })
                .collect();
            cohort
        } else {
            for capture in &mut captures {
                Self::align_native_shadow_capture(capture, &feasible_players, &self.feasible_nodes);
            }
            feasible_players
        };
        if feasible_players.is_empty() {
            self.v137_native_shadow_capture = captures.first().cloned();
            self.v138_native_portfolio_captures = captures;
            self.v138_native_portfolio_diagnostics.clear();
            return Vec::new();
        }

        let mut diagnostics = captures
            .iter()
            .map(|capture| {
                self.native_portfolio_candidate_diagnostic(
                    capture,
                    feasible_players.len(),
                    base_aggregates,
                    signal,
                )
            })
            .collect::<Vec<_>>();

        Self::rank_v138_native_portfolio_candidates(&mut diagnostics);
        let selected = if matches!(
            rule,
            NativePortfolioRule::CausalBurstMorphology
                | NativePortfolioRule::CausalRawPersistence
                | NativePortfolioRule::CausalRawPersistenceFullFrontier
        ) {
            let selected_kind = match rule {
                NativePortfolioRule::CausalBurstMorphology => self
                    .v144_selected_kind
                    .expect("V144 morphology route was not updated before portfolio selection"),
                NativePortfolioRule::CausalRawPersistence => self
                    .v145_selected_kind
                    .expect("V145 persistence route was not updated before portfolio selection"),
                NativePortfolioRule::CausalRawPersistenceFullFrontier => self
                    .v145_selected_kind
                    .expect("V146 persistence route was not updated before portfolio selection"),
                NativePortfolioRule::CausalRawPersistenceRouteNativeFrontier => self
                    .v145_selected_kind
                    .expect("V147 persistence route was not updated before portfolio selection"),
                _ => unreachable!(),
            };
            Self::v144_selected_native_portfolio_index(selected_kind, &diagnostics)
        } else {
            Self::select_v138_native_portfolio_index(rule, &diagnostics)
        };
        diagnostics[selected].selected = true;
        let selected_players = captures[selected].ordered_players.clone();
        self.v137_native_shadow_capture = Some(captures[selected].clone());
        self.v138_native_portfolio_captures = captures;
        self.v138_native_portfolio_diagnostics = diagnostics;
        selected_players
    }

    fn parse_reference_key(value: &str) -> Option<u64> {
        let value = value.trim();
        value
            .strip_prefix("0x")
            .or_else(|| value.strip_prefix("0X"))
            .and_then(|hex| u64::from_str_radix(hex, 16).ok())
            .or_else(|| value.parse::<u64>().ok())
    }

    fn reference_record_key(value: &serde_json::Value) -> Option<u64> {
        value
            .get("state_key_u64")
            .and_then(serde_json::Value::as_u64)
            .or_else(|| {
                value
                    .get("state_key")
                    .and_then(serde_json::Value::as_str)
                    .and_then(Self::parse_reference_key)
            })
    }

    fn insert_reference(
        references: &mut HashMap<u64, Option<f32>>,
        key: u64,
        value: Option<f32>,
    ) -> Result<(), String> {
        if value.is_some_and(|reference| !reference.is_finite()) {
            return Err(format!("reference for state key {key} is not finite"));
        }
        if let Some(previous) = references.insert(key, value) {
            let same = match (previous, value) {
                (Some(previous), Some(value)) => previous.to_bits() == value.to_bits(),
                (None, None) => true,
                _ => false,
            };
            if !same {
                return Err(format!(
                    "conflicting references for state key {key}: {previous:?} vs {value:?}"
                ));
            }
        }
        Ok(())
    }

    fn parse_reference_object(
        value: &serde_json::Value,
        references: &mut HashMap<u64, Option<f32>>,
    ) -> Result<(), String> {
        if value.get("kind").and_then(serde_json::Value::as_str)
            == Some("offline_social_reference_build")
        {
            let Some(key) = Self::reference_record_key(value) else {
                return Err("reference build record is missing a valid state key".to_string());
            };
            let raw_reference = value
                .get("reference")
                .ok_or_else(|| "reference build record is missing reference".to_string())?;
            let reference = if raw_reference.is_null() {
                None
            } else {
                Some(raw_reference.as_f64().ok_or_else(|| {
                    "reference build value is neither numeric nor null".to_string()
                })? as f32)
            };
            Self::insert_reference(references, key, reference)?;
            return Ok(());
        }

        let entries = value.get("references").unwrap_or(value);
        let Some(entries) = entries.as_object() else {
            return Err(
                "reference JSON must be an object, contain a references object, or be JSONL build records"
                    .to_string(),
            );
        };
        for (raw_key, raw_value) in entries {
            let Some(key) = Self::parse_reference_key(raw_key) else {
                continue;
            };
            let raw_reference = raw_value.get("reference").unwrap_or(raw_value);
            let reference = if raw_reference.is_null() {
                None
            } else if let Some(reference) = raw_reference.as_f64().map(|value| value as f32) {
                Some(reference)
            } else {
                continue;
            };
            Self::insert_reference(references, key, reference)?;
        }
        Ok(())
    }

    fn parse_reference_contents(contents: &str) -> Result<HashMap<u64, Option<f32>>, String> {
        let mut references = HashMap::new();
        match serde_json::from_str::<serde_json::Value>(contents) {
            Ok(value) => Self::parse_reference_object(&value, &mut references)?,
            Err(document_error) => {
                let mut parsed_lines = 0usize;
                for (line_index, line) in contents.lines().enumerate() {
                    if line.trim().is_empty() {
                        continue;
                    }
                    let value = serde_json::from_str::<serde_json::Value>(line).map_err(|error| {
                        format!(
                            "reference file is neither JSON ({document_error}) nor valid JSONL at line {}: {error}",
                            line_index + 1
                        )
                    })?;
                    Self::parse_reference_object(&value, &mut references)?;
                    parsed_lines += 1;
                }
                if parsed_lines == 0 {
                    return Err("reference file is empty".to_string());
                }
            }
        }
        if references.is_empty() {
            return Err("no finite reference entries found".to_string());
        }
        Ok(references)
    }

    fn refresh_offline_reference_table(&mut self) {
        let requested_file = self.settings.offline_reference_file.clone();
        if requested_file == self.offline_reference_file_loaded {
            return;
        }
        self.offline_reference_table.clear();
        self.offline_reference_load_error = None;
        self.offline_reference_file_loaded = requested_file.clone();
        let Some(path) = requested_file else {
            return;
        };

        let load_wall_start = Instant::now();
        let load_cpu_start = ThreadTime::try_now().ok();
        let parsed = fs::read_to_string(&path)
            .map_err(|error| error.to_string())
            .and_then(|contents| Self::parse_reference_contents(&contents));
        self.offline_reference_load_attempts += 1;
        self.offline_reference_load_wall_us_total = self
            .offline_reference_load_wall_us_total
            .saturating_add(load_wall_start.elapsed().as_micros().min(u64::MAX as u128) as u64);
        self.offline_reference_load_thread_cpu_us_total = self
            .offline_reference_load_thread_cpu_us_total
            .saturating_add(
                load_cpu_start
                    .as_ref()
                    .and_then(|start| start.try_elapsed().ok())
                    .map(|duration| duration.as_micros().min(u64::MAX as u128) as u64)
                    .unwrap_or(0),
            );
        match parsed {
            Ok(references) => {
                self.offline_reference_table = references;
            }
            Err(error) => {
                log::error!(
                    "NSESche failed to load offline social reference table {}: {}",
                    path,
                    error
                );
                self.offline_reference_load_error = Some(error);
            }
        }
    }

    fn ensure_reference_build_writer(&mut self) {
        if self.settings.reference_mode != "build" {
            return;
        }
        let Some(path) = self.settings.reference_build_output_file.as_ref() else {
            if self.reference_build_writer_error.is_none() {
                let error = "reference mode build requires experiment.reference.build_output_path or an enabled experiment output root".to_string();
                log::error!("NSESche {error}");
                self.reference_build_writer_error = Some(error);
            }
            return;
        };
        let requested = PathBuf::from(path);
        if self
            .reference_build_writer
            .as_ref()
            .is_some_and(|writer| writer.final_path == requested)
        {
            return;
        }
        if let Some(mut previous) = self.reference_build_writer.take() {
            if let Err(error) = previous.finalize() {
                log::error!("NSESche {error}");
                self.reference_build_writer_error = Some(error);
                return;
            }
        }
        match ReferenceBuildWriter::new(requested) {
            Ok(writer) => {
                self.reference_build_writer = Some(writer);
                self.reference_build_writer_error = None;
            }
            Err(error) => {
                log::error!("NSESche {error}");
                self.reference_build_writer_error = Some(error);
            }
        }
    }

    fn persist_reference_build_record(
        &mut self,
        state_key: u64,
        reference: Option<f32>,
        initial_assignment_hash: u64,
        player_count: usize,
        sa_iterations: u32,
        compute_us: u64,
    ) -> (u64, bool) {
        if self.settings.reference_mode != "build" {
            return (0, true);
        }
        let start = Instant::now();
        self.ensure_reference_build_writer();
        let result = self
            .reference_build_writer
            .as_mut()
            .ok_or_else(|| {
                self.reference_build_writer_error
                    .clone()
                    .unwrap_or_else(|| "reference build writer is unavailable".to_string())
            })
            .and_then(|writer| {
                writer.record(
                    state_key,
                    reference,
                    initial_assignment_hash,
                    player_count,
                    sa_iterations,
                    compute_us,
                )
            });
        match result {
            Ok(_) => (start.elapsed().as_micros() as u64, true),
            Err(error) => {
                log::error!("NSESche {error}");
                self.reference_build_writer_error = Some(error);
                (start.elapsed().as_micros() as u64, false)
            }
        }
    }

    fn ensure_observation_writer(&mut self, env: &SimEnvObserve) -> Result<(), String> {
        let config = env.help().config();
        if !self.settings.observation_enabled || !config.experiment.output.enabled {
            return Ok(());
        }
        if self.observation_writer.is_some() {
            return Ok(());
        }
        let final_path = Path::new(&config.experiment.output.root)
            .join(&config.experiment.run_id)
            .join("nash_metrics.jsonl");
        match NashObservationWriter::new(final_path) {
            Ok(writer) => {
                self.observation_writer = Some(writer);
                self.observation_writer_error = None;
                Ok(())
            }
            Err(error) => {
                self.observation_writer_error = Some(error.clone());
                Err(error)
            }
        }
    }

    fn emit_observation(&mut self, event: serde_json::Value) {
        log::info!("NSE_METRIC_V2 {}", event);
        if let Some(writer) = self.observation_writer.as_mut() {
            if let Err(error) = writer.record(&event) {
                self.observation_writer_error = Some(error.clone());
                panic!("NSESche observation output failed: {error}");
            }
        }
    }

    fn ensure_function_profiles(&mut self, env: &SimEnvObserve) {
        let function_count = env.core().fns().len();
        if self.profile_function_count == function_count
            && self.profile_heterogeneity_enabled == self.settings.heterogeneity_enabled
            && self.function_profiles.len() == function_count
        {
            return;
        }

        let functions = {
            let functions = env.core().fns();
            functions
                .iter()
                .map(|function| {
                    (
                        function.fn_id,
                        function.dag_id,
                        function.cpu,
                        function.mem,
                        function.out_put_size,
                        function.cold_start_time,
                        if env.help().config().experiment.qos.enabled {
                            function.quality_weight
                        } else {
                            self.settings.quality_weight
                        },
                        function
                            .cold_start_container_mem_use
                            .max(function.container_mem()),
                    )
                })
                .collect::<Vec<_>>()
        };
        let max_cpu = functions
            .iter()
            .map(|function| function.2)
            .fold(EPSILON, f32::max);
        let max_memory = functions
            .iter()
            .map(|function| function.3)
            .fold(EPSILON, f32::max);
        let dags = env.core().dags();

        self.function_profiles.clear();
        self.function_parents.clear();
        self.function_children.clear();
        for (
            fn_id,
            dag_id,
            cpu,
            memory,
            output_mb,
            cold_start_frames,
            quality_weight,
            required_memory,
        ) in functions
        {
            let dag_node_count = dags
                .get(dag_id)
                .map(|dag| dag.dag_inner.node_count())
                .unwrap_or(1)
                .max(1);
            let heterogeneity = HeterogeneityProfile::new(
                cpu / max_cpu,
                memory / max_memory,
                dag_node_count,
                self.settings.heterogeneity_enabled,
            );
            let parents = env.func(fn_id).parent_fns(env);
            self.function_parents.insert(fn_id, parents);
            self.function_profiles.insert(
                fn_id,
                FunctionProfile {
                    fn_id,
                    raw_cpu: cpu,
                    raw_memory: memory,
                    output_mb,
                    cold_start_frames,
                    dag_node_count,
                    required_container_memory: required_memory,
                    quality_weight,
                    heterogeneity,
                },
            );
        }
        for &fn_id in self.function_profiles.keys() {
            self.function_children.entry(fn_id).or_default();
        }
        for (&child_fn_id, parents) in &self.function_parents {
            for &parent_fn_id in parents {
                self.function_children
                    .entry(parent_fn_id)
                    .or_default()
                    .push(child_fn_id);
            }
        }
        for children in self.function_children.values_mut() {
            children.sort_unstable();
            children.dedup();
        }
        self.terminal_functions =
            Self::derive_terminal_functions(&self.function_profiles, &self.function_parents);
        self.profile_function_count = function_count;
        self.profile_heterogeneity_enabled = self.settings.heterogeneity_enabled;
    }

    fn derive_terminal_functions(
        function_profiles: &HashMap<FnId, FunctionProfile>,
        function_parents: &HashMap<FnId, Vec<FnId>>,
    ) -> HashSet<FnId> {
        let nonterminal_functions = function_parents
            .values()
            .flat_map(|parents| parents.iter().copied())
            .collect::<HashSet<_>>();
        function_profiles
            .keys()
            .copied()
            .filter(|fn_id| !nonterminal_functions.contains(fn_id))
            .collect()
    }

    fn is_completion_proximal_depth1_function(&self, fn_id: FnId) -> bool {
        if self.terminal_functions.contains(&fn_id) {
            return true;
        }
        self.function_children.get(&fn_id).is_some_and(|children| {
            !children.is_empty()
                && children
                    .iter()
                    .all(|child| self.terminal_functions.contains(child))
        })
    }

    fn is_outstanding_nonterminal_speculation(
        &self,
        fn_id: FnId,
        assigned_functions: &HashMap<FnId, NodeId>,
        done_functions: &HashMap<FnId, usize>,
    ) -> bool {
        assigned_functions.contains_key(&fn_id)
            && !done_functions.contains_key(&fn_id)
            && !self.terminal_functions.contains(&fn_id)
            && self
                .function_parents
                .get(&fn_id)
                .into_iter()
                .flatten()
                .any(|parent| !done_functions.contains_key(parent))
    }

    fn outstanding_nonterminal_speculation_count(
        &self,
        assigned_functions: &HashMap<FnId, NodeId>,
        done_functions: &HashMap<FnId, usize>,
    ) -> usize {
        assigned_functions
            .keys()
            .copied()
            .filter(|fn_id| {
                self.is_outstanding_nonterminal_speculation(
                    *fn_id,
                    assigned_functions,
                    done_functions,
                )
            })
            .count()
    }

    fn select_one_outstanding_short_work_candidate(
        &self,
        collectable_functions: &[FnId],
        done_functions: &HashMap<FnId, usize>,
        critical_path_rank: &HashMap<FnId, f32>,
        request_remaining_work: f32,
        queue_density: f32,
        credit_available: bool,
    ) -> Option<FnId> {
        if !(self
            .settings
            .operational_expert_proxy
            .uses_one_outstanding_short_work_credit()
            || self
                .settings
                .operational_expert_proxy
                .uses_lifetime_short_work_credit())
            || !credit_available
            || request_remaining_work > V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
            || queue_density >= V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD
        {
            return None;
        }

        collectable_functions
            .iter()
            .copied()
            .filter(|fn_id| {
                self.function_profiles.contains_key(fn_id)
                    && !self.terminal_functions.contains(fn_id)
                    && self
                        .function_parents
                        .get(fn_id)
                        .into_iter()
                        .flatten()
                        .any(|parent| !done_functions.contains_key(parent))
            })
            .min_by(|left, right| {
                critical_path_rank
                    .get(right)
                    .copied()
                    .unwrap_or(0.0)
                    .total_cmp(&critical_path_rank.get(left).copied().unwrap_or(0.0))
                    .then_with(|| left.cmp(right))
            })
    }

    fn lifetime_short_work_credit_available(&self, request_id: ReqId) -> bool {
        self.lifetime_short_work_credit_available_with_outstanding(request_id, 0)
    }

    fn lifetime_short_work_credit_available_with_outstanding(
        &self,
        request_id: ReqId,
        outstanding_before: usize,
    ) -> bool {
        let second_age_ready = self
            .settings
            .operational_expert_proxy
            .lifetime_credit_second_min_age_windows()
            .is_none_or(|minimum_age| {
                self.aged_credit_first_admission_frames
                    .get(&request_id)
                    .is_some_and(|first_frame| {
                        self.operational_frame.saturating_sub(*first_frame) >= minimum_age
                    })
            });
        self.settings
            .operational_expert_proxy
            .uses_lifetime_short_work_credit()
            && (!self.lifetime_credit_consumed_requests.contains(&request_id)
                || (self
                    .settings
                    .operational_expert_proxy
                    .lifetime_credit_second_outstanding_limit()
                    .is_some_and(|limit| outstanding_before <= limit)
                    && second_age_ready
                    && !self
                        .sequential_credit_second_consumed_requests
                        .contains(&request_id)))
    }

    fn consume_lifetime_short_work_credit(&mut self, request_id: ReqId) -> bool {
        self.consume_lifetime_short_work_credit_stage(request_id, 0)
            .is_some()
    }

    fn consume_lifetime_short_work_credit_stage(
        &mut self,
        request_id: ReqId,
        outstanding_before: usize,
    ) -> Option<usize> {
        if !self
            .lifetime_short_work_credit_available_with_outstanding(request_id, outstanding_before)
        {
            return None;
        }
        if self.lifetime_credit_consumed_requests.insert(request_id) {
            if self
                .settings
                .operational_expert_proxy
                .uses_aged_dual_lifetime_credit2()
            {
                self.aged_credit_first_admission_frames
                    .insert(request_id, self.operational_frame);
            }
            Some(1)
        } else if self
            .settings
            .operational_expert_proxy
            .lifetime_credit_second_outstanding_limit()
            .is_some()
            && self
                .sequential_credit_second_consumed_requests
                .insert(request_id)
        {
            Some(2)
        } else {
            None
        }
    }

    fn observe_jit_parent_task(
        &self,
        env: &SimEnvObserve,
        request: &Request,
        fn_id: FnId,
        frame: usize,
    ) -> Option<JitParentTaskObservation> {
        let &node_id = request.fn_node.get(&fn_id)?;
        let node = env.node(node_id);
        let container = node.container(fn_id)?;
        let task = container.req_fn_state.get(&request.req_id)?;
        let own_parents_done = self
            .function_parents
            .get(&fn_id)
            .into_iter()
            .flatten()
            .all(|parent| request.done_fns.contains_key(parent));
        Some(JitParentTaskObservation {
            frame,
            node_id,
            left_calc: task.left_calc,
            active: container.is_running() && own_parents_done && task.data_recv_done(),
        })
    }

    fn jit_parent_tail_decision(
        &self,
        request_id: ReqId,
        done_fns: &HashMap<FnId, usize>,
        child_fn_id: FnId,
        current: &HashMap<PlayerId, JitParentTaskObservation>,
        frame: usize,
    ) -> JitParentTailDecision {
        let cold_start_frames = self
            .function_profiles
            .get(&child_fn_id)
            .map(|profile| profile.cold_start_frames)
            .unwrap_or(0);
        if cold_start_frames == 0 {
            return JitParentTailDecision::Reject {
                reason: JitParentTailRejection::ZeroColdStart,
                max_predicted_remaining_frames: None,
                max_tail_to_cold_start_ratio: None,
            };
        }

        let mut unfinished_parents = self
            .function_parents
            .get(&child_fn_id)
            .into_iter()
            .flatten()
            .copied()
            .filter(|parent| !done_fns.contains_key(parent))
            .collect::<Vec<_>>();
        unfinished_parents.sort_unstable();
        unfinished_parents.dedup();
        if unfinished_parents.is_empty() {
            return JitParentTailDecision::Reject {
                reason: JitParentTailRejection::MissingCurrent,
                max_predicted_remaining_frames: None,
                max_tail_to_cold_start_ratio: None,
            };
        }

        let mut max_predicted_remaining_frames = 0.0_f32;
        for parent_fn_id in unfinished_parents.iter().copied() {
            let parent = PlayerId {
                req_id: request_id,
                fn_id: parent_fn_id,
            };
            let Some(current_observation) = current.get(&parent).copied() else {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::MissingCurrent,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            };
            let Some(previous_observation) = self
                .jit_parent_task_observations
                .get(&parent)
                .copied()
                .filter(|previous| {
                    previous.frame.checked_add(1) == Some(frame)
                        && previous.node_id == current_observation.node_id
                })
            else {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::MissingPreviousOrNonconsecutive,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            };
            if !previous_observation.active || !current_observation.active {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::Inactive,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            }
            if !previous_observation.left_calc.is_finite()
                || previous_observation.left_calc < 0.0
                || !current_observation.left_calc.is_finite()
                || current_observation.left_calc < 0.0
            {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::InvalidWork,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            }
            let realized_service = previous_observation.left_calc - current_observation.left_calc;
            if !realized_service.is_finite() || realized_service <= EPSILON {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::ZeroService,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            }
            let predicted_remaining_frames = current_observation.left_calc / realized_service;
            if !predicted_remaining_frames.is_finite() || predicted_remaining_frames < 0.0 {
                return JitParentTailDecision::Reject {
                    reason: JitParentTailRejection::InvalidWork,
                    max_predicted_remaining_frames: None,
                    max_tail_to_cold_start_ratio: None,
                };
            }
            max_predicted_remaining_frames =
                max_predicted_remaining_frames.max(predicted_remaining_frames);
        }

        let max_tail_to_cold_start_ratio =
            max_predicted_remaining_frames / cold_start_frames as f32;
        if max_predicted_remaining_frames <= cold_start_frames as f32 {
            JitParentTailDecision::Admit {
                unfinished_parent_count: unfinished_parents.len(),
                max_predicted_remaining_frames,
                max_tail_to_cold_start_ratio,
            }
        } else {
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::TailLongerThanColdStart,
                max_predicted_remaining_frames: Some(max_predicted_remaining_frames),
                max_tail_to_cold_start_ratio: Some(max_tail_to_cold_start_ratio),
            }
        }
    }

    fn uses_jiagu_forecast_order(&self) -> bool {
        matches!(
            self.settings.operational_expert_proxy,
            OperationalExpertProxy::JiaguForecastOrder
                | OperationalExpertProxy::JiaguForecastFaithful
                | OperationalExpertProxy::JiaguNativeFaithfulWindowSafePareto
                | OperationalExpertProxy::JiaguNativeExactPerPlayerPareto
                | OperationalExpertProxy::JiaguNativeExactPerPlayerStrictPareto
                | OperationalExpertProxy::JiaguNativeExactSrptReadyPerPlayerStrictPareto
        )
    }

    fn uses_jiagu_forecast_width(&self) -> bool {
        matches!(
            self.settings.operational_expert_proxy,
            OperationalExpertProxy::JiaguForecastWidth
                | OperationalExpertProxy::JiaguForecastFaithful
                | OperationalExpertProxy::JiaguNativeFaithfulWindowSafePareto
                | OperationalExpertProxy::JiaguNativeExactPerPlayerPareto
                | OperationalExpertProxy::JiaguNativeExactPerPlayerStrictPareto
                | OperationalExpertProxy::JiaguNativeExactSrptReadyPerPlayerStrictPareto
        )
    }

    fn update_operational_jiagu_forecast(&mut self, frame: usize) {
        if !(self.uses_jiagu_forecast_order() || self.uses_jiagu_forecast_width()) {
            return;
        }
        if self.operational_jiagu_last_frame == Some(frame) {
            return;
        }
        if self
            .operational_jiagu_last_frame
            .is_some_and(|last_frame| frame < last_frame)
        {
            self.operational_jiagu_demand_history.clear();
            self.operational_jiagu_predicted_demand.clear();
        }
        self.operational_jiagu_last_frame = Some(frame);
        let mut function_ids = self.function_profiles.keys().copied().collect::<Vec<_>>();
        function_ids.sort_unstable();
        for fn_id in function_ids {
            let count = self
                .player_function_demand
                .get(&fn_id)
                .copied()
                .unwrap_or(0) as f64;
            let history = self
                .operational_jiagu_demand_history
                .entry(fn_id)
                .or_insert_with(|| VecDeque::with_capacity(OPERATIONAL_JIAGU_DEMAND_WINDOW));
            history.push_back(count);
            while history.len() > OPERATIONAL_JIAGU_DEMAND_WINDOW {
                history.pop_front();
            }
            self.operational_jiagu_predicted_demand
                .insert(fn_id, jiagu_forecast_demand(history));
        }
    }

    fn reset_operational_causal_arrival_shock(&mut self) {
        self.operational_seen_request_ids.clear();
        self.operational_first_seen_arrival_history.clear();
        self.operational_arrival_history_last_frame = None;
        self.operational_arrival_shock_until_frame = None;
        self.operational_arrival_shock_first_seen_current_frame = 0;
        self.operational_arrival_shock_baseline_count = 0;
        self.operational_arrival_shock_recent_count = 0;
        self.operational_arrival_shock_history_complete = false;
    }

    fn reset_v144_causal_burst_morphology(&mut self) {
        self.v144_last_frame = None;
        self.v144_arrival_history_valid = true;
        self.v144_frame_reset_this_window = false;
        self.v144_history_discontinuity_this_window = false;
        self.v144_previous_shock_active = false;
        self.v144_episode_started_this_window = false;
        self.v144_episode_count = 0;
        self.v144_first_episode_start_frame = None;
        self.v144_first_episode_age_frames = 0;
        self.v144_first_episode_sustained = false;
        self.v144_selected_kind = None;
        self.v144_selection_reason = "not_applicable";
    }

    fn v144_causal_burst_morphology_route(
        history_valid: bool,
        episode_count: usize,
        first_episode_sustained: bool,
    ) -> (NativeShadowAnchorKind, &'static str) {
        if !history_valid {
            return (
                NativeShadowAnchorKind::Hash,
                "arrival_history_discontinuity_fail_closed_hash",
            );
        }
        if episode_count == 0 {
            return (
                NativeShadowAnchorKind::Hash,
                "quiet_before_first_episode_hash",
            );
        }
        if episode_count >= 2 {
            return (
                NativeShadowAnchorKind::LoadLeast,
                "recurrent_episode_retained_load_least",
            );
        }
        if first_episode_sustained {
            return (
                NativeShadowAnchorKind::Faasrank,
                "first_sustained_episode_retained_faasrank",
            );
        }
        (
            NativeShadowAnchorKind::Greedy,
            "first_short_episode_or_post_episode_greedy",
        )
    }

    fn update_v144_causal_burst_morphology(&mut self, frame: usize) {
        if !self
            .settings
            .operational_expert_proxy
            .uses_causal_burst_morphology_router()
        {
            self.reset_v144_causal_burst_morphology();
            return;
        }

        self.v144_frame_reset_this_window = false;
        self.v144_history_discontinuity_this_window = false;
        self.v144_episode_started_this_window = false;

        if self
            .v144_last_frame
            .is_some_and(|last_frame| frame < last_frame)
        {
            self.reset_v144_causal_burst_morphology();
            self.v144_frame_reset_this_window = true;
        } else if self
            .v144_last_frame
            .is_some_and(|last_frame| frame != last_frame.saturating_add(1))
        {
            // A missing or duplicate scheduler observation cannot be treated
            // as a quiet arrival frame.  Keep the invalidity sticky for this
            // run and route to the preregistered fail-closed Hash initializer.
            self.v144_arrival_history_valid = false;
            self.v144_history_discontinuity_this_window = true;
        }
        self.v144_last_frame = Some(frame);

        let shock_active = self.operational_causal_arrival_shock_active();
        if self.v144_arrival_history_valid {
            if shock_active && !self.v144_previous_shock_active {
                self.v144_episode_count = self.v144_episode_count.saturating_add(1);
                self.v144_episode_started_this_window = true;
                if self.v144_episode_count == 1 {
                    self.v144_first_episode_start_frame = Some(frame);
                    self.v144_first_episode_age_frames = 0;
                }
            }
            if shock_active && self.v144_episode_count == 1 {
                self.v144_first_episode_age_frames = self
                    .v144_first_episode_start_frame
                    .map_or(0, |start| frame.saturating_sub(start).saturating_add(1));
                if self.v144_first_episode_age_frames >= 50 {
                    self.v144_first_episode_sustained = true;
                }
            }
        }
        self.v144_previous_shock_active = shock_active;
        let (kind, reason) = Self::v144_causal_burst_morphology_route(
            self.v144_arrival_history_valid,
            self.v144_episode_count,
            self.v144_first_episode_sustained,
        );
        self.v144_selected_kind = Some(kind);
        self.v144_selection_reason = reason;
    }

    fn reset_v145_causal_raw_persistence(&mut self) {
        self.v145_last_frame = None;
        self.v145_arrival_history_valid = true;
        self.v145_frame_reset_this_window = false;
        self.v145_history_discontinuity_this_window = false;
        self.v145_previous_shock_active = false;
        self.v145_episode_started_this_window = false;
        self.v145_episode_count = 0;
        self.v145_first_episode_start_frame = None;
        self.v145_first_episode_age_frames = 0;
        self.v145_baseline_80_count = None;
        self.v145_recent_5_count = None;
        self.v145_persistence_evaluated = false;
        self.v145_persistence_evaluation_count = 0;
        self.v145_first_episode_sustained = false;
        self.v145_checked_arithmetic_valid = true;
        self.v145_selected_kind = None;
        self.v145_selection_reason = "not_applicable";
    }

    fn v145_checked_raw_arrival_sum(&self, start_frame: usize, frames: usize) -> Option<usize> {
        let end_frame = start_frame.checked_add(frames)?;
        let mut expected_frame = start_frame;
        let mut sum = 0usize;
        for &(frame, count) in &self.operational_first_seen_arrival_history {
            if frame < start_frame || frame >= end_frame {
                continue;
            }
            if frame != expected_frame {
                return None;
            }
            sum = sum.checked_add(count)?;
            expected_frame = expected_frame.checked_add(1)?;
        }
        (expected_frame == end_frame).then_some(sum)
    }

    fn v145_causal_raw_persistence_route(
        history_valid: bool,
        episode_count: usize,
        persistence_evaluated: bool,
        first_episode_sustained: bool,
    ) -> (NativeShadowAnchorKind, &'static str) {
        if !history_valid {
            return (
                NativeShadowAnchorKind::Greedy,
                "arrival_history_or_arithmetic_fail_closed_greedy",
            );
        }
        if episode_count >= 2 {
            return (
                NativeShadowAnchorKind::LoadLeast,
                "recurrent_episode_retained_load_least",
            );
        }
        if persistence_evaluated && first_episode_sustained {
            return (
                NativeShadowAnchorKind::Faasrank,
                "age55_raw_persistence_sustained_retained_faasrank",
            );
        }
        if persistence_evaluated {
            return (
                NativeShadowAnchorKind::Greedy,
                "age55_raw_persistence_short_retained_greedy",
            );
        }
        if episode_count == 0 {
            return (
                NativeShadowAnchorKind::Greedy,
                "quiet_before_first_episode_greedy",
            );
        }
        (
            NativeShadowAnchorKind::Greedy,
            "first_episode_unclassified_through_age54_greedy",
        )
    }

    fn update_v145_causal_raw_persistence(&mut self, frame: usize) {
        if !self
            .settings
            .operational_expert_proxy
            .uses_causal_raw_persistence_router()
        {
            self.reset_v145_causal_raw_persistence();
            return;
        }

        self.v145_frame_reset_this_window = false;
        self.v145_history_discontinuity_this_window = false;
        self.v145_episode_started_this_window = false;

        if self
            .v145_last_frame
            .is_some_and(|last_frame| frame < last_frame)
        {
            self.reset_v145_causal_raw_persistence();
            self.v145_frame_reset_this_window = true;
        } else if self
            .v145_last_frame
            .is_some_and(|last_frame| frame != last_frame.saturating_add(1))
        {
            self.v145_arrival_history_valid = false;
            self.v145_history_discontinuity_this_window = true;
        }
        self.v145_last_frame = Some(frame);

        let shock_active = self.operational_causal_arrival_shock_active();
        if self.v145_arrival_history_valid {
            if shock_active && !self.v145_previous_shock_active {
                self.v145_episode_count = self.v145_episode_count.saturating_add(1);
                self.v145_episode_started_this_window = true;
                if self.v145_episode_count == 1 {
                    self.v145_first_episode_start_frame = Some(frame);
                    self.v145_first_episode_age_frames = 1;
                    let baseline = frame
                        .checked_sub(V145_RAW_PERSISTENCE_BASELINE_FRAMES)
                        .and_then(|start| {
                            self.v145_checked_raw_arrival_sum(
                                start,
                                V145_RAW_PERSISTENCE_BASELINE_FRAMES,
                            )
                        });
                    self.v145_checked_arithmetic_valid = baseline.is_some();
                    self.v145_baseline_80_count = baseline;
                    if !baseline
                        .is_some_and(|count| count >= CAUSAL_ARRIVAL_SHOCK_MIN_REQUESTS_PER_WINDOW)
                    {
                        self.v145_arrival_history_valid = false;
                    }
                }
            }

            if let Some(start_frame) = self.v145_first_episode_start_frame {
                self.v145_first_episode_age_frames =
                    frame.saturating_sub(start_frame).saturating_add(1);
                if self.v145_first_episode_age_frames == V145_RAW_PERSISTENCE_EVALUATION_AGE_FRAMES
                    && !self.v145_persistence_evaluated
                {
                    self.v145_persistence_evaluated = true;
                    self.v145_persistence_evaluation_count =
                        self.v145_persistence_evaluation_count.saturating_add(1);
                    let recent_start = frame
                        .saturating_add(1)
                        .checked_sub(V145_RAW_PERSISTENCE_RECENT_FRAMES);
                    let recent = recent_start.and_then(|start| {
                        self.v145_checked_raw_arrival_sum(start, V145_RAW_PERSISTENCE_RECENT_FRAMES)
                    });
                    self.v145_recent_5_count = recent;
                    let comparison =
                        recent
                            .zip(self.v145_baseline_80_count)
                            .and_then(|(recent, baseline)| {
                                let recent_scaled = recent
                                    .checked_mul(V145_RAW_PERSISTENCE_BASELINE_FRAMES)?
                                    .checked_mul(V145_RAW_PERSISTENCE_THRESHOLD_DENOMINATOR)?;
                                let baseline_scaled = baseline
                                    .checked_mul(V145_RAW_PERSISTENCE_RECENT_FRAMES)?
                                    .checked_mul(V145_RAW_PERSISTENCE_THRESHOLD_NUMERATOR)?;
                                Some(recent_scaled >= baseline_scaled)
                            });
                    match comparison {
                        Some(sustained) => self.v145_first_episode_sustained = sustained,
                        None => {
                            self.v145_checked_arithmetic_valid = false;
                            self.v145_arrival_history_valid = false;
                        }
                    }
                }
            }
        }

        self.v145_previous_shock_active = shock_active;
        let (kind, reason) = Self::v145_causal_raw_persistence_route(
            self.v145_arrival_history_valid,
            self.v145_episode_count,
            self.v145_persistence_evaluated,
            self.v145_first_episode_sustained,
        );
        self.v145_selected_kind = Some(kind);
        self.v145_selection_reason = reason;
    }

    fn reset_v149_causal_steady_load_closure(&mut self) {
        self.v149_last_frame = None;
        self.v149_history_valid = true;
        self.v149_frame_reset_this_window = false;
        self.v149_history_discontinuity_this_window = false;
        self.v149_cumulative_arrivals = 0;
        self.v149_high_gate_evaluated = false;
        self.v149_load_gate_evaluated = false;
        self.v149_band = V149SteadyLoadBand::Unclassified;
        self.v149_selected_kind = None;
        self.v149_selection_reason = "not_applicable";
        self.v149_route_switch_count = 0;
        self.v149_ocs_state_initializations = 0;
        self.v149_faasrank_state_initializations = 0;
        self.v149_jiagu_state_initializations = 0;
        self.v149_ocs_selected_invocations = 0;
        self.v149_faasrank_selected_invocations = 0;
        self.v149_jiagu_selected_invocations = 0;
        self.v149_orion_advisory_invocations = 0;
        self.v149_ocs_feasible_players.clear();
        self.v149_orion_projection_selected = false;
    }

    fn invalidate_v149_causal_steady_load_closure(&mut self, reason: &'static str) {
        self.v149_history_valid = false;
        self.v149_band = V149SteadyLoadBand::Invalid;
        self.v149_selected_kind = Some(NativeShadowAnchorKind::Ocs);
        self.v149_selection_reason = reason;
    }

    fn update_v149_causal_steady_load_closure(&mut self, frame: usize) {
        if !self
            .settings
            .operational_expert_proxy
            .uses_causal_steady_load_closure()
        {
            self.reset_v149_causal_steady_load_closure();
            return;
        }

        self.v149_frame_reset_this_window = false;
        self.v149_history_discontinuity_this_window = false;
        self.v149_orion_projection_selected = false;

        if self.v149_last_frame.is_none() {
            if frame != 0 {
                self.invalidate_v149_causal_steady_load_closure(
                    "initial_frame_not_zero_fail_closed_ocs",
                );
            } else {
                self.v137_ocs_shadow = OCSScheduler::new();
                self.v143_faasrank_shadow = None;
                self.v138_jiagu_shadow = JiaguScheduler::new();
                self.v149_ocs_state_initializations = 1;
                self.v149_selected_kind = Some(NativeShadowAnchorKind::Ocs);
                self.v149_selection_reason = "causal_load_unclassified_ocs";
            }
        } else if self.v149_last_frame.is_some_and(|last| frame < last) {
            self.reset_v149_causal_steady_load_closure();
            self.v149_frame_reset_this_window = true;
            if frame == 0 {
                self.v137_ocs_shadow = OCSScheduler::new();
                self.v143_faasrank_shadow = None;
                self.v138_jiagu_shadow = JiaguScheduler::new();
                self.v149_ocs_state_initializations = 1;
                self.v149_selected_kind = Some(NativeShadowAnchorKind::Ocs);
                self.v149_selection_reason = "frame_reset_reinitialized_ocs";
            } else {
                self.invalidate_v149_causal_steady_load_closure(
                    "nonzero_frame_reset_fail_closed_ocs",
                );
            }
        } else if self
            .v149_last_frame
            .is_some_and(|last| frame != last.saturating_add(1))
        {
            self.v149_history_discontinuity_this_window = true;
            self.invalidate_v149_causal_steady_load_closure(
                "arrival_history_discontinuity_fail_closed_ocs",
            );
        }
        self.v149_last_frame = Some(frame);

        if self.v149_history_valid {
            let Some(total) = self
                .v149_cumulative_arrivals
                .checked_add(self.operational_arrival_shock_first_seen_current_frame)
            else {
                self.invalidate_v149_causal_steady_load_closure(
                    "arrival_count_overflow_fail_closed_ocs",
                );
                return;
            };
            self.v149_cumulative_arrivals = total;

            if !self.v149_high_gate_evaluated
                && frame.saturating_add(1) == V149_HIGH_CLASSIFICATION_FRAMES
            {
                self.v149_high_gate_evaluated = true;
                if self.v149_cumulative_arrivals >= V149_HIGH_ARRIVAL_THRESHOLD {
                    self.v149_band = V149SteadyLoadBand::High;
                    self.v149_selected_kind = Some(NativeShadowAnchorKind::Jiagu);
                    self.v149_selection_reason = "frame20_high_arrival_gate_jiagu";
                    self.v149_route_switch_count = self.v149_route_switch_count.saturating_add(1);
                    self.v138_jiagu_shadow = JiaguScheduler::new();
                    self.v149_jiagu_state_initializations =
                        self.v149_jiagu_state_initializations.saturating_add(1);
                }
            }

            if frame.saturating_add(1) > V149_HIGH_CLASSIFICATION_FRAMES
                && !self.v149_high_gate_evaluated
            {
                self.invalidate_v149_causal_steady_load_closure(
                    "missed_frame20_gate_fail_closed_ocs",
                );
                return;
            }

            if self.v149_band != V149SteadyLoadBand::High
                && !self.v149_load_gate_evaluated
                && frame.saturating_add(1) == V149_LOAD_CLASSIFICATION_FRAMES
            {
                self.v149_load_gate_evaluated = true;
                self.v149_route_switch_count = self.v149_route_switch_count.saturating_add(1);
                if self.v149_cumulative_arrivals < V149_MIDDLE_ARRIVAL_THRESHOLD {
                    self.v149_band = V149SteadyLoadBand::Low;
                    self.v149_selected_kind = Some(NativeShadowAnchorKind::Ocs);
                    self.v149_selection_reason = "frame100_low_arrival_gate_ocs";
                } else {
                    self.v149_band = V149SteadyLoadBand::Middle;
                    self.v149_selected_kind = Some(NativeShadowAnchorKind::Faasrank);
                    self.v149_selection_reason = "frame100_middle_arrival_gate_faasrank";
                    self.v143_faasrank_shadow = None;
                    self.v149_faasrank_state_initializations =
                        self.v149_faasrank_state_initializations.saturating_add(1);
                }
            }

            if self.v149_band != V149SteadyLoadBand::High
                && frame.saturating_add(1) > V149_LOAD_CLASSIFICATION_FRAMES
                && !self.v149_load_gate_evaluated
            {
                self.invalidate_v149_causal_steady_load_closure(
                    "missed_frame100_gate_fail_closed_ocs",
                );
                return;
            }
        }

        if self.v149_history_valid && self.v149_band == V149SteadyLoadBand::Unclassified {
            self.v149_selected_kind = Some(NativeShadowAnchorKind::Ocs);
            self.v149_selection_reason = "causal_load_unclassified_ocs";
        }
    }

    fn update_operational_causal_arrival_shock(
        &mut self,
        frame: usize,
        request_ids: impl IntoIterator<Item = ReqId>,
    ) {
        let Some(gate) = self
            .settings
            .operational_expert_proxy
            .causal_arrival_shock_gate()
        else {
            self.reset_operational_causal_arrival_shock();
            return;
        };

        if self
            .operational_arrival_history_last_frame
            .is_some_and(|last_frame| frame < last_frame)
        {
            self.reset_operational_causal_arrival_shock();
        }

        let first_seen = request_ids
            .into_iter()
            .filter(|req_id| self.operational_seen_request_ids.insert(*req_id))
            .count();
        match self.operational_arrival_history_last_frame {
            Some(last_frame) if last_frame == frame => {
                if let Some((_, count)) = self.operational_first_seen_arrival_history.back_mut() {
                    *count = count.saturating_add(first_seen);
                }
            }
            Some(last_frame) if last_frame.saturating_add(1) == frame => {
                self.operational_first_seen_arrival_history
                    .push_back((frame, first_seen));
            }
            Some(_) => {
                // Missing scheduler observations cannot be interpreted as
                // zero arrivals.  Restart the causal history and fail closed.
                self.operational_first_seen_arrival_history.clear();
                self.operational_arrival_shock_until_frame = None;
                self.operational_first_seen_arrival_history
                    .push_back((frame, first_seen));
            }
            None => self
                .operational_first_seen_arrival_history
                .push_back((frame, first_seen)),
        }
        self.operational_arrival_history_last_frame = Some(frame);
        while self.operational_first_seen_arrival_history.len()
            > CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES
        {
            self.operational_first_seen_arrival_history.pop_front();
        }

        self.operational_arrival_shock_first_seen_current_frame = self
            .operational_first_seen_arrival_history
            .back()
            .map(|(_, count)| *count)
            .unwrap_or(0);
        self.operational_arrival_shock_history_complete = self
            .operational_first_seen_arrival_history
            .front()
            .zip(self.operational_first_seen_arrival_history.back())
            .is_some_and(|((first_frame, _), (last_frame, _))| {
                self.operational_first_seen_arrival_history.len()
                    == CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES
                    && first_frame.saturating_add(CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES - 1)
                        == *last_frame
            });
        self.operational_arrival_shock_baseline_count = 0;
        self.operational_arrival_shock_recent_count = 0;
        if self.operational_arrival_shock_history_complete {
            self.operational_arrival_shock_baseline_count = self
                .operational_first_seen_arrival_history
                .iter()
                .take(CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES)
                .map(|(_, count)| *count)
                .sum();
            self.operational_arrival_shock_recent_count = self
                .operational_first_seen_arrival_history
                .iter()
                .skip(CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES)
                .map(|(_, count)| *count)
                .sum();
            let sufficient_counts = self.operational_arrival_shock_baseline_count
                >= CAUSAL_ARRIVAL_SHOCK_MIN_REQUESTS_PER_WINDOW
                && self.operational_arrival_shock_recent_count
                    >= CAUSAL_ARRIVAL_SHOCK_MIN_REQUESTS_PER_WINDOW;
            let recent_scaled = self.operational_arrival_shock_recent_count as u128
                * CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES as u128
                * gate.threshold_denominator as u128;
            let baseline_scaled = self.operational_arrival_shock_baseline_count as u128
                * CAUSAL_ARRIVAL_SHOCK_RECENT_FRAMES as u128
                * gate.threshold_numerator as u128;
            if sufficient_counts && recent_scaled >= baseline_scaled {
                let detected_until = frame.saturating_add(gate.active_frames - 1);
                self.operational_arrival_shock_until_frame = Some(
                    self.operational_arrival_shock_until_frame
                        .map_or(detected_until, |until| until.max(detected_until)),
                );
            }
        }
    }

    fn operational_causal_arrival_shock_active(&self) -> bool {
        self.operational_arrival_shock_until_frame
            .is_some_and(|until| self.operational_frame <= until)
    }

    /// Returns the two adjacent, disjoint 20-frame first-seen-arrival sums
    /// frozen by V116.  Any incomplete history or integer overflow fails
    /// closed so it cannot authorize an alternative initializer.
    fn operational_non_decreasing_arrival_phase(&self) -> Option<(usize, usize, bool)> {
        if !self.operational_arrival_shock_history_complete {
            return None;
        }
        let previous_start =
            CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES.checked_sub(CAUSAL_ARRIVAL_SHOCK_RECENT_FRAMES)?;
        let checked_sum = |skip: usize| {
            self.operational_first_seen_arrival_history
                .iter()
                .skip(skip)
                .take(CAUSAL_ARRIVAL_SHOCK_RECENT_FRAMES)
                .try_fold(0usize, |sum, (_, count)| sum.checked_add(*count))
        };
        let previous = checked_sum(previous_start)?;
        let current = checked_sum(CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES)?;
        Some((previous, current, current >= previous))
    }

    fn record_causal_arrival_shock_stats(&self, stats: &mut SolveStats) {
        let gate = self
            .settings
            .operational_expert_proxy
            .causal_arrival_shock_gate();
        stats.causal_arrival_shock_gate_enabled = gate.is_some();
        stats.causal_arrival_shock_active = self.operational_causal_arrival_shock_active();
        stats.causal_arrival_shock_history_complete =
            self.operational_arrival_shock_history_complete;
        stats.causal_arrival_shock_first_seen_current_frame =
            self.operational_arrival_shock_first_seen_current_frame;
        stats.causal_arrival_shock_baseline_count = self.operational_arrival_shock_baseline_count;
        stats.causal_arrival_shock_recent_count = self.operational_arrival_shock_recent_count;
        stats.causal_arrival_shock_threshold_numerator =
            gate.map(|value| value.threshold_numerator);
        stats.causal_arrival_shock_threshold_denominator =
            gate.map(|value| value.threshold_denominator);
        stats.causal_arrival_shock_until_frame = self.operational_arrival_shock_until_frame;
        stats.arrival_phase_gate_enabled = self
            .settings
            .operational_expert_proxy
            .uses_non_decreasing_arrival_phase_guard();
        if stats.arrival_phase_gate_enabled {
            if let Some((previous, current, non_decreasing)) =
                self.operational_non_decreasing_arrival_phase()
            {
                stats.arrival_phase_history_complete = true;
                stats.arrival_phase_previous_count = Some(previous);
                stats.arrival_phase_current_count = Some(current);
                stats.arrival_phase_non_decreasing = non_decreasing;
            }
        }
    }

    fn sort_srpt_players(&self, players: &mut [PlayerId]) {
        players.sort_by(|left, right| {
            self.player_request_remaining_work
                .get(left)
                .copied()
                .unwrap_or(f32::INFINITY)
                .total_cmp(
                    &self
                        .player_request_remaining_work
                        .get(right)
                        .copied()
                        .unwrap_or(f32::INFINITY),
                )
                .then_with(|| {
                    self.player_critical_path_rank
                        .get(right)
                        .copied()
                        .unwrap_or(0.0)
                        .total_cmp(
                            &self
                                .player_critical_path_rank
                                .get(left)
                                .copied()
                                .unwrap_or(0.0),
                        )
                })
                .then_with(|| left.cmp(right))
        });
    }

    fn collect_players(&mut self, env: &SimEnvObserve) -> Vec<PlayerId> {
        let requests = env.core().requests();
        self.operational_algorithm_seed = env.help().config().algorithm_seed().to_string();
        self.operational_frame = env.core().current_frame();
        let current_jit_parent_task_observations = if self
            .settings
            .operational_expert_proxy
            .requires_jit_parent_tail_short_work()
        {
            let mut observations = HashMap::new();
            let mut request_ids = requests.keys().copied().collect::<Vec<_>>();
            request_ids.sort_unstable();
            for request_id in request_ids {
                let request = requests
                    .get(&request_id)
                    .expect("request ID came from the current request map");
                let mut function_ids = request.fn_node.keys().copied().collect::<Vec<_>>();
                function_ids.sort_unstable();
                for fn_id in function_ids {
                    if request.done_fns.contains_key(&fn_id) {
                        continue;
                    }
                    if let Some(observation) =
                        self.observe_jit_parent_task(env, request, fn_id, self.operational_frame)
                    {
                        observations.insert(
                            PlayerId {
                                req_id: request_id,
                                fn_id,
                            },
                            observation,
                        );
                    }
                }
            }
            observations
        } else {
            HashMap::new()
        };
        if !self
            .settings
            .operational_expert_proxy
            .uses_causal_steady_load_closure()
        {
            let request_ids = requests.keys().copied().collect::<Vec<_>>();
            self.update_operational_causal_arrival_shock(self.operational_frame, request_ids);
            self.update_v149_causal_steady_load_closure(self.operational_frame);
        }
        self.update_v144_causal_burst_morphology(self.operational_frame);
        self.update_v145_causal_raw_persistence(self.operational_frame);
        let mut players = Vec::new();
        self.player_parent_placements.clear();
        self.v138_player_parent_nodes.clear();
        self.player_critical_path_rank.clear();
        self.player_request_remaining_work.clear();
        self.player_function_demand.clear();
        self.terminal_pipeline_admitted_incomplete_parents_this_window = 0;
        self.terminal_pipeline_rejected_nonterminal_incomplete_parents_this_window = 0;
        self.cpu_bounded_terminal_admitted_incomplete_parents_this_window = 0;
        self.cpu_bounded_terminal_rejected_heavy_incomplete_parents_this_window = 0;
        self.cpu_bounded_terminal_parents_completed_heavy_bypass_this_window = 0;
        self.cpu_bounded_terminal_admitted_ratio_max_this_window = None;
        self.cpu_bounded_terminal_rejected_ratio_min_this_window = None;
        self.capacity_overload_heavy_incomplete_parent_terminal_players_this_window = 0;
        self.capacity_overload_node_count_this_window = 0;
        self.capacity_overload_cpu_guard_active_this_window = false;
        self.capacity_overload_guard_inactive_heavy_admissions_this_window = 0;
        self.short_work_pipeline_admitted_nonterminal_incomplete_parents_this_window = 0;
        self.short_work_pipeline_admitted_remaining_work_max_this_window = None;
        self.short_work_pipeline_rejected_remaining_work_min_this_window = None;
        self.short_work_pipeline_admitted_queue_density_max_this_window = None;
        self.short_work_pipeline_rejected_at_or_above_queue_threshold_this_window = 0;
        self.short_work_pipeline_rejected_queue_density_min_this_window = None;
        self.completion_proximal_short_work_admitted_this_window = 0;
        self.deeper_short_work_rejected_this_window = 0;
        self.jit_parent_tail_admitted_this_window = 0;
        self.jit_parent_tail_admitted_deeper_this_window = 0;
        self.jit_parent_tail_rejected_missing_or_nonconsecutive_this_window = 0;
        self.jit_parent_tail_rejected_inactive_this_window = 0;
        self.jit_parent_tail_rejected_invalid_or_zero_service_this_window = 0;
        self.jit_parent_tail_rejected_over_cold_start_this_window = 0;
        self.jit_parent_tail_admitted_max_predicted_frames_this_window = None;
        self.jit_parent_tail_admitted_max_ratio_this_window = None;
        self.jit_parent_tail_rejected_over_cold_start_min_ratio_this_window = None;
        self.one_outstanding_credit_requests_observed_this_window = 0;
        self.one_outstanding_credit_occupied_requests_this_window = 0;
        self.one_outstanding_credit_released_requests_this_window = 0;
        self.one_outstanding_credit_outstanding_max_before_this_window = 0;
        self.one_outstanding_credit_requests_over_limit_before_this_window = 0;
        self.one_outstanding_credit_admitted_this_window = 0;
        self.one_outstanding_credit_rejected_occupied_this_window = 0;
        self.one_outstanding_credit_rejected_not_selected_this_window = 0;
        self.one_outstanding_credit_projected_max_this_window = 0;
        self.one_outstanding_credit_projected_requests_over_limit_this_window = 0;
        self.lifetime_credit_requests_observed_this_window = 0;
        self.lifetime_credit_consumed_requests_before_this_window = 0;
        self.lifetime_credit_retired_requests_this_window = 0;
        self.sequential_credit_second_consumed_before_this_window = 0;
        self.sequential_credit_second_retired_requests_this_window = 0;
        self.lifetime_credit_first_admissions_this_window = 0;
        self.sequential_credit_second_admissions_this_window = 0;
        self.lifetime_credit_rejected_already_consumed_this_window = 0;
        self.sequential_credit_rejected_while_outstanding_this_window = 0;
        self.lifetime_credit_rejected_not_selected_this_window = 0;
        self.lifetime_credit_repeat_admission_violations_this_window = 0;
        self.sequential_credit_second_admission_outstanding_violations_this_window = 0;
        self.aged_credit_first_frames_before_this_window = 0;
        self.aged_credit_first_frames_retired_this_window = 0;
        self.aged_credit_first_frame_missing_requests_this_window = 0;
        self.aged_credit_first_frame_orphan_requests_this_window = 0;
        self.aged_credit_second_rejected_too_young_this_window = 0;
        self.aged_credit_second_admission_age_violations_this_window = 0;
        self.aged_credit_second_admission_age_min_this_window = None;
        self.aged_credit_second_admission_age_max_this_window = None;
        self.sequential_credit_selected_per_request_max_this_window = 0;
        self.sequential_credit_projected_outstanding_max_this_window = 0;
        self.sequential_credit_projected_requests_over_limit_this_window = 0;
        self.lifetime_credit_candidate_players_this_window.clear();
        self.sequential_credit_candidate_outstanding_before_this_window
            .clear();
        self.ready_antihotspot_players_this_window.clear();
        self.ready_antihotspot_dispatched_this_window = 0;
        self.ready_antihotspot_with_history_this_window = 0;
        self.ready_antihotspot_v163_anchor_substitutions_this_window = 0;
        self.ready_antihotspot_history_length_max_this_window = 0;
        let operational_queue_density = self.operational_queue_density();
        let uses_one_outstanding_credit = self
            .settings
            .operational_expert_proxy
            .uses_one_outstanding_short_work_credit();
        let uses_lifetime_credit = self
            .settings
            .operational_expert_proxy
            .uses_lifetime_short_work_credit();
        let lifetime_credit_second_outstanding_limit = self
            .settings
            .operational_expert_proxy
            .lifetime_credit_second_outstanding_limit();
        let uses_lifetime_credit2 = lifetime_credit_second_outstanding_limit.is_some();
        if uses_lifetime_credit {
            let credited_before_retention = self.lifetime_credit_consumed_requests.len();
            self.lifetime_credit_consumed_requests
                .retain(|request_id| requests.contains_key(request_id));
            self.lifetime_credit_retired_requests_this_window = credited_before_retention
                .saturating_sub(self.lifetime_credit_consumed_requests.len());
            if uses_lifetime_credit2 {
                let second_before_retention = self.sequential_credit_second_consumed_requests.len();
                self.sequential_credit_second_consumed_requests
                    .retain(|request_id| requests.contains_key(request_id));
                self.sequential_credit_second_retired_requests_this_window =
                    second_before_retention
                        .saturating_sub(self.sequential_credit_second_consumed_requests.len());
            } else {
                self.sequential_credit_second_consumed_requests.clear();
            }
            if self
                .settings
                .operational_expert_proxy
                .uses_aged_dual_lifetime_credit2()
            {
                let frames_before_retention = self.aged_credit_first_admission_frames.len();
                self.aged_credit_first_admission_frames
                    .retain(|request_id, _| requests.contains_key(request_id));
                self.aged_credit_first_frames_retired_this_window = frames_before_retention
                    .saturating_sub(self.aged_credit_first_admission_frames.len());
                self.aged_credit_first_frames_before_this_window =
                    self.aged_credit_first_admission_frames.len();
                self.aged_credit_first_frame_missing_requests_this_window = self
                    .lifetime_credit_consumed_requests
                    .iter()
                    .filter(|request_id| {
                        !self
                            .aged_credit_first_admission_frames
                            .contains_key(request_id)
                    })
                    .count();
                self.aged_credit_first_frame_orphan_requests_this_window = self
                    .aged_credit_first_admission_frames
                    .keys()
                    .filter(|request_id| {
                        !self.lifetime_credit_consumed_requests.contains(request_id)
                    })
                    .count();
            } else {
                self.aged_credit_first_admission_frames.clear();
            }
            self.lifetime_credit_requests_observed_this_window = requests.len();
            self.lifetime_credit_consumed_requests_before_this_window =
                self.lifetime_credit_consumed_requests.len();
            self.sequential_credit_second_consumed_before_this_window =
                self.sequential_credit_second_consumed_requests.len();
        } else {
            self.lifetime_credit_consumed_requests.clear();
            self.sequential_credit_second_consumed_requests.clear();
            self.aged_credit_first_admission_frames.clear();
        }
        let one_outstanding_counts = if uses_one_outstanding_credit || uses_lifetime_credit2 {
            requests
                .values()
                .map(|request| {
                    (
                        request.req_id,
                        self.outstanding_nonterminal_speculation_count(
                            &request.fn_node,
                            &request.done_fns,
                        ),
                    )
                })
                .collect::<HashMap<_, _>>()
        } else {
            HashMap::new()
        };
        let current_one_outstanding_occupied_requests = one_outstanding_counts
            .iter()
            .filter_map(|(&request_id, &count)| (count > 0).then_some(request_id))
            .collect::<HashSet<_>>();
        if uses_one_outstanding_credit {
            self.one_outstanding_credit_requests_observed_this_window = requests.len();
            self.one_outstanding_credit_occupied_requests_this_window =
                current_one_outstanding_occupied_requests.len();
            self.one_outstanding_credit_released_requests_this_window = self
                .one_outstanding_credit_previous_occupied_requests
                .iter()
                .filter(|request_id| {
                    requests.contains_key(request_id)
                        && !current_one_outstanding_occupied_requests.contains(request_id)
                })
                .count();
            self.one_outstanding_credit_outstanding_max_before_this_window =
                one_outstanding_counts.values().copied().max().unwrap_or(0);
            self.one_outstanding_credit_requests_over_limit_before_this_window =
                one_outstanding_counts
                    .values()
                    .filter(|&&count| count > 1)
                    .count();
        }
        let mean_node_cpu = {
            let node_count = env.node_cnt().max(1) as f32;
            (env.nodes()
                .iter()
                .map(|node| node.rsc_limit.cpu)
                .sum::<f32>()
                / node_count)
                .max(EPSILON)
        };
        if self
            .settings
            .operational_expert_proxy
            .uses_capacity_overload_cpu_bounded_terminal_guard()
        {
            self.capacity_overload_node_count_this_window = env.node_cnt();
            self.capacity_overload_heavy_incomplete_parent_terminal_players_this_window = requests
                .values()
                .map(|request| {
                    schedule_helper::collect_task_to_sche(
                        request,
                        env,
                        self.settings.operational_expert_proxy.collect_task_config(),
                    )
                    .into_iter()
                    .filter(|fn_id| {
                        let terminal_function = self.terminal_functions.contains(fn_id);
                        let parents_all_done = self
                            .function_parents
                            .get(fn_id)
                            .into_iter()
                            .flatten()
                            .all(|parent| request.done_fns.contains_key(parent));
                        let function_cpu_work = env.func(*fn_id).cpu;
                        terminal_function
                            && !parents_all_done
                            && function_cpu_work.is_finite()
                            && function_cpu_work >= 0.0
                            && mean_node_cpu.is_finite()
                            && mean_node_cpu > EPSILON
                            && function_cpu_work / mean_node_cpu
                                > V168_CPU_BOUNDED_TERMINAL_RATIO_THRESHOLD
                    })
                    .count()
                })
                .sum();
            self.capacity_overload_cpu_guard_active_this_window = self
                .settings
                .operational_expert_proxy
                .capacity_overload_cpu_guard_active(
                    self.capacity_overload_heavy_incomplete_parent_terminal_players_this_window,
                    self.capacity_overload_node_count_this_window,
                );
        }
        for request in requests.values() {
            let uses_srpt_order = self.settings.operational_expert_proxy.uses_srpt_order();
            let mut request_remaining_work = 0.0_f32;
            let critical_path_rank = if self.settings.operational_structural_proxy
                || self.settings.operational_adaptive_proxy
                || uses_srpt_order
                || matches!(
                    self.settings.operational_expert_proxy,
                    OperationalExpertProxy::Orion
                        | OperationalExpertProxy::OrionLoadFaithful
                        | OperationalExpertProxy::FaasrankOrionBorda
                        | OperationalExpertProxy::Faasrank2OrionBorda
                        | OperationalExpertProxy::FaasrankOrionLoadLeastBorda
                        | OperationalExpertProxy::Faasrank2OrionLoadLeastBorda
                        | OperationalExpertProxy::Faasrank2OrionLoadLeast2Borda
                        | OperationalExpertProxy::Structural
                ) {
                let dag = env.dag(request.dag_i);
                let mut walker = dag.new_dag_walker();
                let mut topological_order = Vec::new();
                while let Some(index) = walker.next(&dag.dag_inner) {
                    topological_order.push(dag.dag_inner[index]);
                }
                let node_count = env.node_cnt().max(1) as f32;
                let average_cpu = (env
                    .nodes()
                    .iter()
                    .map(|node| node.rsc_limit.cpu)
                    .sum::<f32>()
                    / node_count)
                    .max(EPSILON);
                let mut ranks = HashMap::new();
                if uses_srpt_order {
                    request_remaining_work = topological_order
                        .iter()
                        .filter(|fn_id| !request.done_fns.contains_key(fn_id))
                        .map(|&fn_id| {
                            let function = env.func(fn_id);
                            let cold_start_work = self
                                .function_profiles
                                .get(&fn_id)
                                .map(|profile| profile.cold_start_frames as f32 / 1_000.0)
                                .unwrap_or(0.0);
                            function.cpu / average_cpu
                                + cold_start_work
                                + function.out_put_size / 1_000.0
                        })
                        .sum::<f32>()
                        .max(EPSILON);
                }
                for &fn_id in topological_order.iter().rev() {
                    let function = env.func(fn_id);
                    let execution_cost = function.cpu / average_cpu;
                    let transfer_cost = function.out_put_size / 1_000.0;
                    let largest_child_rank = function
                        .sub_fns(env)
                        .into_iter()
                        .filter_map(|child| ranks.get(&child).copied())
                        .fold(0.0_f32, f32::max);
                    ranks.insert(fn_id, execution_cost + transfer_cost + largest_child_rank);
                }
                ranks
            } else {
                HashMap::new()
            };
            let collect_config = self.settings.operational_expert_proxy.collect_task_config();
            let collectable_functions =
                schedule_helper::collect_task_to_sche(request, env, collect_config);
            let outstanding_before = one_outstanding_counts
                .get(&request.req_id)
                .copied()
                .unwrap_or(0);
            let selected_one_outstanding_candidate = self
                .select_one_outstanding_short_work_candidate(
                    &collectable_functions,
                    &request.done_fns,
                    &critical_path_rank,
                    request_remaining_work,
                    operational_queue_density,
                    outstanding_before == 0,
                );
            let mut admitted_one_outstanding_for_request = 0_usize;
            let mut admitted_lifetime_credit_for_request = 0_usize;
            let lifetime_credit_available_before = self
                .lifetime_short_work_credit_available_with_outstanding(
                    request.req_id,
                    outstanding_before,
                );
            let selected_lifetime_credit_candidate = self
                .select_one_outstanding_short_work_candidate(
                    &collectable_functions,
                    &request.done_fns,
                    &critical_path_rank,
                    request_remaining_work,
                    operational_queue_density,
                    lifetime_credit_available_before,
                );
            for fn_id in collectable_functions {
                let parents_all_done = self
                    .function_parents
                    .get(&fn_id)
                    .into_iter()
                    .flatten()
                    .all(|parent| request.done_fns.contains_key(parent));
                let terminal_function = self.terminal_functions.contains(&fn_id);
                let terminal_cpu_ratio = terminal_function.then(|| {
                    let function_cpu_work = env.func(fn_id).cpu;
                    function_cpu_work / mean_node_cpu
                });
                let cpu_bounded_terminal_guard_allows = self
                    .settings
                    .operational_expert_proxy
                    .cpu_bounded_terminal_guard_allows(
                        parents_all_done,
                        terminal_function,
                        env.func(fn_id).cpu,
                        mean_node_cpu,
                        !self
                            .settings
                            .operational_expert_proxy
                            .uses_capacity_overload_cpu_bounded_terminal_guard()
                            || self.capacity_overload_cpu_guard_active_this_window,
                    );
                if self
                    .settings
                    .operational_expert_proxy
                    .uses_cpu_bounded_terminal_guard()
                    && terminal_function
                {
                    if parents_all_done {
                        if terminal_cpu_ratio
                            .is_some_and(|ratio| ratio > V168_CPU_BOUNDED_TERMINAL_RATIO_THRESHOLD)
                        {
                            self.cpu_bounded_terminal_parents_completed_heavy_bypass_this_window +=
                                1;
                        }
                    } else if cpu_bounded_terminal_guard_allows {
                        self.cpu_bounded_terminal_admitted_incomplete_parents_this_window += 1;
                        if let Some(ratio) = terminal_cpu_ratio {
                            if self
                                .settings
                                .operational_expert_proxy
                                .uses_capacity_overload_cpu_bounded_terminal_guard()
                                && !self.capacity_overload_cpu_guard_active_this_window
                                && ratio > V168_CPU_BOUNDED_TERMINAL_RATIO_THRESHOLD
                            {
                                self.capacity_overload_guard_inactive_heavy_admissions_this_window +=
                                    1;
                            }
                            self.cpu_bounded_terminal_admitted_ratio_max_this_window = Some(
                                self.cpu_bounded_terminal_admitted_ratio_max_this_window
                                    .map_or(ratio, |current| current.max(ratio)),
                            );
                        }
                    } else {
                        self.cpu_bounded_terminal_rejected_heavy_incomplete_parents_this_window +=
                            1;
                        if let Some(ratio) = terminal_cpu_ratio {
                            self.cpu_bounded_terminal_rejected_ratio_min_this_window = Some(
                                self.cpu_bounded_terminal_rejected_ratio_min_this_window
                                    .map_or(ratio, |current| current.min(ratio)),
                            );
                        }
                    }
                }
                let completion_proximal_nonterminal_function = !terminal_function
                    && self.function_children.get(&fn_id).is_some_and(|children| {
                        !children.is_empty()
                            && children
                                .iter()
                                .all(|child| self.terminal_functions.contains(child))
                    });
                let jit_parent_tail_decision = (self
                    .settings
                    .operational_expert_proxy
                    .requires_jit_parent_tail_short_work()
                    && !parents_all_done
                    && !terminal_function
                    && request_remaining_work <= V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
                    && operational_queue_density < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD)
                    .then(|| {
                        self.jit_parent_tail_decision(
                            request.req_id,
                            &request.done_fns,
                            fn_id,
                            &current_jit_parent_task_observations,
                            self.operational_frame,
                        )
                    });
                let jit_parent_tail_ready = matches!(
                    jit_parent_tail_decision,
                    Some(JitParentTailDecision::Admit { .. })
                );
                let base_frontier_admits = self
                    .settings
                    .operational_expert_proxy
                    .terminal_pipeline_frontier_admits(
                        parents_all_done,
                        terminal_function,
                        completion_proximal_nonterminal_function,
                        jit_parent_tail_ready,
                        request_remaining_work,
                        operational_queue_density,
                    )
                    && cpu_bounded_terminal_guard_allows;
                let is_one_outstanding_short_candidate = uses_one_outstanding_credit
                    && !parents_all_done
                    && !terminal_function
                    && request_remaining_work <= V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
                    && operational_queue_density < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD;
                let one_outstanding_credit_admits = !is_one_outstanding_short_candidate
                    || selected_one_outstanding_candidate == Some(fn_id);
                let is_lifetime_credit_short_candidate = uses_lifetime_credit
                    && !parents_all_done
                    && !terminal_function
                    && request_remaining_work <= V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
                    && operational_queue_density < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD;
                let lifetime_credit_admits = !is_lifetime_credit_short_candidate
                    || (lifetime_credit_available_before
                        && selected_lifetime_credit_candidate == Some(fn_id));
                if !base_frontier_admits
                    || !one_outstanding_credit_admits
                    || !lifetime_credit_admits
                {
                    self.terminal_pipeline_rejected_nonterminal_incomplete_parents_this_window += 1;
                    if base_frontier_admits
                        && is_one_outstanding_short_candidate
                        && !one_outstanding_credit_admits
                    {
                        if outstanding_before > 0 {
                            self.one_outstanding_credit_rejected_occupied_this_window += 1;
                        } else {
                            self.one_outstanding_credit_rejected_not_selected_this_window += 1;
                        }
                    }
                    if base_frontier_admits
                        && is_lifetime_credit_short_candidate
                        && !lifetime_credit_admits
                    {
                        if !lifetime_credit_available_before {
                            let second_age_too_young = self
                                .settings
                                .operational_expert_proxy
                                .lifetime_credit_second_min_age_windows()
                                .is_some_and(|minimum_age| {
                                    self.lifetime_credit_consumed_requests
                                        .contains(&request.req_id)
                                        && !self
                                            .sequential_credit_second_consumed_requests
                                            .contains(&request.req_id)
                                        && lifetime_credit_second_outstanding_limit
                                            .is_some_and(|limit| outstanding_before <= limit)
                                        && self
                                            .aged_credit_first_admission_frames
                                            .get(&request.req_id)
                                            .is_some_and(|first_frame| {
                                                self.operational_frame.saturating_sub(*first_frame)
                                                    < minimum_age
                                            })
                                });
                            if second_age_too_young {
                                self.aged_credit_second_rejected_too_young_this_window += 1;
                            } else if lifetime_credit_second_outstanding_limit
                                .is_some_and(|limit| outstanding_before > limit)
                                && self
                                    .lifetime_credit_consumed_requests
                                    .contains(&request.req_id)
                                && !self
                                    .sequential_credit_second_consumed_requests
                                    .contains(&request.req_id)
                            {
                                self.sequential_credit_rejected_while_outstanding_this_window += 1;
                            } else {
                                self.lifetime_credit_rejected_already_consumed_this_window += 1;
                            }
                        } else {
                            self.lifetime_credit_rejected_not_selected_this_window += 1;
                        }
                    }
                    if self
                        .settings
                        .operational_expert_proxy
                        .short_work_pipeline_remaining_work_threshold()
                        .is_some_and(|threshold| request_remaining_work > threshold)
                    {
                        self.short_work_pipeline_rejected_remaining_work_min_this_window = Some(
                            self.short_work_pipeline_rejected_remaining_work_min_this_window
                                .map_or(request_remaining_work, |current| {
                                    current.min(request_remaining_work)
                                }),
                        );
                    }
                    if self
                        .settings
                        .operational_expert_proxy
                        .short_work_pipeline_queue_density_threshold()
                        .is_some_and(|threshold| {
                            request_remaining_work
                                <= V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
                                && operational_queue_density >= threshold
                        })
                    {
                        self.short_work_pipeline_rejected_at_or_above_queue_threshold_this_window +=
                            1;
                        self.short_work_pipeline_rejected_queue_density_min_this_window = Some(
                            self.short_work_pipeline_rejected_queue_density_min_this_window
                                .map_or(operational_queue_density, |current| {
                                    current.min(operational_queue_density)
                                }),
                        );
                    }
                    if self
                        .settings
                        .operational_expert_proxy
                        .requires_completion_proximal_short_work()
                        && request_remaining_work
                            <= V158_SHORT_WORK_PIPELINE_REMAINING_WORK_THRESHOLD
                        && operational_queue_density < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD
                        && !terminal_function
                        && !completion_proximal_nonterminal_function
                    {
                        self.deeper_short_work_rejected_this_window += 1;
                    }
                    if let Some(JitParentTailDecision::Reject {
                        reason,
                        max_tail_to_cold_start_ratio,
                        ..
                    }) = jit_parent_tail_decision
                    {
                        match reason {
                            JitParentTailRejection::MissingCurrent
                            | JitParentTailRejection::MissingPreviousOrNonconsecutive => {
                                self.jit_parent_tail_rejected_missing_or_nonconsecutive_this_window +=
                                    1;
                            }
                            JitParentTailRejection::Inactive => {
                                self.jit_parent_tail_rejected_inactive_this_window += 1;
                            }
                            JitParentTailRejection::ZeroColdStart
                            | JitParentTailRejection::InvalidWork
                            | JitParentTailRejection::ZeroService => {
                                self.jit_parent_tail_rejected_invalid_or_zero_service_this_window +=
                                    1;
                            }
                            JitParentTailRejection::TailLongerThanColdStart => {
                                self.jit_parent_tail_rejected_over_cold_start_this_window += 1;
                                if let Some(ratio) = max_tail_to_cold_start_ratio {
                                    self.jit_parent_tail_rejected_over_cold_start_min_ratio_this_window =
                                        Some(
                                            self.jit_parent_tail_rejected_over_cold_start_min_ratio_this_window
                                                .map_or(ratio, |current| current.min(ratio)),
                                        );
                                }
                            }
                        }
                    }
                    continue;
                }
                if self
                    .settings
                    .operational_expert_proxy
                    .uses_terminal_pipeline_frontier()
                    && !parents_all_done
                {
                    if terminal_function {
                        self.terminal_pipeline_admitted_incomplete_parents_this_window += 1;
                    } else {
                        self.short_work_pipeline_admitted_nonterminal_incomplete_parents_this_window +=
                            1;
                        if is_one_outstanding_short_candidate {
                            admitted_one_outstanding_for_request += 1;
                            self.one_outstanding_credit_admitted_this_window += 1;
                        }
                        if self
                            .settings
                            .operational_expert_proxy
                            .requires_completion_proximal_short_work()
                        {
                            debug_assert!(completion_proximal_nonterminal_function);
                            self.completion_proximal_short_work_admitted_this_window += 1;
                        }
                        if let Some(JitParentTailDecision::Admit {
                            unfinished_parent_count,
                            max_predicted_remaining_frames,
                            max_tail_to_cold_start_ratio,
                        }) = jit_parent_tail_decision
                        {
                            debug_assert!(unfinished_parent_count > 0);
                            self.jit_parent_tail_admitted_this_window += 1;
                            if !completion_proximal_nonterminal_function {
                                self.jit_parent_tail_admitted_deeper_this_window += 1;
                            }
                            self.jit_parent_tail_admitted_max_predicted_frames_this_window = Some(
                                self.jit_parent_tail_admitted_max_predicted_frames_this_window
                                    .map_or(max_predicted_remaining_frames, |current| {
                                        current.max(max_predicted_remaining_frames)
                                    }),
                            );
                            self.jit_parent_tail_admitted_max_ratio_this_window = Some(
                                self.jit_parent_tail_admitted_max_ratio_this_window
                                    .map_or(max_tail_to_cold_start_ratio, |current| {
                                        current.max(max_tail_to_cold_start_ratio)
                                    }),
                            );
                        }
                        self.short_work_pipeline_admitted_remaining_work_max_this_window = Some(
                            self.short_work_pipeline_admitted_remaining_work_max_this_window
                                .map_or(request_remaining_work, |current| {
                                    current.max(request_remaining_work)
                                }),
                        );
                        self.short_work_pipeline_admitted_queue_density_max_this_window = Some(
                            self.short_work_pipeline_admitted_queue_density_max_this_window
                                .map_or(operational_queue_density, |current| {
                                    current.max(operational_queue_density)
                                }),
                        );
                    }
                }
                let player = PlayerId {
                    req_id: request.req_id,
                    fn_id,
                };
                if !request.fn_node.contains_key(&fn_id)
                    && self.function_profiles.contains_key(&fn_id)
                {
                    let parent_placements = self
                        .function_parents
                        .get(&fn_id)
                        .into_iter()
                        .flatten()
                        .filter_map(|parent_fn_id| {
                            let node_id = request.fn_node.get(parent_fn_id).copied()?;
                            let output_mb = self
                                .function_profiles
                                .get(parent_fn_id)
                                .map(|profile| profile.output_mb.max(0.0))
                                .unwrap_or(0.0);
                            Some((node_id, output_mb))
                        })
                        .collect::<Vec<_>>();
                    self.player_parent_placements
                        .insert(player, parent_placements);
                    let current_parent_nodes = self
                        .function_parents
                        .get(&fn_id)
                        .into_iter()
                        .flatten()
                        .filter_map(|parent_fn_id| {
                            request
                                .fn_node
                                .get(parent_fn_id)
                                .copied()
                                .map(|node_id| (*parent_fn_id, node_id))
                        })
                        .collect::<Vec<_>>();
                    for (parent_fn_id, node_id) in current_parent_nodes {
                        self.v138_player_parent_nodes
                            .insert((player, parent_fn_id), node_id);
                    }
                    if let Some(&rank) = critical_path_rank.get(&fn_id) {
                        self.player_critical_path_rank.insert(player, rank);
                    }
                    if uses_srpt_order {
                        self.player_request_remaining_work
                            .insert(player, request_remaining_work);
                    }
                    if is_lifetime_credit_short_candidate {
                        admitted_lifetime_credit_for_request += 1;
                        self.lifetime_credit_candidate_players_this_window
                            .insert(player);
                        if uses_lifetime_credit2 {
                            self.sequential_credit_candidate_outstanding_before_this_window
                                .insert(player, outstanding_before);
                        }
                    }
                    if self
                        .settings
                        .operational_expert_proxy
                        .uses_ready_antihotspot()
                        && parents_all_done
                    {
                        self.ready_antihotspot_players_this_window.insert(player);
                    }
                    players.push(player);
                }
            }
            if uses_one_outstanding_credit {
                let projected = outstanding_before + admitted_one_outstanding_for_request;
                self.one_outstanding_credit_projected_max_this_window = self
                    .one_outstanding_credit_projected_max_this_window
                    .max(projected);
                if projected > 1 {
                    self.one_outstanding_credit_projected_requests_over_limit_this_window += 1;
                }
            }
            if let Some(second_outstanding_limit) = lifetime_credit_second_outstanding_limit {
                self.sequential_credit_selected_per_request_max_this_window = self
                    .sequential_credit_selected_per_request_max_this_window
                    .max(admitted_lifetime_credit_for_request);
                let projected = outstanding_before + admitted_lifetime_credit_for_request;
                self.sequential_credit_projected_outstanding_max_this_window = self
                    .sequential_credit_projected_outstanding_max_this_window
                    .max(projected);
                if projected > second_outstanding_limit + 1 {
                    self.sequential_credit_projected_requests_over_limit_this_window += 1;
                }
            }
            if let Some(demand_config) = self
                .settings
                .operational_expert_proxy
                .native_expert_demand_config()
            {
                for fn_id in schedule_helper::collect_task_to_sche(request, env, demand_config) {
                    if !request.fn_node.contains_key(&fn_id)
                        && self.function_profiles.contains_key(&fn_id)
                    {
                        *self.player_function_demand.entry(fn_id).or_default() += 1;
                    }
                }
            }
        }
        if uses_one_outstanding_credit {
            self.one_outstanding_credit_previous_occupied_requests =
                current_one_outstanding_occupied_requests;
        } else {
            self.one_outstanding_credit_previous_occupied_requests
                .clear();
        }
        if self
            .settings
            .operational_expert_proxy
            .native_expert_demand_config()
            .is_none()
        {
            for player in &players {
                *self.player_function_demand.entry(player.fn_id).or_default() += 1;
            }
        }
        self.update_operational_jiagu_forecast(env.core().current_frame());
        if self.settings.operational_expert_proxy.uses_srpt_order() {
            self.sort_srpt_players(&mut players);
        } else if self
            .settings
            .operational_expert_proxy
            .uses_faasrank_native_player_order()
        {
            // `requests.values()` and the registered dependency frontier above
            // retain the same iteration order as FaaSRank's native
            // `requests.iter()` loop.  Do not impose the legacy NSESche
            // PlayerId sort on these explicitly registered anchor profiles.
        } else if self.settings.operational_structural_proxy
            || self.settings.operational_adaptive_proxy
            || matches!(
                self.settings.operational_expert_proxy,
                OperationalExpertProxy::Orion
                    | OperationalExpertProxy::OrionLoadFaithful
                    | OperationalExpertProxy::FaasrankOrionBorda
                    | OperationalExpertProxy::Faasrank2OrionBorda
                    | OperationalExpertProxy::FaasrankOrionLoadLeastBorda
                    | OperationalExpertProxy::Faasrank2OrionLoadLeastBorda
                    | OperationalExpertProxy::Faasrank2OrionLoadLeast2Borda
                    | OperationalExpertProxy::Structural
            )
        {
            players.sort_by(|left, right| {
                left.req_id
                    .cmp(&right.req_id)
                    .then_with(|| {
                        self.player_critical_path_rank
                            .get(right)
                            .copied()
                            .unwrap_or(0.0)
                            .total_cmp(
                                &self
                                    .player_critical_path_rank
                                    .get(left)
                                    .copied()
                                    .unwrap_or(0.0),
                            )
                    })
                    .then_with(|| left.fn_id.cmp(&right.fn_id))
            });
        } else if self.uses_jiagu_forecast_order() {
            players.sort_by(|left, right| {
                self.operational_jiagu_predicted_demand
                    .get(&right.fn_id)
                    .copied()
                    .unwrap_or(0.0)
                    .total_cmp(
                        &self
                            .operational_jiagu_predicted_demand
                            .get(&left.fn_id)
                            .copied()
                            .unwrap_or(0.0),
                    )
                    .then_with(|| left.cmp(right))
            });
        } else if let Some((require_resource_orientation, require_topology_bound)) = self
            .settings
            .operational_expert_proxy
            .v56_frontier_predicates()
        {
            if self
                .v56_frontier_prefers_faasrank(require_resource_orientation, require_topology_bound)
            {
                players.sort_unstable();
            } else {
                players.sort_by(|left, right| {
                    self.player_function_demand
                        .get(&right.fn_id)
                        .copied()
                        .unwrap_or(0)
                        .cmp(
                            &self
                                .player_function_demand
                                .get(&left.fn_id)
                                .copied()
                                .unwrap_or(0),
                        )
                        .then_with(|| left.cmp(right))
                });
            }
        } else if matches!(
            self.settings.operational_expert_proxy,
            OperationalExpertProxy::JiaguCurrentDemand
                | OperationalExpertProxy::JiaguForecastWidth
                | OperationalExpertProxy::GreedyJiaguCurrentDemand
                | OperationalExpertProxy::LoadLeastCurrentDemand
                | OperationalExpertProxy::OcsCurrentDemand
                | OperationalExpertProxy::OcsSingletonLoadLeastBurst
                | OperationalExpertProxy::LoadLeastFaasrankTieCurrentDemand
                | OperationalExpertProxy::FaasrankSingletonLoadLeastBurst
                | OperationalExpertProxy::FaasrankSingletonHikuBurst
                | OperationalExpertProxy::FaasrankSingletonHikuLoadFaithfulBurst
                | OperationalExpertProxy::FaasrankSingletonJiaguBurst
                | OperationalExpertProxy::FaasrankJiaguBordaCurrentDemand
                | OperationalExpertProxy::FaasrankJiaguLoadLeastBordaCurrentDemand
                | OperationalExpertProxy::Faasrank2JiaguLoadLeastBordaCurrentDemand
                | OperationalExpertProxy::Faasrank2JiaguBordaCurrentDemand
                | OperationalExpertProxy::Faasrank3JiaguLoadLeastBordaCurrentDemand
                | OperationalExpertProxy::Equal3SingletonFaasrank2JiaguBurst
                | OperationalExpertProxy::Faasrank2JiaguSingletonEqual3Burst
                | OperationalExpertProxy::Faasrank2JiaguLoadLeastSingletonEqual3Burst
                | OperationalExpertProxy::WarmGatedSingletonBordaEqual3Burst
                | OperationalExpertProxy::IdleWarmGatedSingletonBordaEqual3Burst
                | OperationalExpertProxy::WarmComplementSingletonBordaEqual3Burst
                | OperationalExpertProxy::Queue8BandedWarmLoadLeastIdleWarm
                | OperationalExpertProxy::Queue12BandedWarmLoadLeastIdleWarm
                | OperationalExpertProxy::Queue16BandedWarmLoadLeastIdleWarm
        ) {
            players.sort_by(|left, right| {
                self.player_function_demand
                    .get(&right.fn_id)
                    .copied()
                    .unwrap_or(0)
                    .cmp(
                        &self
                            .player_function_demand
                            .get(&left.fn_id)
                            .copied()
                            .unwrap_or(0),
                    )
                    .then_with(|| left.cmp(right))
            });
        } else {
            players.sort_unstable();
        }
        players.dedup();
        if self
            .settings
            .operational_expert_proxy
            .requires_jit_parent_tail_short_work()
        {
            self.jit_parent_task_observations = current_jit_parent_task_observations;
        } else {
            self.jit_parent_task_observations.clear();
        }
        players
    }

    fn ensure_network_proxy(&mut self, env: &SimEnvObserve) {
        let node_count = env.node_cnt();
        if self.network_initialized && self.network_node_count == node_count {
            return;
        }
        self.network_initialized = true;
        self.network_node_count = node_count;
        if node_count < 2 {
            self.network_beta_proxy = 1.0;
            self.network_latency_mean_ms = 0.0;
            self.network_latency_max_ms = 0.0;
            return;
        }

        let mut link_latencies = Vec::with_capacity(node_count * (node_count - 1));
        for first in 0..node_count {
            for second in 0..node_count {
                if first == second {
                    continue;
                }
                let speed_mb_s = env.node_get_speed_btwn(first, second);
                if speed_mb_s > EPSILON {
                    // The simulator exposes configured MB/s rather than measured
                    // RTT.  One-MB transfer time is therefore used as an explicit
                    // latency proxy for Eq. (14), never reported as physical RTT.
                    link_latencies.push(1000.0 / speed_mb_s);
                }
            }
        }
        if link_latencies.is_empty() {
            self.network_beta_proxy = 1.0;
            self.network_latency_mean_ms = 0.0;
            self.network_latency_max_ms = 0.0;
            return;
        }
        let latency_sum = link_latencies.iter().sum::<f32>();
        let measured_max = link_latencies.iter().copied().fold(0.0f32, f32::max);
        self.network_latency_mean_ms = latency_sum / link_latencies.len() as f32;
        self.network_latency_max_ms = measured_max;
    }

    fn update_dynamic_network_proxy(
        &mut self,
        env: &SimEnvObserve,
        transfers: &[(NodeId, NodeId, f32)],
    ) {
        let node_count = self.node_snapshots.len();
        self.network_beta_proxy = 1.0;
        self.active_network_transfers = 0;
        self.active_network_remaining_mb = 0.0;
        self.dynamic_link_delay_mean_ms = 0.0;
        self.dynamic_link_delay_max_ms = 0.0;
        self.saturated_dynamic_links = 0;
        if node_count < 2 {
            self.network_latency_normalizer_used_ms =
                self.settings.network_latency_normalizer_ms.unwrap_or(0.0);
            return;
        }

        let mut link_delay_ms = vec![0.0f32; node_count * node_count];
        for &(source, destination, remaining_mb) in transfers {
            if source >= node_count
                || destination >= node_count
                || source == destination
                || remaining_mb <= EPSILON
            {
                continue;
            }
            self.active_network_transfers += 1;
            self.active_network_remaining_mb += remaining_mb;
            let speed_mb_s = env.node_get_speed_btwn(source, destination);
            if speed_mb_s > EPSILON {
                link_delay_ms[source * node_count + destination] +=
                    remaining_mb / speed_mb_s * 1000.0;
            }
        }

        let pair_count = node_count * (node_count - 1);
        let mut delay_sum = 0.0f32;
        let mut delay_max = 0.0f32;
        for source in 0..node_count {
            for destination in 0..node_count {
                if source == destination {
                    continue;
                }
                let delay = link_delay_ms[source * node_count + destination];
                delay_sum += delay;
                delay_max = delay_max.max(delay);
            }
        }
        self.dynamic_link_delay_mean_ms = delay_sum / pair_count as f32;
        self.dynamic_link_delay_max_ms = delay_max;
        let latency_bound = self
            .settings
            .network_latency_normalizer_ms
            .unwrap_or(self.network_latency_max_ms.max(EPSILON));
        self.network_latency_normalizer_used_ms = latency_bound;
        let mut normalized_delay_sum = 0.0f32;
        for source in 0..node_count {
            for destination in 0..node_count {
                if source == destination {
                    continue;
                }
                let delay = link_delay_ms[source * node_count + destination];
                if delay > latency_bound {
                    self.saturated_dynamic_links += 1;
                }
                // Eq. (14) normalizes by the configured l_max; it does not
                // saturate an observed delay that exceeds that bound.  Keep
                // the ratio itself so overload remains visible in beta, and
                // count above-bound links separately for observability.
                normalized_delay_sum += (delay / latency_bound).max(0.0);
            }
        }
        self.network_beta_proxy = 1.0 + normalized_delay_sum / pair_count as f32;
    }

    fn update_node_snapshots(&mut self, env: &SimEnvObserve) {
        self.ensure_network_proxy(env);
        let node_count = env.node_cnt();
        self.node_snapshots = vec![NodeSnapshot::default(); node_count];
        self.node_queue_cpu_works = vec![None; node_count];
        self.available_container_memory = vec![0.0; node_count];
        self.existing_containers.clear();
        self.warm_containers.clear();
        self.idle_warm_containers.clear();
        self.function_node_resident_tasks.clear();
        let mut active_transfers = Vec::new();

        let requests = env.core().requests();
        let nodes = env.nodes();
        let queue_breakdowns = nodes
            .iter()
            .map(|node| node.queue_breakdown(env))
            .collect::<Vec<_>>();
        let queue_cpu_works = nodes
            .iter()
            .map(|node| node.queue_cpu_work(env))
            .collect::<Vec<_>>();
        let queue_lengths = queue_breakdowns
            .iter()
            .map(|queue| queue.pressure_queue_len())
            .collect::<Vec<_>>();
        self.queue_normalizer_used = match self.settings.queue_normalization_mode {
            QueueNormalizationMode::WindowMax => window_queue_normalizer(queue_lengths.iter()),
            QueueNormalizationMode::Fixed => self
                .settings
                .fixed_queue_normalizer
                .unwrap_or(1.0)
                .max(EPSILON),
        };
        for ((node, queue), queue_cpu_work) in nodes
            .iter()
            .zip(queue_breakdowns)
            .zip(queue_cpu_works.iter())
        {
            let node_id = node.node_id();
            let cpu_utilization = if node.rsc_limit.cpu > EPSILON {
                (node.cpu / node.rsc_limit.cpu).clamp(0.0, 1.0)
            } else {
                0.0
            };
            let memory_utilization = if node.rsc_limit.mem > EPSILON {
                (node.unready_mem() / node.rsc_limit.mem).clamp(0.0, 1.0)
            } else {
                0.0
            };
            let resident_tasks = queue.resident_total();
            debug_assert_eq!(resident_tasks, node.running_task_cnt());
            let (container_count, running_containers) = {
                let containers = node.fn_containers.borrow();
                let mut function_ids = containers.keys().copied().collect::<Vec<_>>();
                function_ids.sort_unstable();
                let mut running_containers = 0usize;
                for fn_id in function_ids {
                    let container = containers
                        .get(&fn_id)
                        .expect("function ID came from the container map");
                    self.existing_containers.insert((fn_id, node_id));
                    if container.is_running() {
                        running_containers += 1;
                        self.warm_containers.insert((fn_id, node_id));
                        self.function_node_resident_tasks
                            .insert((fn_id, node_id), container.req_fn_state.len());
                        if container.req_fn_state.is_empty() {
                            self.idle_warm_containers.insert((fn_id, node_id));
                        }
                        let parents = self.function_parents.get(&fn_id);
                        let mut request_ids =
                            container.req_fn_state.keys().copied().collect::<Vec<_>>();
                        request_ids.sort_unstable();
                        for req_id in request_ids {
                            let task = container
                                .req_fn_state
                                .get(&req_id)
                                .expect("request ID came from the running-task map");
                            let parents_all_done = requests
                                .get(&req_id)
                                .map(|request| {
                                    parents.is_none_or(|parents| {
                                        parents
                                            .iter()
                                            .all(|parent| request.done_fns.contains_key(parent))
                                    })
                                })
                                .unwrap_or(false);
                            if !parents_all_done {
                                continue;
                            }
                            let mut source_nodes =
                                task.data_recv.keys().copied().collect::<Vec<_>>();
                            source_nodes.sort_unstable();
                            for source in source_nodes {
                                let &(need_mb, received_mb) = task
                                    .data_recv
                                    .get(&source)
                                    .expect("source node came from the transfer map");
                                let remaining_mb = (need_mb - received_mb).max(0.0);
                                if remaining_mb > EPSILON {
                                    active_transfers.push((source, node_id, remaining_mb));
                                }
                            }
                        }
                    }
                }
                (containers.len(), running_containers)
            };
            // Eq. (6)'s q_n(t) counts work that can contend for execution now.
            // Tasks blocked by a cold-start, unfinished DAG parents, or input
            // transfer remain observable below but do not inflate CPU queue
            // pressure until they become runnable.
            let queue_ratio =
                normalized_queue_pressure(queue.pressure_queue_len(), self.queue_normalizer_used);
            let pressure = cpu_utilization + memory_utilization + queue_ratio;
            let utilization = ((cpu_utilization + memory_utilization) * 0.5).clamp(0.0, 1.0);
            self.node_snapshots[node_id] = NodeSnapshot {
                cpu_capacity: node.rsc_limit.cpu,
                cpu_utilization,
                memory_utilization,
                memory_used: node.unready_mem().max(0.0),
                memory_limit: node.rsc_limit.mem.max(EPSILON),
                pending_tasks: queue.pending,
                runnable_tasks: queue.runnable,
                pending_cpu_work: queue_cpu_work.as_ref().map(|work| work.pending_cpu),
                runnable_cpu_work: queue_cpu_work.as_ref().map(|work| work.runnable_cpu),
                runnable_remaining_cpu_work: queue_cpu_work
                    .as_ref()
                    .map(|work| work.runnable_remaining_cpu),
                resident_remaining_cpu_work: queue_cpu_work
                    .as_ref()
                    .map(|work| work.resident_remaining_cpu),
                parent_blocked_tasks: queue.parent_blocked,
                data_blocked_tasks: queue.data_blocked,
                starting_resident_tasks: queue.starting_resident,
                resident_tasks,
                container_count,
                running_containers,
                pressure,
                utilization,
            };
            self.available_container_memory[node_id] = node.left_mem_for_place_container().max(0.0);
        }
        self.node_queue_cpu_works = queue_cpu_works;
        drop(nodes);
        drop(requests);
        self.update_dynamic_network_proxy(env, &active_transfers);
    }

    /// Snapshot the common placement-feasible set for every request/function
    /// player.  The request is deliberately part of the key: two invocations
    /// of the same function can have different feasible paths because their
    /// parent functions may have been placed on different nodes.
    fn update_feasible_nodes(&mut self, env: &SimEnvObserve, players: &[PlayerId]) {
        self.feasible_nodes.clear();
        self.player_node_locality_scores.clear();
        if self.settings.operational_adaptive_proxy
            || self
                .settings
                .operational_expert_proxy
                .requires_configured_bandwidth_snapshot()
        {
            let node_count = env.node_cnt();
            self.node_bandwidths = (0..node_count)
                .map(|source| {
                    (0..node_count)
                        .map(|target| {
                            if source == target {
                                f32::INFINITY
                            } else {
                                env.node_get_speed_btwn(source, target).max(EPSILON)
                            }
                        })
                        .collect()
                })
                .collect();
        } else {
            self.node_bandwidths.clear();
        }
        let requests = env.core().requests();
        for &player in players {
            let candidates = requests
                .get(&player.req_id)
                .map(|request| schedule_helper::placement_candidate_ids(request, player.fn_id, env))
                .unwrap_or_default();
            let parent_placements = self
                .player_parent_placements
                .get(&player)
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            for &node_id in &candidates {
                let mut transfer_time = 0.0_f32;
                for &(parent_node, output_mb) in parent_placements {
                    if parent_node != node_id {
                        let bandwidth = env.node_get_speed_btwn(parent_node, node_id).max(EPSILON);
                        transfer_time += output_mb / bandwidth;
                    }
                }
                let locality = if parent_placements.is_empty() {
                    1.0
                } else {
                    1.0 / (1.0 + transfer_time)
                };
                self.player_node_locality_scores
                    .insert((player, node_id), locality.clamp(0.0, 1.0));
            }
            self.feasible_nodes.insert(player, candidates);
        }
    }

    fn build_existing_aggregates(&mut self, env: &SimEnvObserve) -> Vec<NodeAggregate> {
        let mut aggregates = vec![NodeAggregate::default(); self.node_snapshots.len()];
        let requests = env.core().requests();
        let mut cross_node_assignments = 0usize;
        let mut total_assignments = 0usize;
        // `Request::fn_node` is a `HashMap`.  Its per-process iteration order
        // must not decide the order of floating-point aggregation: otherwise
        // the same tape can produce a one-ULP-different price signal and hence
        // a different bit-exact offline-reference key.  Requests themselves
        // are already held in a `BTreeMap`; make the function order explicit
        // as well so build and replay observe the same state.
        for request in requests.values() {
            let active_assignments = stable_function_assignments(&request.fn_node)
                .into_iter()
                .filter(|(fn_id, _)| !request.done_fns.contains_key(fn_id))
                .collect::<Vec<_>>();
            let distinct_nodes: HashSet<NodeId> = active_assignments
                .iter()
                .map(|&(_, node_id)| node_id)
                .collect();
            let active_assignment_count = active_assignments.len();
            total_assignments += active_assignment_count;
            if distinct_nodes.len() > 1 {
                cross_node_assignments += active_assignment_count.saturating_sub(1);
            }
            for (fn_id, node_id) in active_assignments {
                if node_id >= aggregates.len() {
                    continue;
                }
                let Some(profile) = self.function_profiles.get(&fn_id) else {
                    continue;
                };
                aggregates[node_id].request_count += 1;
                aggregates[node_id].resource_intensity_sum +=
                    profile.heterogeneity.resource_intensity;
                aggregates[node_id].impact_sum += profile.heterogeneity.impact();
            }
        }
        self.cross_node_placement_ratio = if total_assignments == 0 {
            0.0
        } else {
            cross_node_assignments as f32 / total_assignments as f32
        };
        aggregates
    }

    fn build_price_signal(&self, existing: &[NodeAggregate]) -> PriceSignal {
        let node_count = self.node_snapshots.len().max(1);
        let global_load = self
            .node_snapshots
            .iter()
            .map(|node| node.cpu_utilization + node.memory_utilization)
            .sum::<f32>()
            / node_count as f32;
        let mut baseline_prices = Vec::with_capacity(self.node_snapshots.len());
        let mut premiums = Vec::with_capacity(self.node_snapshots.len());

        for (node_id, node) in self.node_snapshots.iter().enumerate() {
            let aggregate = existing.get(node_id).copied().unwrap_or_default();
            let congestion_premium = if aggregate.request_count == 0 {
                0.0
            } else {
                (aggregate.resource_intensity_sum / aggregate.request_count as f32)
                    * node.utilization
            };
            let price = if self.settings.congestion_pricing_enabled {
                // Eqs. (11)-(12).
                self.settings.base_node_price * (1.0 + node.pressure) * (1.0 + congestion_premium)
            } else {
                self.settings.base_node_price
            };
            baseline_prices.push(if price.is_finite() {
                price.max(EPSILON)
            } else {
                self.settings.base_node_price
            });
            premiums.push(congestion_premium);
        }

        PriceSignal {
            adjusted_prices: baseline_prices.clone(),
            baseline_prices,
            node_congestion_premiums: premiums,
            global_load,
            network_congestion: self.network_beta_proxy,
        }
    }

    /// Eq. (8) sums the other functions in the current joint decision `S`.
    /// Already-running functions are represented by `Pressure(t)` and by the
    /// Eq. (12) congestion premium; seeding the game state with them as well
    /// would count the same contention twice and can make the social reference
    /// negative even for a feasible scheduling window.
    fn empty_window_aggregates(&self) -> Vec<NodeAggregate> {
        vec![NodeAggregate::default(); self.node_snapshots.len()]
    }

    fn utility(
        &self,
        player: PlayerId,
        node_id: NodeId,
        other_impact_sum: f32,
        signal: &PriceSignal,
    ) -> Option<UtilityBreakdown> {
        let profile = self.function_profiles.get(&player.fn_id)?;
        let node = self.node_snapshots.get(node_id)?;
        let price = signal.adjusted_prices.get(node_id).copied()?;
        let heterogeneity = profile.heterogeneity;

        // Eqs. (2)-(6).
        let baseline_reward = self.settings.base_utility
            * (heterogeneity.resource_intensity + heterogeneity.function_complexity);
        let cost = price * (1.0 + heterogeneity.resource_intensity);
        let quality = profile.quality_weight
            * (heterogeneity.function_complexity + heterogeneity.network_dependency)
            / (1.0 + node.pressure);

        // Eqs. (7)-(9).  Node impact sums make Eq. (8) O(1).
        let externality = if self.settings.externality_enabled {
            heterogeneity.resource_intensity * node.pressure * other_impact_sum.max(0.0)
        } else {
            0.0
        };
        let contribution = if self.settings.contribution_enabled {
            self.settings.contribution_coefficient
                * (1.0 + heterogeneity.differentiation)
                * (1.0 - node.utilization)
        } else {
            0.0
        };
        let total = baseline_reward - cost + quality - externality + contribution;
        total.is_finite().then_some(UtilityBreakdown {
            baseline_reward,
            cost,
            quality,
            externality,
            contribution,
            total,
        })
    }

    /// Estimate implementation-level completion overhead for candidates whose
    /// paper utilities are effectively indistinguishable.  This value is not
    /// part of Eqs. (2)-(9) or the reported social welfare.  It uses only the
    /// current runtime snapshot and therefore cannot consult completed-request
    /// outcomes.
    fn structural_recent_affinity(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let history = self.operational_invocation_history.get(&player.fn_id);
        let history_len = history.map(VecDeque::len).unwrap_or(0);
        let history_matches = history
            .map(|entries| entries.iter().filter(|&&seen| seen == node_id).count())
            .unwrap_or(0);
        let projected_total = state_without_player
            .function_node_counts
            .iter()
            .filter(|((fn_id, _), _)| *fn_id == player.fn_id)
            .map(|(_, &count)| count)
            .sum::<usize>();
        let projected_matches = state_without_player
            .function_node_counts
            .get(&(player.fn_id, node_id))
            .copied()
            .unwrap_or(0);
        let total = history_len.saturating_add(projected_total);
        if total == 0 {
            0.0
        } else {
            (history_matches.saturating_add(projected_matches)) as f32 / total as f32
        }
    }

    fn operational_queue_density(&self) -> f32 {
        let queued = self.node_snapshots.iter().fold(0usize, |total, node| {
            total
                .saturating_add(node.pending_tasks)
                .saturating_add(node.runnable_tasks)
        });
        queued as f32 / self.node_snapshots.len().max(1) as f32
    }

    fn adaptive_parent_locality_score(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let mut transfer_time = 0.0_f32;
        let mut placed_parent_count = 0usize;
        for &(parent_node, output_mb) in self
            .player_parent_placements
            .get(&player)
            .into_iter()
            .flatten()
        {
            placed_parent_count += 1;
            if parent_node != node_id {
                let bandwidth = self
                    .node_bandwidths
                    .get(parent_node)
                    .and_then(|row| row.get(node_id))
                    .copied()
                    .unwrap_or(EPSILON)
                    .max(EPSILON);
                transfer_time += output_mb.max(0.0) / bandwidth;
            }
        }
        for &parent_fn_id in self
            .function_parents
            .get(&player.fn_id)
            .into_iter()
            .flatten()
        {
            let parent = PlayerId {
                req_id: player.req_id,
                fn_id: parent_fn_id,
            };
            let Some(&parent_node) = state_without_player.assignments.get(&parent) else {
                continue;
            };
            placed_parent_count += 1;
            if parent_node != node_id {
                let bandwidth = self
                    .node_bandwidths
                    .get(parent_node)
                    .and_then(|row| row.get(node_id))
                    .copied()
                    .unwrap_or(EPSILON)
                    .max(EPSILON);
                let output_mb = self
                    .function_profiles
                    .get(&parent_fn_id)
                    .map(|profile| profile.output_mb.max(0.0))
                    .unwrap_or(0.0);
                transfer_time += output_mb / bandwidth;
            }
        }
        if placed_parent_count == 0 {
            1.0
        } else {
            1.0 / (1.0 + transfer_time)
        }
    }

    fn hiku_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        let projected_node_count = state_without_player
            .assignments
            .values()
            .filter(|&&assigned_node| assigned_node == node_id)
            .count();
        // Hiku removes an idle function worker from its pull queue after one
        // placement in a decision pass.  Mirror that one-shot token with the
        // current-window function/node count, then retain Hiku's running ->
        // starting -> absent fallback and least-connected tie.
        let idle_token_available = self.idle_warm_containers.contains(&(player.fn_id, node_id))
            && state_without_player
                .function_node_counts
                .get(&(player.fn_id, node_id))
                .copied()
                .unwrap_or(0)
                == 0;
        let container_rank = if idle_token_available {
            0.0
        } else if self.warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            2.0
        } else {
            3.0
        };
        let load = node.resident_tasks.saturating_add(projected_node_count) as f32;
        container_rank + load / (1.0 + load)
    }

    fn hiku_load_faithful_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        allow_idle_token: bool,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        // Hiku's `all_task_cnt()` is pending + running. The legacy proxy
        // accidentally omitted pending work, which made a heavily queued node
        // look idle under sparse load. Projected placements participate only
        // in Hiku's fallback; the one-shot idle-worker heap is ranked by the
        // pre-window active-connection snapshot.
        let base_load = node.pending_tasks.saturating_add(node.resident_tasks);
        let projected_node_count = state_without_player
            .assignments
            .values()
            .filter(|&&assigned_node| assigned_node == node_id)
            .count();
        let idle_token_available = allow_idle_token
            && self.idle_warm_containers.contains(&(player.fn_id, node_id))
            && state_without_player
                .function_node_counts
                .get(&(player.fn_id, node_id))
                .copied()
                .unwrap_or(0)
                == 0;
        if idle_token_available {
            let load = base_load as f32;
            return load / (1.0 + load);
        }
        let container_rank = if self.warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            2.0
        } else {
            3.0
        };
        let load = base_load.saturating_add(projected_node_count) as f32;
        container_rank + load / (1.0 + load)
    }

    fn hiku_expert_tie_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        use_jiagu_tie: bool,
    ) -> f32 {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        let mut ranked = candidates.clone();
        let primary = |candidate: NodeId| {
            let Some(node) = self.node_snapshots.get(candidate) else {
                return (u8::MAX, usize::MAX);
            };
            let projected = state_without_player
                .assignments
                .values()
                .filter(|&&assigned_node| assigned_node == candidate)
                .count();
            let idle_token = initializer_phase
                && self
                    .idle_warm_containers
                    .contains(&(player.fn_id, candidate))
                && state_without_player
                    .function_node_counts
                    .get(&(player.fn_id, candidate))
                    .copied()
                    .unwrap_or(0)
                    == 0;
            let container_rank = if idle_token {
                0
            } else if self.warm_containers.contains(&(player.fn_id, candidate)) {
                1
            } else if self
                .existing_containers
                .contains(&(player.fn_id, candidate))
            {
                2
            } else {
                3
            };
            let base_load = node.pending_tasks.saturating_add(node.resident_tasks);
            let load = if idle_token {
                base_load
            } else {
                base_load.saturating_add(projected)
            };
            (container_rank, load)
        };
        ranked.sort_by(|left, right| {
            primary(*left)
                .cmp(&primary(*right))
                .then_with(|| {
                    if use_jiagu_tie {
                        self.jiagu_current_demand_operational_penalty(
                            player,
                            *left,
                            state_without_player,
                        )
                        .total_cmp(
                            &self.jiagu_current_demand_operational_penalty(
                                player,
                                *right,
                                state_without_player,
                            ),
                        )
                    } else {
                        self.faasrank_operational_score(player, *right, state_without_player)
                            .total_cmp(&self.faasrank_operational_score(
                                player,
                                *left,
                                state_without_player,
                            ))
                    }
                })
                .then_with(|| left.cmp(right))
        });
        ranked
            .iter()
            .position(|&candidate| candidate == node_id)
            .map(|rank| rank as f32)
            .unwrap_or(f32::INFINITY)
    }

    fn orion_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        let projected_node_count = state_without_player
            .assignments
            .values()
            .filter(|&&assigned_node| assigned_node == node_id)
            .count();
        let warm_score = if self.warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            0.25
        } else {
            0.0
        };
        let headroom_score = 1.0 - node.utilization;
        let load = node.resident_tasks.saturating_add(projected_node_count) as f32;
        let load_score = 1.0 / (1.0 + load);
        let locality_score =
            self.adaptive_parent_locality_score(player, node_id, state_without_player);
        let score = 0.40 * headroom_score.clamp(0.0, 1.0)
            + 0.30 * warm_score
            + 0.20 * load_score
            + 0.10 * locality_score.clamp(0.0, 1.0);
        1.0 - score.clamp(0.0, 1.0)
    }

    /// Faithful Orion-P node score.  The frozen baseline uses
    /// `Node::all_task_cnt() + projected`, where `all_task_cnt()` is pending
    /// plus running work.  The legacy proxy above omitted pending work; keep
    /// it reproducible and expose the corrected state rule as a new opt-in
    /// expert.
    fn orion_load_faithful_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        let Some(aggregate) = state_without_player.node_aggregates.get(node_id) else {
            return f32::INFINITY;
        };
        let warm_score = if self.warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            0.25
        } else {
            0.0
        };
        let headroom_score = 1.0 - node.utilization;
        let load = node
            .pending_tasks
            .saturating_add(node.resident_tasks)
            .saturating_add(aggregate.request_count) as f32;
        let load_score = 1.0 / (1.0 + load);
        let locality_score =
            self.adaptive_parent_locality_score(player, node_id, state_without_player);
        let score = 0.40 * headroom_score.clamp(0.0, 1.0)
            + 0.30 * warm_score
            + 0.20 * load_score
            + 0.10 * locality_score.clamp(0.0, 1.0);
        1.0 - score.clamp(0.0, 1.0)
    }

    fn structural_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        let warm_score = if self.idle_warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.warm_containers.contains(&(player.fn_id, node_id)) {
            0.65
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            0.20
        } else {
            0.0
        };
        let headroom_score = 1.0 - node.utilization;
        let task_load = node.pending_tasks.saturating_add(node.resident_tasks) as f32
            + state_without_player
                .node_aggregates
                .get(node_id)
                .map(|aggregate| aggregate.request_count)
                .unwrap_or(usize::MAX) as f32;
        let load_score = 1.0 / (1.0 + task_load);
        let locality_score = self
            .player_node_locality_scores
            .get(&(player, node_id))
            .copied()
            .unwrap_or(1.0);
        let affinity_score = self.structural_recent_affinity(player, node_id, state_without_player);
        let structural_score = 0.425 * warm_score
            + 0.30 * headroom_score.clamp(0.0, 1.0)
            + 0.175 * load_score.clamp(0.0, 1.0)
            + 0.05 * locality_score.clamp(0.0, 1.0)
            + 0.05 * affinity_score.clamp(0.0, 1.0);
        1.0 - structural_score.clamp(0.0, 1.0)
    }

    fn adaptive_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let density = self.operational_queue_density();
        if density < OPERATIONAL_ADAPTIVE_LOW_QUEUE_DENSITY {
            self.hiku_operational_penalty(player, node_id, state_without_player)
        } else if density < OPERATIONAL_ADAPTIVE_HIGH_QUEUE_DENSITY {
            self.orion_operational_penalty(player, node_id, state_without_player)
        } else {
            self.structural_operational_penalty(player, node_id, state_without_player)
        }
    }

    fn greedy_memory_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return f32::INFINITY;
        };
        let Some(profile) = self.function_profiles.get(&player.fn_id) else {
            return f32::INFINITY;
        };
        let Some(aggregate) = state_without_player.node_aggregates.get(node_id) else {
            return f32::INFINITY;
        };
        let function_already_projected = state_without_player
            .function_node_counts
            .get(&(player.fn_id, node_id))
            .copied()
            .unwrap_or(0)
            > 0;
        let new_container_memory = if self.existing_containers.contains(&(player.fn_id, node_id))
            || function_already_projected
        {
            0.0
        } else {
            profile.required_container_memory
        };
        // Greedy orders nodes by projected memory, then task count.  Normalize
        // memory by the configured node limit so the proxy remains meaningful
        // for heterogeneous clusters; the bounded perturbation is a tie-break
        // only at simulator resource precision.
        let projected_memory = node.memory_used
            + aggregate.task_memory_sum
            + aggregate.reserved_container_memory
            + profile.raw_memory
            + new_container_memory;
        let memory_ratio = projected_memory / node.memory_limit.max(EPSILON);
        let task_count = node
            .pending_tasks
            .saturating_add(node.resident_tasks)
            .saturating_add(aggregate.request_count)
            .saturating_add(1) as f32;
        memory_ratio + 1.0e-6 * (task_count / (1.0 + task_count))
    }

    fn jiagu_current_demand_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        if !candidates.contains(&node_id) {
            return f32::INFINITY;
        }
        let static_key = |candidate: NodeId| {
            let node = self
                .node_snapshots
                .get(candidate)
                .copied()
                .unwrap_or_default();
            let container_rank = if self
                .idle_warm_containers
                .contains(&(player.fn_id, candidate))
            {
                0_u8
            } else if self.warm_containers.contains(&(player.fn_id, candidate)) {
                1
            } else if self
                .existing_containers
                .contains(&(player.fn_id, candidate))
            {
                2
            } else {
                3
            };
            let task_count = node.pending_tasks.saturating_add(node.resident_tasks);
            (container_rank, node.utilization, task_count, candidate)
        };
        let compare_static = |left: NodeId, right: NodeId| {
            let left_key = static_key(left);
            let right_key = static_key(right);
            left_key
                .0
                .cmp(&right_key.0)
                .then_with(|| left_key.1.total_cmp(&right_key.1))
                .then_with(|| left_key.2.cmp(&right_key.2))
                .then_with(|| left_key.3.cmp(&right_key.3))
        };
        let active_width = if self.uses_jiagu_forecast_width() {
            self.operational_jiagu_predicted_demand
                .get(&player.fn_id)
                .copied()
                .unwrap_or(1.0)
                .ceil()
                .max(1.0) as usize
        } else {
            self.player_function_demand
                .get(&player.fn_id)
                .copied()
                .unwrap_or(1)
                .max(1)
        }
        .min(candidates.len());
        // The rank in the former sorted clone is exactly the number of
        // candidates preceding the target in the same total order.  Counting
        // them avoids an allocation and O(C log C) comparisons for every
        // candidate score while preserving all tie-breaks byte-for-byte.
        let rank = candidates
            .iter()
            .filter(|&&candidate| compare_static(candidate, node_id).is_lt())
            .count();
        if rank >= active_width {
            return 1.0e12 + rank as f32;
        }
        // Jiagu chooses the least-loaded node within the demand-sized prefix
        // of its container/utilization ranking.  The integer multiplier makes
        // current+same-window task load lexicographically dominant over rank.
        let node = &self.node_snapshots[node_id];
        let projected = state_without_player.node_aggregates[node_id].request_count;
        let load = node
            .pending_tasks
            .saturating_add(node.resident_tasks)
            .saturating_add(projected);
        load as f32 * (active_width + 1) as f32 + rank as f32
    }

    /// Evaluate the exact Jiagu penalty for every feasible node in one shared
    /// pass.  The scalar rule above recomputes the static rank by scanning all
    /// candidates; doing that once per node inside another ordinal-rank pass
    /// creates cubic candidate work.  Sorting the same total static order once
    /// preserves every tie-break while reducing the batch to O(C log C).
    fn jiagu_current_demand_operational_penalties(
        &self,
        player: PlayerId,
        state_without_player: &AssignmentState,
    ) -> HashMap<NodeId, f32> {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return HashMap::new();
        };
        let static_key = |candidate: NodeId| {
            let node = self
                .node_snapshots
                .get(candidate)
                .copied()
                .unwrap_or_default();
            let container_rank = if self
                .idle_warm_containers
                .contains(&(player.fn_id, candidate))
            {
                0_u8
            } else if self.warm_containers.contains(&(player.fn_id, candidate)) {
                1
            } else if self
                .existing_containers
                .contains(&(player.fn_id, candidate))
            {
                2
            } else {
                3
            };
            let task_count = node.pending_tasks.saturating_add(node.resident_tasks);
            (container_rank, node.utilization, task_count, candidate)
        };
        let mut ranked = candidates.clone();
        ranked.sort_by(|left, right| {
            let left_key = static_key(*left);
            let right_key = static_key(*right);
            left_key
                .0
                .cmp(&right_key.0)
                .then_with(|| left_key.1.total_cmp(&right_key.1))
                .then_with(|| left_key.2.cmp(&right_key.2))
                .then_with(|| left_key.3.cmp(&right_key.3))
        });
        let active_width = if self.uses_jiagu_forecast_width() {
            self.operational_jiagu_predicted_demand
                .get(&player.fn_id)
                .copied()
                .unwrap_or(1.0)
                .ceil()
                .max(1.0) as usize
        } else {
            self.player_function_demand
                .get(&player.fn_id)
                .copied()
                .unwrap_or(1)
                .max(1)
        }
        .min(candidates.len());
        ranked
            .into_iter()
            .enumerate()
            .map(|(rank, node_id)| {
                let penalty = if rank >= active_width {
                    1.0e12 + rank as f32
                } else {
                    let node = &self.node_snapshots[node_id];
                    let projected = state_without_player.node_aggregates[node_id].request_count;
                    let load = node
                        .pending_tasks
                        .saturating_add(node.resident_tasks)
                        .saturating_add(projected);
                    load as f32 * (active_width + 1) as f32 + rank as f32
                };
                (node_id, penalty)
            })
            .collect()
    }

    /// Choose between two frozen baseline-faithful experts using only the
    /// current pending+runnable queue density.  Thresholds are run-level
    /// preregistered constants; no completion-derived observation is read.
    fn jiagu_hiku_queue_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        hiku_threshold: f32,
    ) -> f32 {
        debug_assert!(matches!(hiku_threshold as u32, 24 | 48));
        if self.operational_queue_density() < hiku_threshold {
            self.jiagu_current_demand_operational_penalty(player, node_id, state_without_player)
        } else {
            self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            )
        }
    }

    /// Fuse the two frozen baseline-faithful experts by ordinal rank rather
    /// than routing on a workload threshold.  Vote counts are fixed at the
    /// run level, and both experts inspect only the current pre-placement
    /// state.  This keeps the choice scale-free and outcome-blind.
    fn hiku_jiagu_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        hiku_votes: usize,
        jiagu_votes: usize,
    ) -> f32 {
        self.hiku_jiagu_borda_operational_penalties(
            player,
            state_without_player,
            initializer_phase,
            hiku_votes,
            jiagu_votes,
        )
        .get(&node_id)
        .copied()
        .unwrap_or(f32::INFINITY)
    }

    /// Compute both expert rankings once for the complete feasible-node set.
    /// `best_response` consumes this map directly, so each expert score is
    /// evaluated once per player/state rather than once per queried node.
    fn hiku_jiagu_borda_operational_penalties(
        &self,
        player: PlayerId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        hiku_votes: usize,
        jiagu_votes: usize,
    ) -> HashMap<NodeId, f32> {
        debug_assert!(hiku_votes > 0 && jiagu_votes > 0);
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return HashMap::new();
        };
        let candidate_count = candidates.len();
        let hiku_ranks = self.operational_ordinal_ranks(player, |candidate| {
            self.hiku_load_faithful_operational_penalty(
                player,
                candidate,
                state_without_player,
                initializer_phase,
            )
        });
        let jiagu_penalties =
            self.jiagu_current_demand_operational_penalties(player, state_without_player);
        let jiagu_ranks = self.operational_ordinal_ranks(player, |candidate| {
            jiagu_penalties
                .get(&candidate)
                .copied()
                .unwrap_or(f32::INFINITY)
        });
        candidates
            .iter()
            .copied()
            .map(|node_id| {
                let hiku_rank = hiku_ranks.get(&node_id).copied().unwrap_or(f32::INFINITY);
                let jiagu_rank = jiagu_ranks.get(&node_id).copied().unwrap_or(f32::INFINITY);
                let mut ranks = vec![hiku_rank; hiku_votes];
                ranks.extend(std::iter::repeat(jiagu_rank).take(jiagu_votes));
                (node_id, self.ordinal_borda_penalty(&ranks, candidate_count))
            })
            .collect()
    }

    /// Route between the two frozen asymmetric Hiku/Jiagu Borda profiles
    /// using only current pending+runnable tasks per node.  Low-density
    /// windows give Jiagu two votes to favor the active-width/cost side;
    /// high-density windows give Hiku two votes to favor queue relief.  The
    /// threshold is a preregistered run-level constant and no completion
    /// outcome is consulted.
    fn hiku_jiagu_queue_borda_operational_penalties(
        &self,
        player: PlayerId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        queue_density_threshold: f32,
    ) -> HashMap<NodeId, f32> {
        debug_assert!(matches!(queue_density_threshold as u32, 24 | 48));
        let (hiku_votes, jiagu_votes) =
            if self.operational_queue_density() < queue_density_threshold {
                (1, 2)
            } else {
                (2, 1)
            };
        self.hiku_jiagu_borda_operational_penalties(
            player,
            state_without_player,
            initializer_phase,
            hiku_votes,
            jiagu_votes,
        )
    }

    fn hiku_jiagu_queue_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        queue_density_threshold: f32,
    ) -> f32 {
        self.hiku_jiagu_queue_borda_operational_penalties(
            player,
            state_without_player,
            initializer_phase,
            queue_density_threshold,
        )
        .get(&node_id)
        .copied()
        .unwrap_or(f32::INFINITY)
    }

    fn greedy_jiagu_current_demand_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        if self
            .player_function_demand
            .get(&player.fn_id)
            .copied()
            .unwrap_or(1)
            > 1
        {
            self.jiagu_current_demand_operational_penalty(player, node_id, state_without_player)
        } else {
            self.greedy_memory_operational_penalty(player, node_id, state_without_player)
        }
    }

    fn load_least_current_demand_operational_penalty(
        &self,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(load) =
            self.load_least_current_demand_projected_load(node_id, state_without_player)
        else {
            return f32::INFINITY;
        };
        // LoadLeast chooses the minimum (all_task_cnt + projected, node_id).
        // Node IDs are dense simulator indices, so this scalar preserves the
        // exact lexicographic order without introducing a fitted weight.
        let stride = self.node_snapshots.len().saturating_add(1) as f32;
        load as f32 * stride + node_id as f32
    }

    fn load_least_current_demand_projected_load(
        &self,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> Option<usize> {
        let node = self.node_snapshots.get(node_id)?;
        let aggregate = state_without_player.node_aggregates.get(node_id)?;
        Some(
            node.pending_tasks
                .saturating_add(node.resident_tasks)
                .saturating_add(aggregate.request_count),
        )
    }

    fn faasrank_recent_selection_fraction(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let mut function_decisions = 0usize;
        let mut node_decisions = 0usize;
        for &(seen_fn, seen_node) in &self.operational_faasrank_history {
            if seen_fn == player.fn_id {
                function_decisions += 1;
                if seen_node == node_id {
                    node_decisions += 1;
                }
            }
        }
        for (&(seen_fn, seen_node), &count) in &state_without_player.function_node_counts {
            if seen_fn == player.fn_id {
                function_decisions = function_decisions.saturating_add(count);
                if seen_node == node_id {
                    node_decisions = node_decisions.saturating_add(count);
                }
            }
        }
        if function_decisions == 0 {
            0.0
        } else {
            node_decisions as f32 / function_decisions as f32
        }
    }

    fn faasrank_recent_selection_fraction_in_history(
        &self,
        player: PlayerId,
        node_id: NodeId,
        history: &VecDeque<(FnId, NodeId)>,
    ) -> f32 {
        let mut function_decisions = 0usize;
        let mut node_decisions = 0usize;
        for &(seen_fn, seen_node) in history {
            if seen_fn == player.fn_id {
                function_decisions += 1;
                if seen_node == node_id {
                    node_decisions += 1;
                }
            }
        }
        if function_decisions == 0 {
            0.0
        } else {
            node_decisions as f32 / function_decisions as f32
        }
    }

    fn record_faasrank_actual_selection(
        history: &mut VecDeque<(FnId, NodeId)>,
        player: PlayerId,
        node_id: NodeId,
    ) {
        history.push_back((player.fn_id, node_id));
        while history.len() > OPERATIONAL_FAASRANK_HISTORY_LIMIT {
            history.pop_front();
        }
    }

    fn faasrank_operational_score_with_diversity(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        diversity: f32,
    ) -> f32 {
        self.faasrank_operational_components(player, node_id, state_without_player, diversity)
            .map_or(f32::NEG_INFINITY, |components| components.weighted_score())
    }

    fn faasrank_operational_components(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        diversity: f32,
    ) -> Option<FaasrankOperationalComponents> {
        let Some(node) = self.node_snapshots.get(node_id) else {
            return None;
        };
        let Some(aggregate) = state_without_player.node_aggregates.get(node_id) else {
            return None;
        };
        let warm_affinity = if self.warm_containers.contains(&(player.fn_id, node_id)) {
            1.0
        } else if self.existing_containers.contains(&(player.fn_id, node_id)) {
            0.2
        } else {
            0.0
        };
        let load_balance = 1.0
            / (1.0
                + node
                    .pending_tasks
                    .saturating_add(node.resident_tasks)
                    .saturating_add(aggregate.request_count) as f32);
        let locality = self
            .player_node_locality_scores
            .get(&(player, node_id))
            .copied()
            .unwrap_or(1.0)
            .clamp(0.0, 1.0);
        Some(FaasrankOperationalComponents {
            cpu_headroom: 1.0 - node.cpu_utilization.clamp(0.0, 1.0),
            memory_headroom: 1.0 - node.memory_utilization.clamp(0.0, 1.0),
            locality,
            warm_affinity,
            load_balance,
            diversity,
        })
    }

    /// Frozen FaaSRank exploitation score.  The calibrated baseline's
    /// epsilon exploration is intentionally omitted: this operational proxy
    /// must remain deterministic and uses no outcome-dependent tuning.
    fn faasrank_operational_score(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let diversity =
            self.faasrank_recent_selection_fraction(player, node_id, state_without_player);
        self.faasrank_operational_score_with_diversity(
            player,
            node_id,
            state_without_player,
            diversity,
        )
    }

    fn faasrank_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        -self.faasrank_operational_score(player, node_id, state_without_player)
    }

    fn terminal_ocs_router_uses_ocs(&self, player: PlayerId) -> bool {
        self.settings.operational_expert_proxy.uses_all_ocs_router()
            || (self
                .settings
                .operational_expert_proxy
                .uses_terminal_ocs_router()
                && self.terminal_functions.contains(&player.fn_id))
    }

    fn terminal_ocs_routed_score(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        decision_history: &VecDeque<(FnId, NodeId)>,
    ) -> f32 {
        if self
            .settings
            .operational_expert_proxy
            .uses_all_jiagu_router()
        {
            -self.jiagu_current_demand_operational_penalty(player, node_id, state_without_player)
        } else if self.terminal_ocs_router_uses_ocs(player) {
            -self.ocs_current_demand_operational_penalty(player, node_id, state_without_player)
        } else {
            let diversity = self.faasrank_recent_selection_fraction_in_history(
                player,
                node_id,
                decision_history,
            );
            self.faasrank_operational_score_with_diversity(
                player,
                node_id,
                state_without_player,
                diversity,
            )
        }
    }

    /// Guard post-initialization coordination around the native FaaSRank
    /// exploitation anchor.  The initializer itself remains unrestricted and
    /// outcome-blind.  A later Nash move is either disabled, or must be a
    /// strict Pareto improvement in paper utility and a preregistered online
    /// surrogate.  No completed-request metric is available on this path.
    fn faasrank_native_move_is_admissible(
        &self,
        player: PlayerId,
        old_node: NodeId,
        candidate_node: NodeId,
        old_utility: f32,
        candidate_utility: f32,
        state_without_player: &AssignmentState,
    ) -> bool {
        if candidate_node == old_node {
            return true;
        }
        if candidate_utility <= old_utility + EPSILON {
            return false;
        }
        let old_score = self.faasrank_operational_score(player, old_node, state_without_player);
        let candidate_score =
            self.faasrank_operational_score(player, candidate_node, state_without_player);
        match self.settings.operational_expert_proxy {
            OperationalExpertProxy::FaasrankNativeExploitAnchor
            | OperationalExpertProxy::FaasrankNativeFaithfulAnchor => false,
            OperationalExpertProxy::FaasrankNativeExploitScorePareto
            | OperationalExpertProxy::FaasrankNativeFaithfulScorePareto => {
                candidate_score > old_score + EPSILON
            }
            OperationalExpertProxy::FaasrankNativeExploitCompletionPareto
            | OperationalExpertProxy::FaasrankNativeFaithfulCompletionPareto
            | OperationalExpertProxy::FaasrankNativeFaithfulPipelineCompletionPareto => {
                let old_completion =
                    self.hybrid_operational_penalty(player, old_node, state_without_player);
                let candidate_completion =
                    self.hybrid_operational_penalty(player, candidate_node, state_without_player);
                candidate_score + EPSILON >= old_score
                    && candidate_completion + EPSILON < old_completion
            }
            OperationalExpertProxy::FaasrankNativeFaithfulWindowSafePareto => true,
            profile => {
                if let Some((hiku_votes, jiagu_votes)) = profile.faasrank_native_hiku_jiagu_votes()
                {
                    let old_frontier = self.hiku_jiagu_borda_operational_penalty(
                        player,
                        old_node,
                        state_without_player,
                        false,
                        hiku_votes,
                        jiagu_votes,
                    );
                    let candidate_frontier = self.hiku_jiagu_borda_operational_penalty(
                        player,
                        candidate_node,
                        state_without_player,
                        false,
                        hiku_votes,
                        jiagu_votes,
                    );
                    candidate_score + EPSILON >= old_score
                        && candidate_frontier + EPSILON < old_frontier
                } else {
                    true
                }
            }
        }
    }

    /// Reproduce frozen FaaSRank's deterministic epsilon-greedy choice on
    /// the same parent-complete frontier.  The selected node is ranked first;
    /// all other nodes retain the exploitation ordering, making this usable
    /// as an outcome-blind NSESche initializer/tie-break penalty.
    fn faasrank_ready_faithful_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        let mut ranked = candidates.clone();
        ranked.sort_by(|left, right| {
            self.faasrank_operational_score(player, *right, state_without_player)
                .total_cmp(&self.faasrank_operational_score(player, *left, state_without_player))
                .then_with(|| left.cmp(right))
        });
        if ranked.is_empty() {
            return f32::INFINITY;
        }
        let context = [
            self.operational_frame as u64,
            player.req_id as u64,
            player.fn_id as u64,
            0,
        ];
        let explore_hash = faasrank_stable_hash(&self.operational_algorithm_seed, &context);
        let selected_index = if unit_interval(explore_hash) < 0.1 {
            faasrank_stable_hash(
                &self.operational_algorithm_seed,
                &[
                    self.operational_frame as u64,
                    player.req_id as u64,
                    player.fn_id as u64,
                    1,
                ],
            ) as usize
                % ranked.len()
        } else {
            0
        };
        let Some(rank) = ranked.iter().position(|candidate| *candidate == node_id) else {
            return f32::INFINITY;
        };
        if rank == selected_index {
            0.0
        } else {
            1.0 + rank as f32
        }
    }

    /// Use Hiku's load-faithful placement rule only while current queue
    /// pressure is below a fixed, preregistered threshold. Above the
    /// threshold, retain V43's exact deterministic FaaSRank choice. The
    /// router observes current pending+runnable work only; it never reads
    /// completion outcomes or workload labels.
    fn faasrank_ready_hiku_queue_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        queue_density_threshold: f32,
    ) -> f32 {
        debug_assert!(matches!(queue_density_threshold as u32, 8 | 16 | 32));
        if self.operational_queue_density() < queue_density_threshold {
            self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            )
        } else {
            self.faasrank_ready_faithful_operational_penalty(player, node_id, state_without_player)
        }
    }

    /// Preserve exact FaaSRank selection at low queue pressure, where V44's
    /// paired baseline owned QPR, and switch to the load-faithful Orion score
    /// only at a fixed high-pressure boundary. This reads the same current
    /// pending+runnable density as the V44 router and no outcome metric.
    fn faasrank_ready_orion_queue_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        queue_density_threshold: f32,
    ) -> f32 {
        debug_assert!(matches!(queue_density_threshold as u32, 24 | 32));
        if self.operational_queue_density() < queue_density_threshold {
            self.faasrank_ready_faithful_operational_penalty(player, node_id, state_without_player)
        } else {
            self.orion_load_faithful_operational_penalty(player, node_id, state_without_player)
        }
    }

    /// Preserve V45's queue-24 Orion branch, but use the current window's
    /// repeated same-function demand to select a Hiku expert only inside the
    /// low-pressure branch. Singleton demand remains exact FaaSRank. The gate
    /// reads no completion, latency, cost, workload label, or prior outcome.
    fn faasrank_ready_repeat_hiku_orion_queue24_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        load_faithful_hiku: bool,
    ) -> f32 {
        if self.operational_queue_density() >= 24.0 {
            return self.orion_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
            );
        }
        if self
            .player_function_demand
            .get(&player.fn_id)
            .copied()
            .unwrap_or(1)
            > 1
        {
            if load_faithful_hiku {
                self.hiku_load_faithful_operational_penalty(
                    player,
                    node_id,
                    state_without_player,
                    initializer_phase,
                )
            } else {
                self.hiku_operational_penalty(player, node_id, state_without_player)
            }
        } else {
            self.faasrank_ready_faithful_operational_penalty(player, node_id, state_without_player)
        }
    }

    /// Retain V47's FaaSRank-singleton/load-faithful-Hiku-repeated router
    /// between queue densities 8 and 24 and its load-faithful Orion branch at
    /// 24 or above.  Only the preregistered ultra-low-density band can use the
    /// exact current-demand Jiagu proxy, either for every player or only for
    /// repeated same-function demand.  All gates are current pre-placement
    /// state and do not consume completion outcomes or workload labels.
    fn faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        jiagu_repeated_only: bool,
        jiagu_density_threshold: f32,
    ) -> f32 {
        debug_assert!(matches!(
            jiagu_density_threshold as u32,
            2 | 4 | 6 | 8 | 11 | 12 | 13 | 16
        ));
        let density = self.operational_queue_density();
        if density >= 24.0 {
            return self.orion_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
            );
        }
        let repeated_demand = self
            .player_function_demand
            .get(&player.fn_id)
            .copied()
            .unwrap_or(1)
            > 1;
        if density < jiagu_density_threshold && (!jiagu_repeated_only || repeated_demand) {
            self.jiagu_current_demand_operational_penalty(player, node_id, state_without_player)
        } else if repeated_demand {
            self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            )
        } else {
            self.faasrank_ready_faithful_operational_penalty(player, node_id, state_without_player)
        }
    }

    /// Add a fixed OCS-P latency/cost vote to V50's density-12 throughput
    /// router. Both experts read only the current pre-placement state. The
    /// vote counts are run-level preregistered constants, so no completion,
    /// latency, cost, workload label, or prior outcome can affect routing.
    fn faasrank_ready_repeat_jiagu_low12_ocs_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        base_votes: usize,
        ocs_votes: usize,
    ) -> f32 {
        debug_assert!((1..=2).contains(&base_votes));
        debug_assert!((1..=2).contains(&ocs_votes));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let base_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                player,
                candidate,
                state_without_player,
                initializer_phase,
                true,
                12.0,
            )
        });
        let ocs_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.ocs_current_demand_operational_penalty(player, candidate, state_without_player)
        });
        let mut ranks = vec![base_rank; base_votes];
        ranks.extend(vec![ocs_rank; ocs_votes]);
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

    /// Route three frozen outcome-blind experts by the current queue regime.
    /// Below 24 tasks/node the full profile preserves V52c's QPR-leading
    /// base1:OCS2 ordinal rule.  From 24 to below 48 it uses the exact OCS-P
    /// current-demand proxy, and at 48 or above it uses load-faithful Hiku-P.
    /// The two boolean deletions remove the low composite or middle OCS band;
    /// neither changes a vote dose or reads completion-derived observations.
    fn v53_queue_triage_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        use_v52c_low_band: bool,
        use_ocs_middle_band: bool,
    ) -> f32 {
        let density = self.operational_queue_density();
        if density < 24.0 {
            if use_v52c_low_band {
                return self.faasrank_ready_repeat_jiagu_low12_ocs_borda_operational_penalty(
                    player,
                    node_id,
                    state_without_player,
                    initializer_phase,
                    1,
                    2,
                );
            }
            return self.ocs_current_demand_operational_penalty(
                player,
                node_id,
                state_without_player,
            );
        }
        if density < 48.0 && use_ocs_middle_band {
            return self.ocs_current_demand_operational_penalty(
                player,
                node_id,
                state_without_player,
            );
        }
        self.hiku_load_faithful_operational_penalty(
            player,
            node_id,
            state_without_player,
            initializer_phase,
        )
    }

    /// Retain V53b's high-queue Hiku branch, but use Hiku inside the low
    /// queue band only when its pull-worker semantics are applicable.  The
    /// full gate requires a narrow current frontier, at least one running
    /// container per node cluster-wide, and an idle-warm feasible worker for
    /// this function.  Deletion profiles remove either the global maturity
    /// predicate or the per-player idle-worker predicate.
    fn v54_sparse_idle_hiku_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        require_maturity: bool,
        require_idle_worker: bool,
    ) -> f32 {
        if self.operational_queue_density() >= 24.0 {
            return self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            );
        }
        let node_count = self.node_snapshots.len().max(1);
        let frontier_width = self.player_function_demand.values().copied().sum::<usize>();
        let narrow_mature_cluster = frontier_width.saturating_mul(3) < node_count
            && self.warm_containers.len() >= node_count;
        let idle_worker_available =
            self.feasible_nodes
                .get(&player)
                .into_iter()
                .flatten()
                .any(|&candidate| {
                    self.idle_warm_containers
                        .contains(&(player.fn_id, candidate))
                });
        let use_hiku = (!require_maturity || narrow_mature_cluster)
            && (!require_idle_worker || idle_worker_available);
        if use_hiku {
            self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            )
        } else {
            self.faasrank_ready_repeat_jiagu_low12_ocs_borda_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
                1,
                2,
            )
        }
    }

    /// Extend V54b's narrow-frontier/mature-cluster branch with a second,
    /// independently interpretable Hiku premise: the current runnable queue
    /// is covered by current running containers and this function has an
    /// idle-warm feasible worker.  Deletion profiles remove the capacity
    /// guard or the original narrow/mature branch without changing a numeric
    /// threshold or consulting completed-request outcomes.
    fn v55_capacity_covered_idle_hiku_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
        require_capacity_coverage: bool,
        include_mature_sparse_branch: bool,
    ) -> f32 {
        if self.operational_queue_density() >= 24.0 {
            return self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            );
        }
        let node_count = self.node_snapshots.len().max(1);
        let frontier_width = self.player_function_demand.values().copied().sum::<usize>();
        let narrow_mature_cluster = frontier_width.saturating_mul(3) < node_count
            && self.warm_containers.len() >= node_count;
        let queued_work = self.node_snapshots.iter().fold(0usize, |total, snapshot| {
            total
                .saturating_add(snapshot.pending_tasks)
                .saturating_add(snapshot.runnable_tasks)
        });
        let capacity_covered = queued_work <= self.warm_containers.len();
        let idle_worker_available =
            self.feasible_nodes
                .get(&player)
                .into_iter()
                .flatten()
                .any(|&candidate| {
                    self.idle_warm_containers
                        .contains(&(player.fn_id, candidate))
                });
        let covered_idle_branch =
            idle_worker_available && (!require_capacity_coverage || capacity_covered);
        let use_hiku =
            covered_idle_branch || (include_mature_sparse_branch && narrow_mature_cluster);
        if use_hiku {
            self.hiku_load_faithful_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            )
        } else {
            self.faasrank_ready_repeat_jiagu_low12_ocs_borda_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
                1,
                2,
            )
        }
    }

    /// Summarize only the functions currently waiting on the parent-complete
    /// frontier.  Counts weight each function profile by its current request
    /// multiplicity, so the route is a property of preplacement demand rather
    /// than a static workload label.
    fn v56_frontier_profile_totals(&self) -> (usize, f32, f32, usize) {
        self.player_function_demand.iter().fold(
            (0usize, 0.0f32, 0.0f32, 0usize),
            |(instances, cpu, memory, dag_nodes), (&fn_id, &demand)| {
                let Some(profile) = self.function_profiles.get(&fn_id) else {
                    return (instances, cpu, memory, dag_nodes);
                };
                (
                    instances.saturating_add(demand),
                    cpu + profile.heterogeneity.normalized_cpu * demand as f32,
                    memory + profile.heterogeneity.normalized_memory * demand as f32,
                    dag_nodes.saturating_add(profile.dag_node_count.saturating_mul(demand)),
                )
            },
        )
    }

    /// Select the frozen ready-frontier FaaSRank expert only for a
    /// memory-oriented frontier whose mean DAG width is bounded by the current
    /// cluster width.  Deletion controls remove one semantic predicate; there
    /// is no fitted numeric threshold and no completion feedback.
    fn v56_frontier_prefers_faasrank(
        &self,
        require_resource_orientation: bool,
        require_topology_bound: bool,
    ) -> bool {
        let (instances, cpu, memory, dag_nodes) = self.v56_frontier_profile_totals();
        if instances == 0 {
            return false;
        }
        let memory_oriented = cpu <= memory;
        let topology_bounded =
            dag_nodes <= self.node_snapshots.len().max(1).saturating_mul(instances);
        (!require_resource_orientation || memory_oriented)
            && (!require_topology_bound || topology_bounded)
    }

    fn v56_resource_topology_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        require_resource_orientation: bool,
        require_topology_bound: bool,
    ) -> f32 {
        if self.v56_frontier_prefers_faasrank(require_resource_orientation, require_topology_bound)
        {
            self.faasrank_ready_faithful_operational_penalty(player, node_id, state_without_player)
        } else {
            self.ocs_current_demand_operational_penalty(player, node_id, state_without_player)
        }
    }

    fn faasrank_ready_ocs_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        faasrank_votes: usize,
    ) -> f32 {
        debug_assert!((1..=2).contains(&faasrank_votes));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let faasrank_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_operational_penalty(player, candidate, state_without_player)
        });
        let ocs_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.ocs_current_demand_operational_penalty(player, candidate, state_without_player)
        });
        let mut ranks = vec![faasrank_rank; faasrank_votes];
        ranks.push(ocs_rank);
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

    /// Integer-vote ordinal Borda over the exact frozen FaaSRank selection and
    /// exact LoadLeast ordering.  V60/V61 combine only ranks; they do not fit
    /// a continuous weight or consult outcomes.
    fn faasrank_load_least_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        faasrank_votes: usize,
        load_least_votes: usize,
    ) -> f32 {
        debug_assert!((1..=2).contains(&faasrank_votes));
        debug_assert!((1..=2).contains(&load_least_votes));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let faasrank_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_ready_faithful_operational_penalty(
                player,
                candidate,
                state_without_player,
            )
        });
        let load_least_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.load_least_current_demand_operational_penalty(candidate, state_without_player)
        });
        let mut ranks = vec![faasrank_rank; faasrank_votes];
        ranks.extend(std::iter::repeat(load_least_rank).take(load_least_votes));
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

    fn load_least_faasrank_tie_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        let mut ranked = candidates.clone();
        ranked.sort_by(|left, right| {
            let load = |candidate: NodeId| {
                self.node_snapshots
                    .get(candidate)
                    .zip(state_without_player.node_aggregates.get(candidate))
                    .map(|(node, aggregate)| {
                        node.pending_tasks
                            .saturating_add(node.resident_tasks)
                            .saturating_add(aggregate.request_count)
                    })
                    .unwrap_or(usize::MAX)
            };
            load(*left)
                .cmp(&load(*right))
                .then_with(|| {
                    self.faasrank_operational_score(player, *right, state_without_player)
                        .total_cmp(&self.faasrank_operational_score(
                            player,
                            *left,
                            state_without_player,
                        ))
                })
                .then_with(|| left.cmp(right))
        });
        ranked
            .iter()
            .position(|&candidate| candidate == node_id)
            .map(|rank| rank as f32)
            .unwrap_or(f32::INFINITY)
    }

    /// V152's input-only affinity diagnostic.  The mapping is stable for a
    /// function and a common feasible-node set, independent of request ID,
    /// seed label, load label, future arrivals, or any completion outcome.
    /// Sorting makes the choice independent of HashMap/vector iteration order.
    fn stable_function_affinity_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
    ) -> f32 {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        if !candidates.contains(&node_id) {
            return f32::INFINITY;
        }
        let mut ordered = candidates.clone();
        ordered.sort_unstable();
        ordered.dedup();
        let target = ordered[faasrank_stable_hash(
            "nse-v152-stable-function-affinity",
            &[player.fn_id as u64],
        ) as usize
            % ordered.len()];
        if node_id == target {
            0.0
        } else {
            1.0 + ordered
                .iter()
                .position(|&candidate| candidate == node_id)
                .unwrap_or(ordered.len()) as f32
        }
    }

