    fn operational_ordinal_rank<F>(&self, player: PlayerId, node_id: NodeId, mut penalty: F) -> f32
    where
        F: FnMut(NodeId) -> f32,
    {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return f32::INFINITY;
        };
        if !candidates.contains(&node_id) {
            return f32::INFINITY;
        }
        // A comparator-based sort may reevaluate an expensive expert score
        // O(C log C) times for every queried node.  Rank is exactly the count
        // of candidates ordered before the target, so evaluate each score once
        // and preserve the same (score, node-id) total order.
        let target_penalty = penalty(node_id);
        candidates
            .iter()
            .filter(|&&candidate| {
                if candidate == node_id {
                    return false;
                }
                let ordering = penalty(candidate).total_cmp(&target_penalty);
                ordering.is_lt() || (ordering.is_eq() && candidate < node_id)
            })
            .count() as f32
    }

    /// Return the same `(penalty, node-id)` total-order ranks as
    /// `operational_ordinal_rank`, evaluating each candidate penalty exactly
    /// once.  This is the batch primitive used by composite experts.
    fn operational_ordinal_ranks<F>(&self, player: PlayerId, mut penalty: F) -> HashMap<NodeId, f32>
    where
        F: FnMut(NodeId) -> f32,
    {
        let Some(candidates) = self.feasible_nodes.get(&player) else {
            return HashMap::new();
        };
        let mut ranked = candidates
            .iter()
            .copied()
            .map(|node_id| (node_id, penalty(node_id)))
            .collect::<Vec<_>>();
        ranked.sort_by(|(left_node, left_penalty), (right_node, right_penalty)| {
            left_penalty
                .total_cmp(right_penalty)
                .then_with(|| left_node.cmp(right_node))
        });
        ranked
            .into_iter()
            .enumerate()
            .map(|(rank, (node_id, _))| (node_id, rank as f32))
            .collect()
    }

    fn ordinal_borda_penalty(&self, ranks: &[f32], candidate_count: usize) -> f32 {
        if ranks.iter().any(|rank| !rank.is_finite()) {
            return f32::INFINITY;
        }
        let rank_sum = ranks.iter().sum::<f32>();
        let worst_rank = ranks.iter().copied().fold(0.0_f32, f32::max);
        // Vote-expanded Borda sum is primary.  Equal-vote profiles pass each
        // rank once; preregistered integer-majority profiles repeat a rank.
        // Worst expert rank is the deterministic tie-break; node ID is final.
        rank_sum * candidate_count.saturating_add(1) as f32 + worst_rank
    }

    fn faasrank_orion_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        faasrank_votes: usize,
    ) -> f32 {
        debug_assert!((1..=2).contains(&faasrank_votes));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let faasrank_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_operational_penalty(player, candidate, state_without_player)
        });
        let orion_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.orion_load_faithful_operational_penalty(player, candidate, state_without_player)
        });
        let mut ranks = vec![faasrank_rank; faasrank_votes];
        ranks.push(orion_rank);
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

