    fn srpt_ready_hiku2_ocs_queue8_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
    ) -> f32 {
        if self.operational_queue_density() < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD {
            self.srpt_ready_hiku_ocs_borda_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
                2,
                1,
            )
        } else {
            self.ocs_current_demand_operational_penalty(player, node_id, state_without_player)
        }
    }

    fn srpt_ready_antihotspot_hiku2_ocs_queue8_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        initializer_phase: bool,
    ) -> f32 {
        if !self.ready_antihotspot_players_this_window.contains(&player) {
            return self.srpt_ready_hiku2_ocs_queue8_operational_penalty(
                player,
                node_id,
                state_without_player,
                initializer_phase,
            );
        }
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let antihotspot_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.structural_recent_affinity(player, candidate, state_without_player)
        });
        if self.operational_queue_density() < V155_SRPT_HIKU2_OCS_QUEUE_DENSITY_THRESHOLD {
            let hiku_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
                self.hiku_load_faithful_operational_penalty(
                    player,
                    candidate,
                    state_without_player,
                    initializer_phase,
                )
            });
            let ocs_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
                self.ocs_current_demand_operational_penalty(player, candidate, state_without_player)
            });
            self.ordinal_borda_penalty(
                &[hiku_rank, hiku_rank, ocs_rank, antihotspot_rank],
                candidate_count,
            )
        } else {
            let ocs_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
                self.ocs_current_demand_operational_penalty(player, candidate, state_without_player)
            });
            self.ordinal_borda_penalty(&[ocs_rank, antihotspot_rank], candidate_count)
        }
    }

    fn faasrank_orion_load_least_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        faasrank_votes: usize,
        load_least_votes: usize,
    ) -> f32 {
        debug_assert!((1..=2).contains(&faasrank_votes));
        debug_assert!((1..=2).contains(&load_least_votes));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let faasrank_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_operational_penalty(player, candidate, state_without_player)
        });
        let orion_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.orion_load_faithful_operational_penalty(player, candidate, state_without_player)
        });
        let load_least_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.load_least_current_demand_operational_penalty(candidate, state_without_player)
        });
        let mut ranks = vec![faasrank_rank; faasrank_votes];
        ranks.push(orion_rank);
        ranks.extend(std::iter::repeat(load_least_rank).take(load_least_votes));
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

    fn hybrid3_expert_borda_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
        expert: OperationalExpertProxy,
    ) -> f32 {
        debug_assert!(matches!(
            expert,
            OperationalExpertProxy::Hybrid3FaasrankBorda
                | OperationalExpertProxy::Hybrid3OrionBorda
                | OperationalExpertProxy::Hybrid3JiaguBorda
                | OperationalExpertProxy::Hybrid3Jiagu2Borda
                | OperationalExpertProxy::Hybrid3JiaguOrionBorda
                | OperationalExpertProxy::Hybrid3JiaguFaasrankBorda
                | OperationalExpertProxy::Hybrid3GreedyBorda
                | OperationalExpertProxy::Hybrid3OcsBorda
                | OperationalExpertProxy::Hybrid3GreedyOcsBorda
                | OperationalExpertProxy::Hybrid3LoadLeastBorda
                | OperationalExpertProxy::Hybrid3LoadLeastGreedyBorda
                | OperationalExpertProxy::Hybrid3LoadLeastOcsBorda
                | OperationalExpertProxy::Hybrid3LoadLeastOcs2Borda
                | OperationalExpertProxy::Hybrid3LoadLeastOcs3Borda
                | OperationalExpertProxy::Hybrid3LoadLeast2Ocs2Borda
        ));
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let hybrid_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.hybrid_operational_penalty(player, candidate, state_without_player)
        });
        let faasrank_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.faasrank_operational_penalty(player, candidate, state_without_player)
            })
        };
        let orion_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.orion_load_faithful_operational_penalty(
                    player,
                    candidate,
                    state_without_player,
                )
            })
        };
        let jiagu_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.jiagu_current_demand_operational_penalty(
                    player,
                    candidate,
                    state_without_player,
                )
            })
        };
        let greedy_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.greedy_memory_operational_penalty(player, candidate, state_without_player)
            })
        };
        let ocs_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.ocs_current_demand_operational_penalty(player, candidate, state_without_player)
            })
        };
        let load_least_rank = || {
            self.operational_ordinal_rank(player, node_id, |candidate| {
                self.load_least_current_demand_operational_penalty(candidate, state_without_player)
            })
        };
        let mut ranks = vec![hybrid_rank, hybrid_rank, hybrid_rank];
        match expert {
            OperationalExpertProxy::Hybrid3FaasrankBorda => ranks.push(faasrank_rank()),
            OperationalExpertProxy::Hybrid3OrionBorda => ranks.push(orion_rank()),
            OperationalExpertProxy::Hybrid3JiaguBorda => ranks.push(jiagu_rank()),
            OperationalExpertProxy::Hybrid3Jiagu2Borda => {
                let rank = jiagu_rank();
                ranks.extend([rank, rank]);
            }
            OperationalExpertProxy::Hybrid3JiaguOrionBorda => {
                ranks.extend([jiagu_rank(), orion_rank()]);
            }
            OperationalExpertProxy::Hybrid3JiaguFaasrankBorda => {
                ranks.extend([jiagu_rank(), faasrank_rank()]);
            }
            OperationalExpertProxy::Hybrid3GreedyBorda => ranks.push(greedy_rank()),
            OperationalExpertProxy::Hybrid3OcsBorda => ranks.push(ocs_rank()),
            OperationalExpertProxy::Hybrid3GreedyOcsBorda => {
                ranks.extend([greedy_rank(), ocs_rank()]);
            }
            OperationalExpertProxy::Hybrid3LoadLeastBorda => ranks.push(load_least_rank()),
            OperationalExpertProxy::Hybrid3LoadLeastGreedyBorda => {
                ranks.extend([load_least_rank(), greedy_rank()]);
            }
            OperationalExpertProxy::Hybrid3LoadLeastOcsBorda => {
                ranks.extend([load_least_rank(), ocs_rank()]);
            }
            OperationalExpertProxy::Hybrid3LoadLeastOcs2Borda => {
                let ocs = ocs_rank();
                ranks.extend([load_least_rank(), ocs, ocs]);
            }
            OperationalExpertProxy::Hybrid3LoadLeastOcs3Borda => {
                let ocs = ocs_rank();
                ranks.extend([load_least_rank(), ocs, ocs, ocs]);
            }
            OperationalExpertProxy::Hybrid3LoadLeast2Ocs2Borda => {
                let load_least = load_least_rank();
                let ocs = ocs_rank();
                ranks.extend([load_least, load_least, ocs, ocs]);
            }
            _ => unreachable!("hybrid3 expert proxy was validated above"),
        }
        self.ordinal_borda_penalty(&ranks, candidate_count)
    }

    fn faasrank_jiagu_borda_current_demand_operational_penalty(
        &self,
        player: PlayerId,
        node_id: NodeId,
        state_without_player: &AssignmentState,
    ) -> f32 {
        let candidate_count = self
            .feasible_nodes
            .get(&player)
            .map(Vec::len)
            .unwrap_or_default();
        let faasrank_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.faasrank_operational_penalty(player, candidate, state_without_player)
        });
        let jiagu_rank = self.operational_ordinal_rank(player, node_id, |candidate| {
            self.jiagu_current_demand_operational_penalty(player, candidate, state_without_player)
        });
        self.ordinal_borda_penalty(&[faasrank_rank, jiagu_rank], candidate_count)
    }

