        assert!(!scheduler.faasrank_native_move_is_admissible(player, 0, 1, 1.0, 1.0, &state,));

        scheduler.settings.operational_expert_proxy =
            OperationalExpertProxy::FaasrankNativeExploitCompletionPareto;
