    #[test]
    fn v56_route_requires_memory_orientation_and_topology_bound() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.node_snapshots.resize(20, NodeSnapshot::default());
        scheduler.player_function_demand.insert(player.fn_id, 2);
        scheduler
            .function_profiles
            .insert(player.fn_id, function_profile(player.fn_id, 0.4, 0.6, 10));

        assert!(scheduler.v56_frontier_prefers_faasrank(true, true));
        assert!(scheduler.v56_frontier_prefers_faasrank(false, true));
        assert!(scheduler.v56_frontier_prefers_faasrank(true, false));

        scheduler
            .function_profiles
            .insert(player.fn_id, function_profile(player.fn_id, 0.8, 0.4, 10));
        assert!(!scheduler.v56_frontier_prefers_faasrank(true, true));
        assert!(scheduler.v56_frontier_prefers_faasrank(false, true));
        assert!(!scheduler.v56_frontier_prefers_faasrank(true, false));

        scheduler
            .function_profiles
            .insert(player.fn_id, function_profile(player.fn_id, 0.4, 0.6, 25));
        assert!(!scheduler.v56_frontier_prefers_faasrank(true, true));
        assert!(!scheduler.v56_frontier_prefers_faasrank(false, true));
        assert!(scheduler.v56_frontier_prefers_faasrank(true, false));

        scheduler.player_function_demand.clear();
        assert!(!scheduler.v56_frontier_prefers_faasrank(false, false));
    }

    #[test]
    fn low8_jiagu_router_preserves_all_preregistered_boundaries() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.operational_frame = 41;
        scheduler.node_snapshots[0].cpu_utilization = 0.9;
        scheduler.node_snapshots[0].memory_utilization = 0.9;
        scheduler.node_snapshots[0].utilization = 0.9;
        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.1;
        scheduler.node_snapshots[1].utilization = 0.1;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.idle_warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.existing_containers.insert((player.fn_id, 1));
        let state = empty_operational_state();
        let context = [
            scheduler.operational_frame as u64,
            player.req_id as u64,
            player.fn_id as u64,
            0,
        ];
        scheduler.operational_algorithm_seed = (0..10_000)
            .map(|index| format!("v48-exploit-{index}"))
            .find(|seed| unit_interval(faasrank_stable_hash(seed, &context)) >= 0.1)
            .expect("find deterministic exploitation seed");

        scheduler.node_snapshots[0].pending_tasks = 0;
        scheduler.node_snapshots[1].pending_tasks = 0;
        scheduler.player_function_demand.insert(player.fn_id, 1);
        let jiagu = scheduler.jiagu_current_demand_operational_penalty(player, 0, &state);
        let faasrank = scheduler.faasrank_ready_faithful_operational_penalty(player, 0, &state);
        assert_eq!(
            scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                player, 0, &state, true, false, 8.0,
            ),
            jiagu
        );
        assert_eq!(
            scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                player, 0, &state, true, true, 8.0,
            ),
            faasrank
        );

        scheduler.player_function_demand.insert(player.fn_id, 2);
        let jiagu = scheduler.jiagu_current_demand_operational_penalty(player, 0, &state);
        for repeated_only in [false, true] {
            assert_eq!(
                scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                    player,
                    0,
                    &state,
                    true,
                    repeated_only,
                    8.0,
                ),
                jiagu
            );
        }

        // Density equality at 8 leaves the Jiagu band. Singleton demand uses
        // FaaSRank and repeated demand uses load-faithful Hiku.
        scheduler.node_snapshots[0].pending_tasks = 16;
        scheduler.player_function_demand.insert(player.fn_id, 1);
        let faasrank = scheduler.faasrank_ready_faithful_operational_penalty(player, 0, &state);
        for repeated_only in [false, true] {
            assert_eq!(
                scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                    player,
                    0,
                    &state,
                    true,
                    repeated_only,
                    8.0,
                ),
                faasrank
            );
        }
        scheduler.player_function_demand.insert(player.fn_id, 2);
        let hiku = scheduler.hiku_load_faithful_operational_penalty(player, 0, &state, true);
        for repeated_only in [false, true] {
            assert_eq!(
                scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                    player,
                    0,
                    &state,
                    true,
                    repeated_only,
                    8.0,
                ),
                hiku
            );
        }

        // Density equality at 24 belongs to Orion for every scope and demand.
        scheduler.node_snapshots[0].pending_tasks = 48;
        let orion = scheduler.orion_load_faithful_operational_penalty(player, 0, &state);
        for demand in [1, 2] {
            scheduler
                .player_function_demand
                .insert(player.fn_id, demand);
            for repeated_only in [false, true] {
                assert_eq!(
                    scheduler.faasrank_ready_hiku_jiagu_low8_orion_queue24_operational_penalty(
                        player,
                        0,
                        &state,
                        true,
                        repeated_only,
                        8.0,
                    ),
                    orion
                );
            }
        }
    }

    #[test]
    fn faasrank_ready_faithful_reproduces_deterministic_epsilon_choice() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::FaasrankReadyFaithful;
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.operational_frame = 41;
        scheduler.node_snapshots[0].cpu_utilization = 0.9;
        scheduler.node_snapshots[0].memory_utilization = 0.9;
        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.1;
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.existing_containers.insert((player.fn_id, 1));
        let state = empty_operational_state();

        let context = [
            scheduler.operational_frame as u64,
            player.req_id as u64,
            player.fn_id as u64,
            0,
        ];
        let exploitation_seed = (0..10_000)
            .map(|index| format!("v43-exploit-{index}"))
            .find(|seed| unit_interval(faasrank_stable_hash(seed, &context)) >= 0.1)
            .expect("find deterministic exploitation seed");
        scheduler.operational_algorithm_seed = exploitation_seed;
        assert_eq!(
            scheduler.faasrank_ready_faithful_operational_penalty(player, 1, &state),
            0.0
        );

        let exploration_seed = (0..100_000)
            .map(|index| format!("v43-explore-{index}"))
            .find(|seed| {
                unit_interval(faasrank_stable_hash(seed, &context)) < 0.1
                    && faasrank_stable_hash(
                        seed,
                        &[
                            scheduler.operational_frame as u64,
                            player.req_id as u64,
                            player.fn_id as u64,
                            1,
                        ],
                    ) as usize
                        % 2
                        == 1
            })
            .expect("find deterministic non-head exploration seed");
        scheduler.operational_algorithm_seed = exploration_seed;
        assert_eq!(
            scheduler.faasrank_ready_faithful_operational_penalty(player, 0, &state),
            0.0
        );
        assert!(
            scheduler.faasrank_ready_faithful_operational_penalty(player, 0, &state)
                < scheduler.faasrank_ready_faithful_operational_penalty(player, 1, &state)
        );
    }

    #[test]
    fn ready_faasrank_ocs_borda_uses_exact_registered_votes() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].cpu_utilization = 0.9;
        scheduler.node_snapshots[0].memory_utilization = 0.9;
        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.1;
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.existing_containers.insert((player.fn_id, 1));
        let state = empty_operational_state();

        for (expert, faasrank_votes) in [
            (OperationalExpertProxy::FaasrankReadyOcsBorda, 1),
            (OperationalExpertProxy::Faasrank2ReadyOcsBorda, 2),
        ] {
            scheduler.settings.operational_expert_proxy = expert;
            for node_id in [0, 1] {
                let faasrank_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                        scheduler.faasrank_operational_penalty(player, candidate, &state)
                    });
                let ocs_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.ocs_current_demand_operational_penalty(player, candidate, &state)
                });
                let mut ranks = vec![faasrank_rank; faasrank_votes];
                ranks.push(ocs_rank);
                let expected = scheduler.ordinal_borda_penalty(&ranks, 2);
                assert_eq!(
                    scheduler.faasrank_ready_ocs_borda_operational_penalty(
                        player,
                        node_id,
                        &state,
                        faasrank_votes,
                    ),
                    expected
                );
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    expected
                );
            }
        }
    }

