    #[test]
    fn ordinal_rank_evaluates_each_candidate_once_and_preserves_ties() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![3, 1, 2, 0]);
        let mut evaluations = 0usize;
        let rank = scheduler.operational_ordinal_rank(player, 2, |candidate| {
            evaluations += 1;
            match candidate {
                0 => 3.0,
                1 | 2 => 1.0,
                3 => 2.0,
                _ => f32::INFINITY,
            }
        });
        assert_eq!(rank, 1.0, "node 1 wins the equal-score node-id tie");
        assert_eq!(evaluations, 4, "each candidate score is evaluated once");
    }

    #[test]
    fn ordinal_borda_uses_exact_integer_vote_multiplicity() {
        let (scheduler, _) = operational_tie_scheduler();
        assert_eq!(scheduler.ordinal_borda_penalty(&[1.0, 2.0, 3.0], 4), 33.0);
        assert_eq!(
            scheduler.ordinal_borda_penalty(&[1.0, 1.0, 2.0, 3.0], 4),
            38.0
        );
        assert_eq!(
            scheduler.ordinal_borda_penalty(&[1.0, 1.0, 1.0, 2.0, 3.0], 4),
            43.0
        );
    }

    #[test]
    fn ordinal_profile_routers_switch_only_at_repeated_current_demand() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.node_snapshots[0].resident_tasks = 6;
        scheduler.node_snapshots[1].memory_utilization = 0.7;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        let state = empty_operational_state();

        scheduler.player_function_demand.insert(player.fn_id, 1);
        for node_id in 0..2 {
            assert_eq!(
                scheduler.equal3_singleton_faasrank2_jiagu_burst_operational_penalty(
                    player, node_id, &state,
                ),
                scheduler.faasrank_jiagu_load_least_borda_current_demand_operational_penalty(
                    player, node_id, &state,
                )
            );
            assert_eq!(
                scheduler.faasrank2_jiagu_singleton_equal3_burst_operational_penalty(
                    player, node_id, &state,
                ),
                scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, false,
                )
            );
            assert_eq!(
                scheduler.faasrank2_jiagu_load_least_singleton_equal3_burst_operational_penalty(
                    player, node_id, &state,
                ),
                scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, true,
                )
            );
        }

        scheduler.player_function_demand.insert(player.fn_id, 2);
        for node_id in 0..2 {
            assert_eq!(
                scheduler.equal3_singleton_faasrank2_jiagu_burst_operational_penalty(
                    player, node_id, &state,
                ),
                scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, false,
                )
            );
            let equal_three = scheduler
                .faasrank_jiagu_load_least_borda_current_demand_operational_penalty(
                    player, node_id, &state,
                );
            assert_eq!(
                scheduler.faasrank2_jiagu_singleton_equal3_burst_operational_penalty(
                    player, node_id, &state,
                ),
                equal_three
            );
            assert_eq!(
                scheduler.faasrank2_jiagu_load_least_singleton_equal3_burst_operational_penalty(
                    player, node_id, &state,
                ),
                equal_three
            );
        }
    }

    #[test]
    fn singleton_state_gate_uses_only_feasible_warm_container_state() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.player_function_demand.insert(player.fn_id, 1);
        let state = empty_operational_state();

        for node_id in 0..2 {
            let with_load = scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                player, node_id, &state, 2, true,
            );
            let without_load = scheduler
                .faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, false,
                );
            assert_eq!(
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, false, false,
                ),
                with_load
            );
            assert_eq!(
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, false, true,
                ),
                without_load
            );
        }

        scheduler.warm_containers.insert((player.fn_id, 0));
        for node_id in 0..2 {
            let with_load = scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                player, node_id, &state, 2, true,
            );
            let without_load = scheduler
                .faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, false,
                );
            assert_eq!(
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, false, false,
                ),
                without_load
            );
            assert_eq!(
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, true, false,
                ),
                with_load
            );
        }

        scheduler.idle_warm_containers.insert((player.fn_id, 0));
        for node_id in 0..2 {
            assert_eq!(
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, true, false,
                ),
                scheduler.faasrank_majority_borda_current_demand_operational_penalty(
                    player, node_id, &state, 2, false,
                )
            );
        }

        scheduler.player_function_demand.insert(player.fn_id, 2);
        for node_id in 0..2 {
            let equal_three = scheduler
                .faasrank_jiagu_load_least_borda_current_demand_operational_penalty(
                    player, node_id, &state,
                );
            for (idle, complement) in [(false, false), (true, false), (false, true)] {
                assert_eq!(
                    scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                        player, node_id, &state, idle, complement,
                    ),
                    equal_three
                );
            }
        }
    }

    #[test]
    fn queue_banded_router_uses_low_middle_and_high_pressure_profiles() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.player_function_demand.insert(player.fn_id, 1);
        scheduler.warm_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();

        for node_id in 0..2 {
            assert_eq!(
                scheduler.queue_banded_warm_load_least_idle_warm_operational_penalty(
                    player, node_id, &state, 8.0,
                ),
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, true, false,
                )
            );
        }

        scheduler.node_snapshots[0].pending_tasks = 10;
        scheduler.node_snapshots[1].pending_tasks = 10;
        for node_id in 0..2 {
            assert_eq!(
                scheduler.queue_banded_warm_load_least_idle_warm_operational_penalty(
                    player, node_id, &state, 8.0,
                ),
                scheduler.load_least_current_demand_operational_penalty(node_id, &state)
            );
        }

        scheduler.node_snapshots[0].pending_tasks = 32;
        scheduler.node_snapshots[1].pending_tasks = 32;
        for node_id in 0..2 {
            assert_eq!(
                scheduler.queue_banded_warm_load_least_idle_warm_operational_penalty(
                    player, node_id, &state, 8.0,
                ),
                scheduler.state_gated_singleton_borda_equal3_burst_operational_penalty(
                    player, node_id, &state, false, false,
                )
            );
        }
    }

