    #[test]
    fn v161_jit_parent_tail_uses_all_parents_and_includes_the_exact_boundary() {
        let mut scheduler = ScheNashScheduler::new();
        let request_id = 41;
        let child_fn_id = 3;
        scheduler
            .function_profiles
            .insert(child_fn_id, function_profile(child_fn_id, 1.0, 1.0, 3));
        scheduler.function_parents.insert(child_fn_id, vec![2, 1]);
        scheduler.jit_parent_task_observations.insert(
            PlayerId {
                req_id: request_id,
                fn_id: 1,
            },
            JitParentTaskObservation {
                frame: 4,
                node_id: 0,
                left_calc: 11.0,
                active: true,
            },
        );
        scheduler.jit_parent_task_observations.insert(
            PlayerId {
                req_id: request_id,
                fn_id: 2,
            },
            JitParentTaskObservation {
                frame: 4,
                node_id: 1,
                left_calc: 12.0,
                active: true,
            },
        );
        let current = HashMap::from([
            (
                PlayerId {
                    req_id: request_id,
                    fn_id: 1,
                },
                JitParentTaskObservation {
                    frame: 5,
                    node_id: 0,
                    left_calc: 10.0,
                    active: true,
                },
            ),
            (
                PlayerId {
                    req_id: request_id,
                    fn_id: 2,
                },
                JitParentTaskObservation {
                    frame: 5,
                    node_id: 1,
                    left_calc: 6.0,
                    active: true,
                },
            ),
        ]);

        assert_eq!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &current,
                5,
            ),
            JitParentTailDecision::Admit {
                unfinished_parent_count: 2,
                max_predicted_remaining_frames: 10.0,
                max_tail_to_cold_start_ratio: 1.0,
            }
        );
    }

    #[test]
    fn v161_jit_parent_tail_fails_closed_on_history_activity_service_and_long_tail() {
        let mut scheduler = ScheNashScheduler::new();
        let request_id = 42;
        let parent = PlayerId {
            req_id: request_id,
            fn_id: 1,
        };
        let child_fn_id = 3;
        scheduler
            .function_profiles
            .insert(child_fn_id, function_profile(child_fn_id, 1.0, 1.0, 3));
        scheduler.function_parents.insert(child_fn_id, vec![1]);
        let active_current = JitParentTaskObservation {
            frame: 5,
            node_id: 0,
            left_calc: 10.0,
            active: true,
        };

        assert!(matches!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &HashMap::new(),
                5,
            ),
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::MissingCurrent,
                ..
            }
        ));

        let current = HashMap::from([(parent, active_current)]);
        assert!(matches!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &current,
                5,
            ),
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::MissingPreviousOrNonconsecutive,
                ..
            }
        ));

        scheduler.jit_parent_task_observations.insert(
            parent,
            JitParentTaskObservation {
                frame: 4,
                node_id: 0,
                left_calc: 11.0,
                active: false,
            },
        );
        assert!(matches!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &current,
                5,
            ),
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::Inactive,
                ..
            }
        ));

        scheduler.jit_parent_task_observations.insert(
            parent,
            JitParentTaskObservation {
                frame: 4,
                node_id: 0,
                left_calc: 10.0,
                active: true,
            },
        );
        assert!(matches!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &current,
                5,
            ),
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::ZeroService,
                ..
            }
        ));

        scheduler.jit_parent_task_observations.insert(
            parent,
            JitParentTaskObservation {
                frame: 4,
                node_id: 0,
                left_calc: 10.5,
                active: true,
            },
        );
        assert_eq!(
            scheduler.jit_parent_tail_decision(
                request_id,
                &HashMap::new(),
                child_fn_id,
                &current,
                5,
            ),
            JitParentTailDecision::Reject {
                reason: JitParentTailRejection::TailLongerThanColdStart,
                max_predicted_remaining_frames: Some(20.0),
                max_tail_to_cold_start_ratio: Some(2.0),
            }
        );
    }

    #[test]
    fn v152_stable_function_affinity_is_order_invariant_and_function_specific() {
        let (mut scheduler, player) = operational_tie_scheduler();
        let state = empty_operational_state();
        scheduler.settings.operational_expert_proxy =
            OperationalExpertProxy::SrptReadyStableFunctionAffinity;
        scheduler.feasible_nodes.insert(player, vec![1, 0]);

        let penalties = |scheduler: &ScheNashScheduler, player: PlayerId| {
            (0..2)
                .map(|node_id| {
                    scheduler.operational_completion_penalty(player, node_id, &state, true)
                })
                .collect::<Vec<_>>()
        };
        let first = penalties(&scheduler, player);
        assert_eq!(first.iter().filter(|&&value| value == 0.0).count(), 1);

        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        assert_eq!(penalties(&scheduler, player), first);

        let other = PlayerId {
            req_id: player.req_id.saturating_add(1),
            fn_id: player.fn_id.saturating_add(1),
        };
        scheduler.feasible_nodes.insert(other, vec![0, 1]);
        let other_penalties = penalties(&scheduler, other);
        assert_eq!(
            other_penalties
                .iter()
                .filter(|&&value| value == 0.0)
                .count(),
            1
        );
        assert_eq!(
            OperationalExpertProxy::from_name("srpt_ready_stable_function_affinity"),
            OperationalExpertProxy::SrptReadyStableFunctionAffinity
        );
    }

    #[test]
    fn srpt_order_is_remaining_work_then_critical_path_then_stable_id() {
        let (mut scheduler, _) = operational_tie_scheduler();
        let shortest = PlayerId {
            req_id: 8,
            fn_id: 4,
        };
        let tied_high_rank = PlayerId {
            req_id: 10,
            fn_id: 6,
        };
        let tied_low_id = PlayerId {
            req_id: 9,
            fn_id: 2,
        };
        let tied_high_id = PlayerId {
            req_id: 9,
            fn_id: 3,
        };
        for player in [tied_high_rank, tied_low_id, tied_high_id] {
            scheduler.player_request_remaining_work.insert(player, 3.0);
        }
        scheduler
            .player_request_remaining_work
            .insert(shortest, 1.0);
        scheduler
            .player_critical_path_rank
            .insert(tied_high_rank, 5.0);
        scheduler.player_critical_path_rank.insert(tied_low_id, 2.0);
        scheduler
            .player_critical_path_rank
            .insert(tied_high_id, 2.0);

        let mut players = vec![tied_high_id, tied_low_id, tied_high_rank, shortest];
        scheduler.sort_srpt_players(&mut players);

        assert_eq!(
            players,
            vec![shortest, tied_high_rank, tied_low_id, tied_high_id]
        );
    }

    #[test]
    fn srpt_experts_delegate_to_frozen_placement_rules_and_exact_borda() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].cpu_utilization = 0.85;
        scheduler.node_snapshots[0].memory_utilization = 0.75;
        scheduler.node_snapshots[0].pending_tasks = 6;
        scheduler.node_snapshots[1].cpu_utilization = 0.2;
        scheduler.node_snapshots[1].memory_utilization = 0.25;
        scheduler.node_snapshots[1].pending_tasks = 1;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();

        for node_id in 0..2 {
            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyHikuLoadFaithful;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                scheduler.hiku_load_faithful_operational_penalty(player, node_id, &state, true,)
            );

            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyOcsCurrentDemand;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                scheduler.ocs_current_demand_operational_penalty(player, node_id, &state)
            );

            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyOrionLoadFaithful;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                scheduler.orion_load_faithful_operational_penalty(player, node_id, &state)
            );

            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyFaasrankFaithful;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                scheduler.faasrank_ready_faithful_operational_penalty(player, node_id, &state,)
            );

            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyLoadLeastCurrentDemand;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                scheduler.load_least_current_demand_operational_penalty(node_id, &state)
            );

            let faasrank_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                scheduler.faasrank_ready_faithful_operational_penalty(player, candidate, &state)
            });
            let load_least_rank =
                scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.load_least_current_demand_operational_penalty(candidate, &state)
                });
            let expected_faasrank_load_least =
                scheduler.ordinal_borda_penalty(&[faasrank_rank, load_least_rank], 2);
            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyFaasrankLoadLeastBorda;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                expected_faasrank_load_least
            );

            let hiku_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                scheduler.hiku_load_faithful_operational_penalty(player, candidate, &state, true)
            });
            let ocs_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                scheduler.ocs_current_demand_operational_penalty(player, candidate, &state)
            });
            let expected = scheduler.ordinal_borda_penalty(&[hiku_rank, ocs_rank], 2);
            scheduler.settings.operational_expert_proxy =
                OperationalExpertProxy::SrptReadyHikuOcsBorda;
            assert_eq!(
                scheduler.operational_completion_penalty(player, node_id, &state, true),
                expected
            );
        }
    }

    #[test]
    fn v59_srpt_borda_profiles_use_exact_preregistered_vote_multiplicity() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].cpu_utilization = 0.85;
        scheduler.node_snapshots[0].memory_utilization = 0.75;
        scheduler.node_snapshots[0].pending_tasks = 6;
        scheduler.node_snapshots[1].cpu_utilization = 0.2;
        scheduler.node_snapshots[1].memory_utilization = 0.25;
        scheduler.node_snapshots[1].pending_tasks = 1;
        scheduler.existing_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();
        let profiles = [
            (OperationalExpertProxy::SrptReadyHiku2OcsBorda, 2, 1),
            (OperationalExpertProxy::SrptReadyHiku3OcsBorda, 3, 1),
            (OperationalExpertProxy::SrptReadyHikuOcs2Borda, 1, 2),
            (OperationalExpertProxy::SrptReadyHikuOcs3Borda, 1, 3),
        ];

        for node_id in 0..2 {
            let hiku_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                scheduler.hiku_load_faithful_operational_penalty(player, candidate, &state, true)
            });
            let ocs_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                scheduler.ocs_current_demand_operational_penalty(player, candidate, &state)
            });
            assert_ne!(hiku_rank, ocs_rank);

            for (profile, hiku_votes, ocs_votes) in profiles {
                let mut ranks = vec![hiku_rank; hiku_votes];
                ranks.extend(std::iter::repeat(ocs_rank).take(ocs_votes));
                let expected = scheduler.ordinal_borda_penalty(&ranks, 2);
                scheduler.settings.operational_expert_proxy = profile;
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    expected
                );
            }
        }
    }

