    #[test]
    fn v108_complete_certificate_uses_service_proxy_not_load_least_score() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15CriticalService10InitializerOnlyGuard64DualWindowSafePareto;
        scheduler.terminal_functions.insert(player.fn_id);
        scheduler.function_children.insert(player.fn_id, Vec::new());
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots = vec![
            NodeSnapshot {
                cpu_capacity: 1.0,
                memory_limit: 1.0,
                ..NodeSnapshot::default()
            },
            NodeSnapshot {
                cpu_capacity: 100.0,
                pending_tasks: 1,
                memory_limit: 1.0,
                ..NodeSnapshot::default()
            },
        ];
        scheduler.available_container_memory = vec![1.0, 1.0];
        scheduler.existing_containers.insert((player.fn_id, 1));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler
            .player_node_locality_scores
            .insert((player, 0), 1.0);
        scheduler
            .player_node_locality_scores
            .insert((player, 1), 1.0);
        let players = [player];
        let base = vec![NodeAggregate::default(); 2];
        let mut anchor = AssignmentState::new(base.clone(), 1);
        anchor.add(
            player,
            0,
            &scheduler.existing_containers,
            &scheduler.function_profiles,
        );
        let mut alternative = AssignmentState::new(base.clone(), 1);
        alternative.add(
            player,
            1,
            &scheduler.existing_containers,
            &scheduler.function_profiles,
        );
        let critical = HashSet::from([player]);
        let anchor_proxy =
            scheduler.v108_complete_critical_service_proxy_sum(&players, &base, &anchor, &critical);
        let alternative_proxy = scheduler.v108_complete_critical_service_proxy_sum(
            &players,
            &base,
            &alternative,
            &critical,
        );
        let signal = PriceSignal {
            baseline_prices: vec![0.3, 0.3],
            adjusted_prices: vec![0.3, 0.3],
            node_congestion_premiums: vec![0.0, 0.0],
            global_load: 0.0,
            network_congestion: 1.0,
        };
        let decision = scheduler.v108_critical_service_dominance_decision(
            &players,
            &base,
            &signal,
            &anchor,
            &alternative,
            1,
            anchor_proxy,
            alternative_proxy,
            false,
            None,
            None,
        );

        assert!(anchor_proxy.unwrap() > alternative_proxy.unwrap());
        assert!(
            decision.alternative_load_least_score.unwrap()
                <= decision.anchor_load_least_score.unwrap()
        );
        assert!(decision.accepted, "{}", decision.reason);
        assert_eq!(decision.reason, "accepted");

        let interference_rejected = scheduler.v108_critical_service_dominance_decision(
            &players,
            &base,
            &signal,
            &anchor,
            &alternative,
            1,
            anchor_proxy,
            alternative_proxy,
            true,
            Some(1.0),
            Some(1.1),
        );
        assert!(!interference_rejected.accepted);
        assert_eq!(
            interference_rejected.reason,
            "alternative_admitted_interference_worse"
        );

        let interference_accepted = scheduler.v108_critical_service_dominance_decision(
            &players,
            &base,
            &signal,
            &anchor,
            &alternative,
            1,
            anchor_proxy,
            alternative_proxy,
            true,
            Some(1.0),
            Some(1.0),
        );
        assert!(interference_accepted.accepted);
    }

    fn update_v107_arrivals(
        scheduler: &mut ScheNashScheduler,
        frame: usize,
        request_ids: impl IntoIterator<Item = ReqId>,
    ) {
        scheduler.operational_frame = frame;
        scheduler.update_operational_causal_arrival_shock(frame, request_ids);
    }

    #[test]
    fn v109_causal_horizons_expire_at_the_preregistered_deadline() {
        let profiles = [
            (
                OperationalExpertProxy::FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon25CriticalService10InitializerOnlyGuard64DualWindowSafePareto,
                25usize,
            ),
            (
                OperationalExpertProxy::FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50CriticalService10InitializerOnlyGuard64DualWindowSafePareto,
                50usize,
            ),
        ];
        for (profile, active_frames) in profiles {
            let mut scheduler = ScheNashScheduler::new();
            scheduler.settings.operational_expert_proxy = profile;
            let mut next_request_id = 0usize;
            for frame in 0..CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES {
                let count = if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES {
                    1
                } else if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES + 10 {
                    2
                } else {
                    1
                };
                let arrivals = (next_request_id..next_request_id + count).collect::<Vec<ReqId>>();
                next_request_id += count;
                update_v107_arrivals(&mut scheduler, frame, arrivals);
            }

            let detected_frame = CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES - 1;
            let expected_until = detected_frame + active_frames - 1;
            assert_eq!(
                scheduler.operational_arrival_shock_until_frame,
                Some(expected_until)
            );
            scheduler.operational_frame = expected_until;
            assert!(scheduler.operational_causal_arrival_shock_active());
            scheduler.operational_frame = expected_until + 1;
            assert!(!scheduler.operational_causal_arrival_shock_active());
        }
    }

    #[test]
    fn v107_causal_arrival_shock_is_first_seen_only_exact_and_fail_closed() {
        let mut shock15 = ScheNashScheduler::new();
        shock15.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15ResourceParetoInitializerOnlyGuard64DualWindowSafePareto;
        let mut shock20 = ScheNashScheduler::new();
        shock20.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock20ResourceParetoInitializerOnlyGuard64DualWindowSafePareto;

        let mut next_request_id = 0usize;
        for frame in 0..CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES {
            let arrivals = [next_request_id];
            next_request_id += 1;
            update_v107_arrivals(&mut shock15, frame, arrivals);
            update_v107_arrivals(&mut shock20, frame, arrivals);
            assert!(!shock15.operational_causal_arrival_shock_active());
            assert!(!shock20.operational_causal_arrival_shock_active());
        }
        for frame in CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES..CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES {
            let count = if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES + 10 {
                2
            } else {
                1
            };
            let arrivals = (next_request_id..next_request_id + count).collect::<Vec<_>>();
            next_request_id += count;
            update_v107_arrivals(&mut shock15, frame, arrivals.iter().copied());
            update_v107_arrivals(&mut shock20, frame, arrivals.iter().copied());
        }

        assert!(shock15.operational_arrival_shock_history_complete);
        assert_eq!(shock15.operational_arrival_shock_baseline_count, 80);
        assert_eq!(shock15.operational_arrival_shock_recent_count, 30);
        assert!(shock15.operational_causal_arrival_shock_active());
        assert_eq!(shock15.operational_arrival_shock_until_frame, Some(198));
        assert!(!shock20.operational_causal_arrival_shock_active());

        // Re-observing an existing request in the same frame and then
        // removing every request cannot create an arrival or cancel the
        // already detected interval.
        let seen_before_reobservation = shock15.operational_seen_request_ids.len();
        update_v107_arrivals(&mut shock15, 99, [0]);
        assert_eq!(
            shock15.operational_seen_request_ids.len(),
            seen_before_reobservation
        );
        assert_eq!(
            shock15.operational_arrival_shock_first_seen_current_frame,
            1
        );
        update_v107_arrivals(&mut shock15, 100, std::iter::empty());
        assert_eq!(
            shock15.operational_arrival_shock_first_seen_current_frame,
            0
        );
        assert!(shock15.operational_causal_arrival_shock_active());
        shock15.operational_frame = 199;
        assert!(!shock15.operational_causal_arrival_shock_active());

        // The stricter profile activates at exact 2.0x rate equality.
        let mut exact_shock20 = ScheNashScheduler::new();
        exact_shock20.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock20ResourceParetoInitializerOnlyGuard64DualWindowSafePareto;
        let mut exact_request_id = 0usize;
        for frame in 0..CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES {
            let count = if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES {
                1
            } else {
                2
            };
            let arrivals = (exact_request_id..exact_request_id + count).collect::<Vec<ReqId>>();
            exact_request_id += count;
            update_v107_arrivals(&mut exact_shock20, frame, arrivals);
        }
        assert_eq!(exact_shock20.operational_arrival_shock_baseline_count, 80);
        assert_eq!(exact_shock20.operational_arrival_shock_recent_count, 40);
        assert!(exact_shock20.operational_causal_arrival_shock_active());

        // Diagnostics are emitted for every scheduling window, including
        // windows with no feasible players and therefore no initializer call.
        let (_, _, stats) = exact_shock20.solve(
            &[],
            Vec::new(),
            PriceSignal {
                baseline_prices: Vec::new(),
                adjusted_prices: Vec::new(),
                node_congestion_premiums: Vec::new(),
                global_load: 0.0,
                network_congestion: 1.0,
            },
        );
        assert_eq!(stats.termination_reason, "no_players");
        assert!(stats.causal_arrival_shock_gate_enabled);
        assert!(stats.causal_arrival_shock_active);
        assert!(stats.causal_arrival_shock_history_complete);
        assert_eq!(stats.causal_arrival_shock_baseline_count, 80);
        assert_eq!(stats.causal_arrival_shock_recent_count, 40);
        assert_eq!(stats.causal_arrival_shock_threshold_numerator, Some(2));
        assert_eq!(stats.causal_arrival_shock_threshold_denominator, Some(1));
        assert_eq!(stats.causal_arrival_shock_until_frame, Some(198));
    }

    #[test]
    fn v116_arrival_phase_uses_adjacent_disjoint_windows_and_fails_closed() {
        let profile = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50AdmittedWork10CompleteInterferenceParetoRisingPhaseInitializerOnlyGuard64DualWindowSafePareto;
        let mut rising = ScheNashScheduler::new();
        rising.settings.operational_expert_proxy = profile;
        assert_eq!(rising.operational_non_decreasing_arrival_phase(), None);

        let mut next_request_id = 0usize;
        for frame in 0..CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES {
            let count = if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES {
                1
            } else {
                2
            };
            let arrivals = (next_request_id..next_request_id + count).collect::<Vec<ReqId>>();
            next_request_id += count;
            update_v107_arrivals(&mut rising, frame, arrivals);
        }
        assert_eq!(
            rising.operational_non_decreasing_arrival_phase(),
            Some((20, 40, true))
        );
        assert!(rising.operational_causal_arrival_shock_active());

        // A missing observation frame cannot be imputed as zero and resets
        // the fixed causal history, so the phase gate becomes unavailable.
        update_v107_arrivals(
            &mut rising,
            CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES + 1,
            std::iter::empty(),
        );
        assert_eq!(rising.operational_non_decreasing_arrival_phase(), None);
        let mut incomplete_stats = SolveStats::default();
        rising.record_causal_arrival_shock_stats(&mut incomplete_stats);
        assert!(incomplete_stats.arrival_phase_gate_enabled);
        assert!(!incomplete_stats.arrival_phase_history_complete);
        assert_eq!(incomplete_stats.arrival_phase_previous_count, None);
        assert_eq!(incomplete_stats.arrival_phase_current_count, None);
        assert!(!incomplete_stats.arrival_phase_non_decreasing);

        // Freeze a valid shock whose immediately preceding 20-frame count is
        // higher than its current 20-frame count.  V115 reaches alternative
        // construction, while V116 atomically preserves the exact anchor.
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = profile;
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 1));
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.node_snapshots[0].pending_tasks = 10;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let mut declining_request_id = 0usize;
        for frame in 0..CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES {
            let count = if frame < 60 {
                0
            } else if frame < CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES {
                3
            } else {
                2
            };
            let arrivals =
                (declining_request_id..declining_request_id + count).collect::<Vec<ReqId>>();
            declining_request_id += count;
            update_v107_arrivals(&mut scheduler, frame, arrivals);
        }
        assert!(scheduler.operational_causal_arrival_shock_active());
        assert_eq!(
            scheduler.operational_non_decreasing_arrival_phase(),
            Some((60, 40, false))
        );

        let players = [player];
        let base = vec![NodeAggregate::default(); 2];
        let signal = PriceSignal {
            baseline_prices: vec![0.3, 0.3],
            adjusted_prices: vec![0.3, 0.3],
            node_congestion_premiums: vec![0.0, 0.0],
            global_load: 0.0,
            network_congestion: 1.0,
        };
        let mut anchor_stats = SolveStats::default();
        let mut anchor_no_feasible = HashSet::new();
        let anchor = scheduler.initialize_faasrank_native_faithful_assignment(
            &players,
            base.clone(),
            &mut anchor_stats,
            &mut anchor_no_feasible,
        );

        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50AdmittedWork10CompleteInterferenceParetoInitializerOnlyGuard64DualWindowSafePareto;
        let mut v115_stats = SolveStats::default();
        let mut v115_no_feasible = HashSet::new();
        let _ = scheduler.initialize_v97_low_density_load_assignment(
            &players,
            base.clone(),
            &signal,
            &mut v115_stats,
            &mut v115_no_feasible,
        );
        assert!(!v115_stats.arrival_phase_gate_enabled);
        assert!(v115_stats.load_least_alternative_assignment_hash.is_some());

        scheduler.settings.operational_expert_proxy = profile;
        let mut v116_stats = SolveStats::default();
        let mut v116_no_feasible = HashSet::new();
        let selected = scheduler.initialize_v97_low_density_load_assignment(
            &players,
            base,
            &signal,
            &mut v116_stats,
            &mut v116_no_feasible,
        );
        assert_eq!(selected.assignments, anchor.assignments);
        assert!(v116_stats.arrival_phase_gate_enabled);
        assert!(v116_stats.arrival_phase_history_complete);
        assert_eq!(v116_stats.arrival_phase_previous_count, Some(60));
        assert_eq!(v116_stats.arrival_phase_current_count, Some(40));
        assert!(!v116_stats.arrival_phase_non_decreasing);
        assert_eq!(
            v116_stats.load_least_dominance_reason,
            "causal_arrival_phase_declining"
        );
        assert_eq!(v116_stats.load_least_alternative_assignment_hash, None);
        assert_eq!(
            v116_stats.load_least_selected_assignment_hash,
            v116_stats.load_least_anchor_assignment_hash
        );
    }

    #[test]
    fn v107_inactive_shock_dispatches_exact_anchor_even_below_static_density_gate() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15ResourceParetoInitializerOnlyGuard64DualWindowSafePareto;
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 1));
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.node_snapshots[0].pending_tasks = 10;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let players = [player];
        let base = vec![NodeAggregate::default(); 2];
        let signal = PriceSignal {
            baseline_prices: vec![0.3, 0.3],
            adjusted_prices: vec![0.3, 0.3],
            node_congestion_premiums: vec![0.0, 0.0],
            global_load: 0.0,
            network_congestion: 1.0,
        };
        let mut anchor_stats = SolveStats::default();
        let mut anchor_no_feasible = HashSet::new();
        let anchor = scheduler.initialize_faasrank_native_faithful_assignment(
            &players,
            base.clone(),
            &mut anchor_stats,
            &mut anchor_no_feasible,
        );
        let mut stats = SolveStats::default();
        let mut no_feasible = HashSet::new();
        let selected = scheduler.initialize_v97_low_density_load_assignment(
            &players,
            base,
            &signal,
            &mut stats,
            &mut no_feasible,
        );

        assert_eq!(selected.assignments, anchor.assignments);
        assert!(stats.causal_arrival_shock_gate_enabled);
        assert!(!stats.causal_arrival_shock_active);
        assert_eq!(
            stats.load_least_dominance_reason,
            "causal_arrival_shock_inactive"
        );
        assert_eq!(
            stats.load_least_selected_assignment_hash,
            stats.load_least_anchor_assignment_hash
        );
        assert_eq!(stats.load_least_alternative_assignment_hash, None);

        // Once the causal gate is active, even a density above the legacy
        // upper gate reaches the guarded alternative construction.
        scheduler.operational_arrival_shock_until_frame = Some(99);
        scheduler.operational_frame = 0;
        scheduler.node_snapshots[0].pending_tasks = 100;
        let mut active_stats = SolveStats::default();
        let mut active_no_feasible = HashSet::new();
        let _ = scheduler.initialize_v97_low_density_load_assignment(
            &players,
            vec![NodeAggregate::default(); 2],
            &signal,
            &mut active_stats,
            &mut active_no_feasible,
        );
        assert!(active_stats.causal_arrival_shock_active);
        assert_ne!(
            active_stats.load_least_dominance_reason,
            "queue_density_not_below_threshold"
        );
        assert!(active_stats
            .load_least_alternative_assignment_hash
            .is_some());
    }

    fn v106_resource_safety_scheduler(
        profile: OperationalExpertProxy,
    ) -> (ScheNashScheduler, PlayerId, AssignmentState) {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = profile;
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 1));
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.function_children.insert(player.fn_id, Vec::new());
        scheduler
            .player_node_locality_scores
            .insert((player, 0), 1.0);
        scheduler
            .player_node_locality_scores
            .insert((player, 1), 1.0);
        scheduler.node_snapshots[0].pending_tasks = 20;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let state = AssignmentState::new(vec![NodeAggregate::default(); 2], 1);
        (scheduler, player, state)
    }

    #[test]
    fn v106_resource_pareto_gate_rejects_each_resource_loss_and_accepts_nonworse() {
        let profile = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyTerminalLoadBand8To24BidirectionalLocalityNoncriticalFrontierResourceParetoInitializerOnlyGuard64DualWindowSafePareto;
        let (mut scheduler, player, state) = v106_resource_safety_scheduler(profile);
        scheduler.node_snapshots[0].cpu_utilization = 0.2;
        scheduler.node_snapshots[0].memory_utilization = 0.2;

        scheduler.node_snapshots[1].cpu_utilization = 0.3;
        scheduler.node_snapshots[1].memory_utilization = 0.1;
        let cpu_loss =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(cpu_loss.node_id, 0);
        assert!(!cpu_loss.substituted);
        assert_eq!(cpu_loss.resource_headroom_rejected_candidate_count, 1);
        assert_eq!(cpu_loss.cpu_headroom_rejected_candidate_count, 1);
        assert_eq!(cpu_loss.memory_headroom_rejected_candidate_count, 0);
        assert_eq!(cpu_loss.resource_headroom_unavailable_candidate_count, 0);

        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.3;
        let memory_loss =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(memory_loss.node_id, 0);
        assert!(!memory_loss.substituted);
        assert_eq!(memory_loss.resource_headroom_rejected_candidate_count, 1);
        assert_eq!(memory_loss.cpu_headroom_rejected_candidate_count, 0);
        assert_eq!(memory_loss.memory_headroom_rejected_candidate_count, 1);

        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.1;
        let safe =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(safe.node_id, 1);
        assert!(safe.substituted);
        assert_eq!(safe.resource_headroom_rejected_candidate_count, 0);
    }

    #[test]
    fn v106_resource_bottleneck_sum_gate_allows_tradeoff_but_protects_both_aggregates() {
        let profile = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyTerminalLoadBand8To24BidirectionalLocalityNoncriticalFrontierResourceBottleneckSumInitializerOnlyGuard64DualWindowSafePareto;
        let (mut scheduler, player, state) = v106_resource_safety_scheduler(profile);
        scheduler.node_snapshots[0].cpu_utilization = 0.2;
        scheduler.node_snapshots[0].memory_utilization = 0.6;

        // Headroom changes from (0.8, 0.4) to (0.6, 0.6): CPU is
        // individually worse, but the bottleneck improves and the sum ties.
        scheduler.node_snapshots[1].cpu_utilization = 0.4;
        scheduler.node_snapshots[1].memory_utilization = 0.4;
        let balanced_tradeoff =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(balanced_tradeoff.node_id, 1);
        assert!(balanced_tradeoff.substituted);
        assert_eq!(
            balanced_tradeoff.resource_headroom_rejected_candidate_count,
            0
        );

        // (0.7, 0.4) preserves the bottleneck but reduces total headroom.
        scheduler.node_snapshots[1].cpu_utilization = 0.3;
        scheduler.node_snapshots[1].memory_utilization = 0.6;
        let total_loss =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(total_loss.node_id, 0);
        assert!(!total_loss.substituted);
        assert_eq!(total_loss.resource_total_rejected_candidate_count, 1);
        assert_eq!(total_loss.resource_bottleneck_rejected_candidate_count, 0);

        // (0.9, 0.3) preserves total headroom but worsens the bottleneck.
        scheduler.node_snapshots[1].cpu_utilization = 0.1;
        scheduler.node_snapshots[1].memory_utilization = 0.7;
        let bottleneck_loss =
            scheduler.v97_load_least_dominance_choice(player, 0, &[0, 1], &state, &VecDeque::new());
        assert_eq!(bottleneck_loss.node_id, 0);
        assert!(!bottleneck_loss.substituted);
        assert_eq!(bottleneck_loss.resource_total_rejected_candidate_count, 0);
        assert_eq!(
            bottleneck_loss.resource_bottleneck_rejected_candidate_count,
            1
        );
    }

    #[test]
    fn v105_current_frontier_protection_is_request_local_tie_safe_and_fail_closed() {
        let p = |req_id, fn_id| PlayerId { req_id, fn_id };
        let unique_max = p(1, 10);
        let lower_parallel = p(1, 11);
        let tied_a = p(2, 20);
        let tied_b = p(2, 21);
        let singleton = p(3, 30);
        let known_with_missing_peer = p(4, 40);
        let missing_peer = p(4, 41);
        let known_with_nonfinite_peer = p(5, 50);
        let nonfinite_peer = p(5, 51);
        let known_max_with_missing_peer = p(6, 60);
        let known_lower_with_missing_peer = p(6, 61);
        let second_missing_peer = p(6, 62);
        let players = vec![
            unique_max,
            lower_parallel,
            tied_a,
            tied_b,
            singleton,
            known_with_missing_peer,
            missing_peer,
            known_with_nonfinite_peer,
            nonfinite_peer,
            known_max_with_missing_peer,
            known_lower_with_missing_peer,
            second_missing_peer,
        ];
        let ranks = HashMap::from([
            (unique_max, 5.0),
            (lower_parallel, 3.0),
            (tied_a, 4.0),
            (tied_b, 4.0),
            (singleton, 1.0),
            (known_with_missing_peer, 2.0),
            (known_with_nonfinite_peer, 2.0),
            (nonfinite_peer, f32::NAN),
            (known_max_with_missing_peer, 7.0),
            (known_lower_with_missing_peer, 2.0),
        ]);

        let protected = current_frontier_critical_players(&players, &ranks);
        assert!(protected.contains(&unique_max));
        assert!(!protected.contains(&lower_parallel));
        assert!(protected.contains(&tied_a));
        assert!(protected.contains(&tied_b));
        assert!(protected.contains(&singleton));
        assert!(protected.contains(&known_with_missing_peer));
        assert!(protected.contains(&missing_peer));
        assert!(protected.contains(&known_with_nonfinite_peer));
        assert!(protected.contains(&nonfinite_peer));
        assert!(protected.contains(&known_max_with_missing_peer));
        assert!(!protected.contains(&known_lower_with_missing_peer));
        assert!(protected.contains(&second_missing_peer));
        assert_eq!(protected.len(), players.len() - 2);
    }

